const SINAVLAR = [{"kod": "5-s1", "sinif": 5, "ders": "ingilizce", "senaryo": 1, "deneme": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "bilgi kartı doldurma", "yonerge": "Read the texts quickly. Write in the boxes.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Olivia", "metin": "Hi! I'm Olivia. I'm from Canada. My best friend is Aiko. I love drawing pictures. I'm in the art club.", "aciklama": null}, {"kisi": "Jung", "metin": "My name is Jung. My favourite subject is Maths. I'm from South Korea. I love solving problems. I'm in the chess club.", "aciklama": null}]}, {"tur": "tablo", "basliklar": ["Name", "Country", "School club"], "satirlar": [["Olivia", {"bosluk": 1}, {"bosluk": 2}], ["Jung", {"bosluk": 3}, {"bosluk": 4}]], "baslik": "STUDENT CARDS"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Canada", "kabul": ["in Canada"], "aciklama": "Olivia'ın metnindeki \"I'm from Canada.\" cümlesi. Ülke \"I'm from ...\" kalıbından sonra gelir."}, {"soru": null, "cevap": "art club", "kabul": ["art", "the art club"], "aciklama": "Olivia'ın metnindeki \"I'm in the art club.\" cümlesi."}, {"soru": null, "cevap": "South Korea", "kabul": ["Korea", "in South Korea"], "aciklama": "Jung'un metnindeki \"I'm from South Korea.\" cümlesi."}, {"soru": null, "cevap": "chess club", "kabul": ["chess", "the chess club"], "aciklama": "Jung'un metnindeki \"I'm in the chess club.\" cümlesi. \"solving problems\" bir etkinliktir; kulüp adı \"in the ... club\" kalıbında geçer."}], "adlar": [], "puanlama": "Alt sorular (kutular) eşit puanlı. Bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz; boş ya da yanlış bilgi 0. Çözüm yolu: Önce iki metne hızlıca göz at; her metinde yalnızca ülkeyi ve kulübü ara (en sevdiği ders, arkadaşı gibi bilgileri atla), bulduğunu kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-5-s1-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Put the sentences in the correct order. Write C, D, E or F in the boxes.", "uyaran": [{"tur": "metin", "metin": "A) OK. Cheers!\nB) Hi, Mehriban! Do you like music?\nC) Great! I like playing the guitar. I'm in the music club.\nD) It's downstairs. Let's go together.\nE) Yes, I do. I love singing songs.\nF) Cool! Where is the music club?", "baslik": "At School"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "A"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "Pedro \"Do you like music?\" diye sorar; cevap \"Yes, I do.\" ile başlayan E cümlesidir."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "Pedro \"Great!\" der ve kendini anlatır (guitar, music club). Bu cümle E'den sonra gelir, çünkü Mehriban'ın müzik sevdiğine karşılık verir."}, {"soru": null, "cevap": "F", "kabul": [], "aciklama": "Mehriban \"music club\" sözünü duyunca \"Where is the music club?\" diye sorar; bu soru C'den sonra gelir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "\"Where...?\" sorusunun cevabı \"It's downstairs.\" cümlesidir (D); hemen ardından \"Let's go together.\" gelir."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan; yanlış ya da boş 0. Çözüm yolu: İlk ve son cümle verilmiş. Her soruya cevap olan cümleyi bul (Do you like...? → Yes, I do. Where...? → It's downstairs) ve sırayla yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-5-s1-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "kolay", "soru_tipi": "karışık harflerden kelime", "yonerge": "Write the words.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "We sing songs in the ........ club. (i u c m s)", "cevap": "music", "kabul": [], "aciklama": "Harfler: m-u-s-i-c (5 harf). Şarkı söylenen kulüp \"music club\" (müzik kulübü)."}, {"soru": "Jack is in the ........ club. (a m d r a)", "cevap": "drama", "kabul": [], "aciklama": "Harfler: d-r-a-m-a (5 harf). \"drama club\" (tiyatro kulübü); \"a\" harfi iki kez kullanılır."}, {"soru": "The ........ makes food in the canteen. (o k c o)", "cevap": "cook", "kabul": [], "aciklama": "Harfler: c-o-o-k (4 harf). Kantinde yemek yapan kişi aşçıdır: cook; \"o\" harfi iki kez kullanılır."}, {"soru": "We do experiments in the ........ lab. (n c e i s c e)", "cevap": "science", "kabul": [], "aciklama": "Harfler: s-c-i-e-n-c-e (7 harf). Deney yapılan laboratuvar science lab; \"c\" ve \"e\" ikişer kez kullanılır."}], "adlar": [], "puanlama": "Alt sorular (kelimeler) eşit puanlı. Kelime doğru yazılmışsa tam puan; tek harf hatası yarım puan; boş ya da yanlış kelime 0. Çözüm yolu: İpucu cümlesini oku, kelimeyi düşün ve kutulara yaz; kesişen harfler cevabını kontrol etmene yardım eder.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["makes:SARTLI", "sing:KOK"]}, "ornek": "We play ........ in the club. (s h c e s) → chess"}, {"id": "HZ-5-s1-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "hata düzeltme", "yonerge": "One word in each sentence is false. Write the correct sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "They is in the art club.", "cevap": "They are in the art club.", "kabul": [], "aciklama": "\"They\" ile \"are\" kullanılır; \"is\" yalnız he / she / it ile gelir."}, {"soru": "Jack is in an music club.", "cevap": "Jack is in a music club.", "kabul": [], "aciklama": "\"Music\" ünsüz sesiyle (m) başlar, bu yüzden \"a\" kullanılır; \"an\" ünlü sesi (a, e, i, o, u) için."}, {"soru": "You mustn't runs in the library.", "cevap": "You mustn't run in the library.", "kabul": [], "aciklama": "\"mustn't\" ve \"can't\" den sonra fiil yalın halde gelir: eat."}, {"soru": "Do you likes playing chess?", "cevap": "Do you like playing chess?", "kabul": [], "aciklama": "\"Do you\" ile başlayan soruda fiil yalın halde kalır: like. \"-s\" yalnız he / she / it cümlelerinde olur."}, {"soru": "Me favourite subject is Maths.", "cevap": "My favourite subject is Maths.", "kabul": [], "aciklama": "İyelik \"my\" (benim) ile yapılır. \"My favourite subject is ...\" kalıbı."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru cümle tam puan; hata düzeltilmiş ama başka bir yazım hatası varsa yarım puan; hata düzeltilmemişse ya da boşsa 0. Çözüm yolu: Cümleyi dikkatle oku, yanlış kelimeyi bul (is/are, a/an, fiilin biçimi, my/me) ve tüm cümleyi doğru yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["runs:SARTLI", "sentence:KOK", "word:KOK"]}, "ornek": "Wear you goggles. → Wear your goggles."}, {"id": "HZ-5-s1-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "örnek metinle benzer metin yazma", "yonerge": "Read the example. Look at the card. Write about Selin. Use \"She\".", "uyaran": [{"tur": "metin", "metin": "This is Roberto. He is from Italy. He is in the science club. He likes doing experiments.", "baslik": "Example"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Name", "Selin"], ["Country", "Türkiye"], ["School club", "film club"], ["Likes", "watching films"]], "baslik": "STUDENT CARD"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-5-s1-05.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "(name)", "cevap": "This is Selin.", "kabul": ["She is Selin."], "aciklama": "Örnekteki \"This is Roberto.\" cümlesi gibi: \"This is\" + kartın Name satırı."}, {"soru": "(country)", "cevap": "She is from Türkiye.", "kabul": ["Selin is from Türkiye."], "aciklama": "Örnekteki \"He is from Italy.\" gibi; Selin kız olduğu için \"She is from\" + Country satırı."}, {"soru": "(club)", "cevap": "She is in the film club.", "kabul": ["Selin is in the film club.", "She is a member of the film club."], "aciklama": "Örnekteki \"He is in the science club.\" gibi: \"She is in the\" + School club satırı."}, {"soru": "(likes)", "cevap": "She likes watching films.", "kabul": ["She loves watching films.", "Selin likes watching films."], "aciklama": "Örnekteki \"He likes doing experiments.\" gibi: \"She likes\" + Likes satırı."}], "adlar": ["Selin"], "puanlama": "Alt sorular (dört cümle) eşit puanlı. Karttaki bilgiyi doğru aktaran, anlaşılır cümle tam puan; bilgi doğru ama belirgin dil hatası (He, is eksik vb.) yarım puan; boş ya da yanlış bilgi 0. Anahtardakiler örnektir. Çözüm yolu: Önce örnek metne bak; her satırda ipucuna (name, country, club, likes) uygun kart bilgisini bul ve örnekteki gibi yaz. Selin kız olduğu için \"She\" kullan.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["films:SARTLI", "loves:SARTLI", "watching:SARTLI"]}}]}, {"kod": "5-s1d2", "sinif": 5, "ders": "ingilizce", "senaryo": 1, "deneme": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1d2-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "duyurulardan tablo doldurma", "yonerge": "Read the notices quickly. Write in the boxes.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Notice 1", "metin": "Do you like dancing? Join the folk dance club! We dance on Tuesday. Come to the sports field. The coach is Mr Wilson.", "aciklama": null}, {"kisi": "Notice 2", "metin": "Do you like films? Join the film club! We watch films on Wednesday. Come to the conference hall. The teacher is Ms Canan.", "aciklama": null}]}, {"tur": "tablo", "basliklar": ["Club", "Day", "Place"], "satirlar": [["Folk dance club", {"bosluk": 1}, {"bosluk": 2}], ["Film club", {"bosluk": 3}, {"bosluk": 4}]], "baslik": "SCHOOL CLUBS"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Tuesday", "kabul": ["on Tuesday"], "aciklama": "Birinci duyurudaki \"We dance on Tuesday.\" cümlesi. Gün \"on\" sözcüğünden sonra gelir."}, {"soru": null, "cevap": "sports field", "kabul": ["the sports field", "in the sports field"], "aciklama": "Birinci duyurudaki \"Come to the sports field.\" cümlesi. Yer, \"Come to\" sözlerinden sonra yazılır."}, {"soru": null, "cevap": "Wednesday", "kabul": ["on Wednesday"], "aciklama": "İkinci duyurudaki \"We watch films on Wednesday.\" cümlesi. Gün \"on\" sözcüğünden sonra gelir."}, {"soru": null, "cevap": "conference hall", "kabul": ["the conference hall", "in the conference hall", "hall"], "aciklama": "İkinci duyurudaki \"Come to the conference hall.\" cümlesi. Yer, \"Come to\" sözlerinden sonra yazılır."}], "adlar": ["Wilson", "Canan"], "puanlama": "Alt sorular (kutular) eşit puanlı. Bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz; boş ya da yanlış bilgi 0. Çözüm yolu: İki duyuruya hızlıca göz at; her duyuruda yalnızca günü ve yeri ara (öğretmenin adı gibi bilgileri atla), bulduğunu kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["films:SARTLI", "notices:SARTLI", "place:KOK"]}}, {"id": "HZ-5-s1d2-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "metne Wh- soruları", "yonerge": "Read the text and answer the questions.", "uyaran": [{"tur": "metin", "metin": "Hi! My name is Zeynep. I'm a student at this school. There are three clubs here: art club, music club and chess club. My favourite school club is music club. I love singing songs. The music club is downstairs. My best friend is Elif. She is in the art club. The art club is near the library.", "baslik": "Zeynep's School"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "How many clubs are there at Zeynep's school?", "cevap": "Three.", "kabul": ["There are three clubs.", "Three clubs.", "3"], "aciklama": "Metindeki \"There are three clubs here.\" cümlesi. \"How many\" sayı sorar; cevap \"three\" sayısıdır."}, {"soru": "Where is the music club?", "cevap": "It is downstairs.", "kabul": ["Downstairs.", "The music club is downstairs."], "aciklama": "Metindeki \"The music club is downstairs.\" cümlesi. \"Where\" yer sorar; cevap \"downstairs\" sözcüğüdür."}, {"soru": "Who is Zeynep's best friend?", "cevap": "Elif.", "kabul": ["Elif is Zeynep's best friend."], "aciklama": "Metindeki \"My best friend is Elif.\" cümlesi. \"Who\" kişi sorar; cevap kişinin adıdır."}, {"soru": "What is Zeynep's favourite school club?", "cevap": "The music club.", "kabul": ["Music club.", "It is the music club."], "aciklama": "Metindeki \"My favourite school club is music club.\" cümlesi. Elif'in kulübü (art club) değil, Zeynep'in sevdiği kulüp sorulur."}], "adlar": ["Zeynep", "Elif"], "puanlama": "Alt sorular eşit puanlı. Soruya doğru cevap veren kısa cevap ya da tam cümle tam puan; bilgi doğru ama belirgin dil hatası varsa yarım puan; yanlış ya da boş 0. Çözüm yolu: Önce metni oku; soru sözcüğüne bak (How many = sayı, Where = yer, Who = kişi, What = şey) ve cevabı metinde o bilgiyi veren cümlede ara.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["text:KOK"]}}, {"id": "HZ-5-s1d2-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "kolay", "soru_tipi": "harf ipuçlu cümle tamamlama", "yonerge": "Write the words.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "We eat food in the c _ _ _ _ _ _.", "cevap": "canteen", "kabul": [], "aciklama": "c-a-n-t-e-e-n (7 harf). Yemek yenen okul yeri canteen."}, {"soru": "Mr Wilson is the c _ _ _ _. He is in the sports field.", "cevap": "coach", "kabul": [], "aciklama": "c-o-a-c-h (5 harf). Spor alanında çalışan okul kişisi coach."}, {"soru": "I play the g _ _ _ _ _ in the music club.", "cevap": "guitar", "kabul": [], "aciklama": "g-u-i-t-a-r (6 harf). Müzik kulübünde çalınan çalgı guitar."}, {"soru": "Spain is a c _ _ _ _ _ _.", "cevap": "country", "kabul": [], "aciklama": "c-o-u-n-t-r-y (7 harf). Spain, France, Italy gibi yerler country (ülke)."}, {"soru": "Students read books in the l _ _ _ _ _ _.", "cevap": "library", "kabul": [], "aciklama": "l-i-b-r-a-r-y (7 harf). Kitap okunan okul yeri library."}], "adlar": ["Wilson"], "puanlama": "Alt sorular (kelimeler) eşit puanlı. Kelime doğru yazılmışsa tam puan; tek harf hatası yarım puan; boş ya da yanlış kelime 0. Çözüm yolu: Cümleyi oku, kelimeyi düşün; verilen ilk harf ve çizgi sayısı (her çizgi bir harf) cevabını kontrol etmene yardım eder.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "We draw pictures in the a _ _ club. → art"}, {"id": "HZ-5-s1d2-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "boşluğa soru sözcüğü yazma", "yonerge": "Write Who, What, Where or How many.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": ".......... is the music club? It is downstairs.", "cevap": "Where", "kabul": [], "aciklama": "Cevap bir yer verir (downstairs); yer soran soru sözcüğü Where."}, {"soru": ".......... is the coach? Mr Wilson is the coach.", "cevap": "Who", "kabul": [], "aciklama": "Cevap bir kişi adıdır (Mr Wilson); kişi soran soru sözcüğü Who."}, {"soru": ".......... clubs are there? There are two clubs.", "cevap": "How many", "kabul": [], "aciklama": "Cevap bir sayıdır (two); sayı soran kalıp How many."}, {"soru": ".......... is your favourite subject? It is Maths.", "cevap": "What", "kabul": [], "aciklama": "Cevap bir şeydir (Maths, bir ders); \"What is your favourite ...?\" kalıbı kullanılır."}], "adlar": ["Wilson"], "puanlama": "Alt sorular eşit puanlı. Doğru soru sözcüğü tam puan; yanlış ya da boş 0. Çözüm yolu: Boşluktan sonraki cevap cümlesini oku: cevap bir yerse Where, bir kişiyse Who, bir sayıysa How many, bir şeyse What yazılır.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": ".......... is the library? It is near the canteen. → Where"}, {"id": "HZ-5-s1d2-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "örnek metinle benzer metin yazma", "yonerge": "Read the example. Look at the card. Write about Edward. Use \"He\".", "uyaran": [{"tur": "metin", "metin": "This is Mateo. He is from Mexico. His favourite subject is Maths. He likes solving problems.", "baslik": "Example"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Name", "Edward"], ["Country", "England"], ["Favourite subject", "Science"], ["Likes", "playing volleyball"]], "baslik": "STUDENT CARD"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(name)", "cevap": "This is Edward.", "kabul": ["He is Edward."], "aciklama": "Örnekteki \"This is Mateo.\" cümlesi gibi: \"This is\" + kartın Name satırı."}, {"soru": "(country)", "cevap": "He is from England.", "kabul": ["Edward is from England."], "aciklama": "Örnekteki \"He is from Mexico.\" gibi: \"He is from\" + Country satırı."}, {"soru": "(subject)", "cevap": "His favourite subject is Science.", "kabul": ["He likes Science.", "Edward's favourite subject is Science."], "aciklama": "Örnekteki \"His favourite subject is Maths.\" gibi: \"His favourite subject is\" + Favourite subject satırı."}, {"soru": "(likes)", "cevap": "He likes playing volleyball.", "kabul": ["He loves playing volleyball.", "Edward likes playing volleyball."], "aciklama": "Örnekteki \"He likes solving problems.\" gibi: \"He likes\" + Likes satırı. Fiilden sonra -ing'li etkinlik gelir."}], "adlar": ["Edward", "Mateo"], "puanlama": "Alt sorular (dört cümle) eşit puanlı. Karttaki bilgiyi doğru aktaran, anlaşılır cümle tam puan; bilgi doğru ama belirgin dil hatası (is eksik, -s eksik vb.) yarım puan; boş ya da yanlış bilgi 0. Anahtardakiler örnektir. Çözüm yolu: Önce örnek metne bak; her satırda ipucuna (name, country, subject, likes) uygun kart bilgisini bul ve örnekteki gibi yaz. Edward erkek olduğu için \"He\" kullan.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["loves:SARTLI"]}}]}, {"kod": "5-s1d3", "sinif": 5, "ders": "ingilizce", "senaryo": 1, "deneme": 3, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1d3-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "kısa metinlerden kişi-görev-yer tablosu", "yonerge": "Read the texts quickly. Write in the boxes.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Mr Wilson", "metin": "Hi! I'm Mr Wilson. I love volleyball. I'm a coach. I'm in the sports field every day.", "aciklama": null}, {"kisi": "Ms Janet", "metin": "Hi! My name is Ms Janet. I make food for the students. I'm a cook. I'm in the canteen.", "aciklama": null}]}, {"tur": "tablo", "basliklar": ["Name", "Person at school", "Place"], "satirlar": [["Mr Wilson", {"bosluk": 1}, {"bosluk": 2}], ["Ms Janet", {"bosluk": 3}, {"bosluk": 4}]], "baslik": "PEOPLE AT SCHOOL"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "coach", "kabul": ["a coach", "the coach"], "aciklama": "Mr Wilson'ın metnindeki \"I'm a coach.\" cümlesi. Görev \"I'm a ...\" kalıbından sonra gelir; \"volleyball\" sevdiği şeydir, görev değildir."}, {"soru": null, "cevap": "sports field", "kabul": ["the sports field", "in the sports field"], "aciklama": "Mr Wilson'ın metnindeki \"I'm in the sports field every day.\" cümlesi. Yer \"I'm in the ...\" kalıbından sonra gelir."}, {"soru": null, "cevap": "cook", "kabul": ["a cook", "the cook"], "aciklama": "Ms Janet'in metnindeki \"I'm a cook.\" cümlesi. Görev \"I'm a ...\" kalıbından sonra gelir; \"food\" yemektir, görev değildir."}, {"soru": null, "cevap": "canteen", "kabul": ["the canteen", "in the canteen"], "aciklama": "Ms Janet'in metnindeki \"I'm in the canteen.\" cümlesi. Yer \"I'm in the ...\" kalıbından sonra gelir."}], "adlar": ["Wilson", "Janet"], "puanlama": "Alt sorular (kutular) eşit puanlı. Bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz; boş ya da yanlış bilgi 0. Çözüm yolu: İki metne hızlıca göz at; her metinde yalnızca kişinin okuldaki görevini (\"I'm a ...\") ve yerini (\"I'm in the ...\") ara, bulduğunu kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["place:KOK"]}}, {"id": "HZ-5-s1d3-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text. Write one word for each sentence.", "uyaran": [{"tur": "metin", "metin": "Hi! I'm Valeria. I'm from Spain. I'm a student at a language camp. My best friend is Alp. He is from Türkiye. We are in the same class. We love playing chess together. The chess club is on Friday.", "baslik": "At the Language Camp"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Valeria is a .......... at a language camp.", "cevap": "student", "kabul": [], "aciklama": "Metindeki \"I'm a student at a language camp.\" cümlesi. Boşluğa Valeria'nın kim olduğu yazılır."}, {"soru": "Alp is from .......... .", "cevap": "Türkiye", "kabul": [], "aciklama": "Metindeki \"He is from Türkiye.\" cümlesi. Alp'in ülkesi \"from\" sözcüğünden sonra yazılır (Valeria İspanya'dandır)."}, {"soru": "Valeria and Alp are in the same .......... .", "cevap": "class", "kabul": [], "aciklama": "Metindeki \"We are in the same class.\" cümlesi. \"We\" iki arkadaşı (Valeria ve Alp) gösterir."}, {"soru": "The two friends love playing .......... together.", "cevap": "chess", "kabul": [], "aciklama": "Metindeki \"We love playing chess together.\" cümlesi. \"playing\" sözcüğünden sonra oyunun adı gelir."}, {"soru": "The chess club is on .......... .", "cevap": "Friday", "kabul": [], "aciklama": "Metindeki \"The chess club is on Friday.\" cümlesi. \"on\" sözcüğünden sonra günün adı gelir."}], "adlar": ["Valeria", "Alp"], "puanlama": "Alt sorular eşit puanlı. Kelime metinden doğru bulunup yazılmışsa tam puan; yazım hatası yarım puan; yanlış ya da boş 0. Çözüm yolu: Önce metni baştan sona oku; her soru cümlesinde neyin eksik olduğunu bul, metinde aynı bilgiyi anlatan cümleyi ara ve oradaki kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["friends:SARTLI", "sentence:KOK", "text:KOK", "word:KOK"]}, "ornek": "Valeria is from .......... . → Spain"}, {"id": "HZ-5-s1d3-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "orta", "soru_tipi": "ipucu cümlesinden kulüp / yer bulma", "yonerge": "Read the clues. Write the words.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "We draw pictures here. It is the .......... club.", "cevap": "art", "kabul": [], "aciklama": "\"draw pictures\" (resim yapmak) art club (resim kulübü) ipucudur."}, {"soru": "We play volleyball and run. We have a coach. It is the .......... club.", "cevap": "sports", "kabul": [], "aciklama": "Voleybol oynamak, koşmak ve antrenör (coach) sports club (spor kulübü) ipuçlarıdır."}, {"soru": "We solve problems here. It is the .......... club.", "cevap": "maths", "kabul": [], "aciklama": "\"solve problems\" (problem çözmek) maths club (matematik kulübü) ipucudur."}, {"soru": "We read books here. We mustn't make noise. It is the .......... .", "cevap": "library", "kabul": [], "aciklama": "Kitap okunan ve gürültü yapılmayan yer library (kütüphane)."}], "adlar": [], "puanlama": "Alt sorular (kelimeler) eşit puanlı. Kelime doğru yazılmışsa tam puan; tek harf hatası yarım puan; boş ya da yanlış kelime 0. Çözüm yolu: İpucu cümlelerini oku (\"We draw pictures here.\" gibi) ve orada ne yapıldığını düşün; kulübün ya da yerin adını yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}, "ornek": "We sing songs here. It is the .......... club. → music"}, {"id": "HZ-5-s1d3-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "mustn't / Don't ile kural yazma", "yonerge": "Write the rules. Use mustn't or Don't.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(shout / in the classroom)", "cevap": "You mustn't shout in the classroom.", "kabul": ["Don't shout in the classroom."], "aciklama": "Parantezdeki fiil (shout) ve yer (in the classroom) alınır. \"mustn't\" ya da \"Don't\" den sonra fiil yalın halde kalır."}, {"soru": "(run / in the library)", "cevap": "You mustn't run in the library.", "kabul": ["Don't run in the library."], "aciklama": "Fiil (run) ve yer (in the library) alınır. \"You mustn't\" ya da \"Don't\" ile başlayan yasak cümlesi kurulur."}, {"soru": "(eat / in the science lab)", "cevap": "You mustn't eat in the science lab.", "kabul": ["Don't eat in the science lab."], "aciklama": "Fiil (eat) ve yer (in the science lab) alınır. Yasaklarda \"mustn't\" ya da \"Don't\" kullanılır."}, {"soru": "(chew gum / at school)", "cevap": "You mustn't chew gum at school.", "kabul": ["Don't chew gum at school."], "aciklama": "Fiil öbeği (chew gum) ve yer (at school) alınır. Fiil \"chew\" yalın halde kalır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: \"You mustn't + fiil + yer\" ya da \"Don't + fiil + yer\" biçiminde doğru cümle. Kısmi (yarım puan): kural doğru ama belirgin yazım hatası var. Yanlış kalıp (fiile -s eklemek, can't / don't karışıklığı) ya da boş 0. Çözüm yolu: Parantezdeki iki bilgiyi al (ne yapılmayacak / nerede), başına You mustn't ya da Don't koy ve yasağı bir cümle olarak yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "(run / in the canteen) → You mustn't run in the canteen. / Don't run in the canteen."}, {"id": "HZ-5-s1d3-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "örnek metinle kendini tanıtma", "yonerge": "Read the example. Write about you.", "uyaran": [{"tur": "metin", "metin": "My name is Sara. I'm from Spain. I'm in the art club. I like drawing pictures.", "baslik": "Example"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(name)", "cevap": "My name is Zeynep.", "kabul": ["I'm Zeynep."], "aciklama": "Örnekteki \"My name is Sara.\" cümlesi gibi: \"My name is\" + kendi adın."}, {"soru": "(country)", "cevap": "I'm from Türkiye.", "kabul": ["I am from Türkiye."], "aciklama": "Örnekteki \"I'm from Spain.\" gibi: \"I'm from\" + kendi ülken."}, {"soru": "(club)", "cevap": "I'm in the music club.", "kabul": ["I'm in the chess club.", "I'm in the drama club."], "aciklama": "Örnekteki \"I'm in the art club.\" gibi: \"I'm in the\" + okuldaki kulübün (ya da istediğin bir kulüp) + club."}, {"soru": "(likes)", "cevap": "I like playing the guitar.", "kabul": ["I like reading books.", "I love singing songs."], "aciklama": "Örnekteki \"I like drawing pictures.\" gibi: \"I like\" + sevdiğin etkinlik (-ing'li)."}], "adlar": ["Sara", "Zeynep"], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: satırın istediği bilgiyi veren, anlaşılır her cümle tam puan; bilgi doğru ama belirgin dil hatası varsa yarım puan; boş ya da konu dışı 0. Çözüm yolu: Önce örnek metne bak; her satırda ipucuna (name, country, club, likes) uygun kendi bilgini örnekteki gibi yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}]}, {"kod": "5-s1s", "sinif": 5, "ders": "secmeli", "senaryo": 1, "deneme": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1s-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the texts quickly. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Pierre", "metin": "Hi! I'm Pierre. I'm from France. I love playing the piano. I'm in the music club.", "aciklama": null}, {"kisi": "Chen", "metin": "My name is Chen. I'm from China. I do experiments in the lab. I'm in the science club.", "aciklama": null}, {"kisi": "Carol", "metin": "Hey! I'm Carol. I'm from Canada. I love playing chess. I'm in the chess club.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I am a member of the science club.\"", "cevap": "Chen", "kabul": [], "aciklama": "Chen \"I'm in the science club\" der. Fen kulübünde olan tek kişi Chen'dir; Pierre müzik, Carol satranç kulübündedir."}, {"soru": "\"Canada is my country.\"", "cevap": "Carol", "kabul": [], "aciklama": "Carol \"I'm from Canada\" der. Ülke \"I'm from ...\" kalıbından sonra gelir; Pierre Fransa'dan, Chen Çin'denir."}, {"soru": "\"I can play the piano.\"", "cevap": "Pierre", "kabul": [], "aciklama": "Pierre \"I love playing the piano\" der. Piyano çalan tek kişi Pierre'dir; metinlerde piyanodan başka söz eden yoktur."}, {"soru": "\"I like chess.\"", "cevap": "Carol", "kabul": [], "aciklama": "Carol \"I love playing chess\" der. Satranç sevdiği için hem \"chess club\" hem de bu cümle Carol'a aittir. Chen yazmak (Chen deney yapar)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: doğru kişinin adı (isimde küçük yazım hatası kabul edilir). Yanlış / boş: 0. Çözüm yolu: Önce üç kısa metni oku ve her kişinin ülkesini, kulübünü, sevdiği şeyi not al. Sonra verilen cümlenin hangi bilgiye uyduğunu bul ve o kişinin adını yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["says:SARTLI"]}}, {"id": "HZ-5-s1s-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. These sentences are false. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Hi! I'm Noah. I'm from Australia. I'm a student at this school. I like surfing. I'm in the sports club. Mr Harris is our coach. We play volleyball in the sports field.", "baslik": "Noah's School"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-5-s1s-02.jpg", "yerlesim": "yan"}, "alt_sorular": [{"soru": "Noah likes drawing pictures.", "cevap": "Noah likes surfing.", "kabul": ["He likes surfing."], "aciklama": "Metindeki \"I like surfing.\" cümlesi. Noah'ın sevdiği şey surfing'dir."}, {"soru": "Mr Adams is the coach.", "cevap": "Mr Harris is the coach.", "kabul": ["Mr Harris is their coach."], "aciklama": "Metindeki \"Mr Harris is our coach.\" cümlesi. Antrenör Mr Harris'tir; Mr Adams metinde geçmez."}, {"soru": "Noah is from Italy.", "cevap": "Noah is from Australia.", "kabul": ["He is from Australia."], "aciklama": "Metindeki \"I'm from Australia.\" cümlesi. Ülke \"from\" sözcüğünden sonra yazılır; sadece Italy sözcüğü Australia ile değiştirilir."}, {"soru": "Noah is in the art club.", "cevap": "Noah is in the sports club.", "kabul": ["He is in the sports club."], "aciklama": "Metindeki \"I'm in the sports club.\" cümlesi. Kulüp adı \"in the ... club\" kalıbında geçer."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: yanlış bilgi metne göre doğru düzeltilmiş cümle. Kısmi (yarım puan): düzeltme doğru ama cümlede belirgin dil hatası var. Yanlış bilgi düzeltilmemişse ya da boşsa 0. Çözüm yolu: Önce metni oku; her cümleyi metindeki bilgiyle karşılaştır, yanlış kısmı metindeki doğru bilgiyle değiştirip cümleyi yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["noah's:SARTLI", "text:KOK"]}}, {"id": "HZ-5-s1s-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "orta", "soru_tipi": "ipucusuz tamamlama", "yonerge": "Write one word for each sentence.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Excuse .......... ! I am new at school.", "cevap": "me", "kabul": [], "aciklama": "\"Excuse me!\" birine seslenirken kullanılan kalıptır (afedersiniz). Kitaptaki \"Excuse me! Where is the science club?\" cümlesinde olduğu gibi."}, {"soru": "Don't make .......... in the library.", "cevap": "noise", "kabul": [], "aciklama": "\"make noise\" = gürültü yapmak. Kütüphanede gürültü yapmak yasaktır; kitaptaki kural konusundan (library rules)."}, {"soru": "Let's .......... started!", "cevap": "get", "kabul": [], "aciklama": "\"Let's get started!\" (Haydi başlayalım!) kitaptaki sosyal kalıptır."}, {"soru": "Students do .......... in the science lab.", "cevap": "experiments", "kabul": ["experiment"], "aciklama": "Fen laboratuvarında yapılan şey deneydir: \"do experiments\". Kitaptaki \"doing experiments\" ve \"science lab\" ifadelerinden."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelime doğru yazılmış. Kısmi (yarım puan): tek harf hatası. Yanlış / boş: 0. Çözüm yolu: Cümleyi baştan sona oku; derste öğrendiğin kalıbı (Nice to meet you gibi) hatırla ve boşluğa uyan tek kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["experiment:KOK", "sentence:KOK", "word:KOK"]}, "ornek": "Welcome .......... our school! → to"}, {"id": "HZ-5-s1s-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "kelimeleri sıraya koyup cümle yazma", "yonerge": "Put the words in the correct order. Write the sentences.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Mary / is / where / from", "cevap": "Where is Mary from?", "kabul": [], "aciklama": "Soru sözcüğü (Where) başa gelir, sonra is ve kişi adı, en sonda from. Kitaptaki \"Where is Mary from?\" kalıbı. Soru işareti (?) eksikliği puan kırdırmaz; kelimelerden soru cümlesi çıkar."}, {"soru": "food / eat / in the library / can't / you", "cevap": "You can't eat food in the library.", "kabul": [], "aciklama": "Önce özne (You), sonra can't ve yalın fiil (eat), en sonda yer: \"You can't + fiil + yer\"."}, {"soru": "reading books / do / like / you", "cevap": "Do you like reading books?", "kabul": [], "aciklama": "Soru \"Do you like\" ile başlar, sonra -ing'li etkinlik gelir: \"Do you like + -ing?\". Kitaptaki \"Do you like reading books?\" kalıbı."}, {"soru": "in / the drama club / is / Pedro", "cevap": "Pedro is in the drama club.", "kabul": ["Is Pedro in the drama club?"], "aciklama": "Önce özne (Pedro), sonra is, sonra \"in the drama club\": \"Pedro is in the ... club\". Aynı kelimelerle \"Is Pedro in the drama club?\" sorusu da doğrudur ve kabul edilir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelimeler doğru sırada, cümle doğru (büyük harf ve nokta eksikliği puan kırdırmaz). Kısmi (yarım puan): sıra doğru ama bir kelime eksik / fazla ya da belirgin yazım hatası var. Sıra yanlışsa ya da boşsa 0. Çözüm yolu: Önce özneyi (Who / kişi) ya da soru sözcüğünü bul, sonra fiili yerleştir ve kalan kelimeleri anlamlı bir cümle olacak şekilde sırala.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "(the rules / follow) → Follow the rules."}, {"id": "HZ-5-s1s-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "notlardan afiş", "yonerge": "Read the notes. Then write the poster for the new club in the boxes.", "uyaran": [{"tur": "metin", "metin": "Origami club, on Thursday, in the classroom. Students fold paper and colour pictures. The teacher is Ms Carol.", "baslik": "Notes"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Title", {"ornek": "Origami Club"}], ["Day", {"bosluk": 1}], ["Place", {"bosluk": 2}], ["Activities", {"bosluk": 3}], ["Teacher", {"bosluk": 4}]], "baslik": "POSTER"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Thursday", "kabul": ["on Thursday"], "aciklama": "Notlarda \"on Thursday\" yazar. Day (gün) satırına günün adı yazılır. Title satırının cevabıdır)."}, {"soru": null, "cevap": "in the classroom", "kabul": ["the classroom", "classroom"], "aciklama": "Notlarda \"in the classroom\" yazar. Place (yer) satırına kulübün yapıldığı yer yazılır."}, {"soru": null, "cevap": "folding paper and colouring pictures", "kabul": ["folding paper and colouring pictures.", "Students fold paper and colour pictures.", "fold paper and colour pictures"], "aciklama": "Notlarda \"Students fold paper and colour pictures.\" cümlesi var. Activities (etkinlikler) satırına öğrencilerin yaptığı iki iş yazılır."}, {"soru": null, "cevap": "Ms Carol", "kabul": ["Carol", "The teacher is Ms Carol."], "aciklama": "Notlarda \"The teacher is Ms Carol.\" yazar. Teacher (öğretmen) satırına öğretmenin adı yazılır."}], "adlar": ["Carol"], "puanlama": "Kutular eşit puanlı. Notlardaki bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz. Yanlış bilgi / boş: 0. Anahtardakiler örnektir. Çözüm yolu: Önce notları oku; Title satırındaki örneğe bakarak her satırın ne istediğini anla (Day = gün, Place = yer, Activities = etkinlik, Teacher = öğretmen) ve notlardaki ilgili bilgiyi kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fold:KOK", "notes:SARTLI", "place:KOK", "title:KOK"]}}]}, {"kod": "5-s1sd2", "sinif": 5, "ders": "secmeli", "senaryo": 1, "deneme": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1sd2-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "bilgi kartı doldurma", "yonerge": "Read the texts quickly. Write in the boxes.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Mateo", "metin": "My name is Mateo. I'm from Mexico. My favourite subject is Maths. My best friend is Jurgen. We play volleyball together.", "aciklama": null}, {"kisi": "Maysa", "metin": "Hi! I'm Maysa. I'm from Azerbaijan. I love English. My best friend is Aylin. We read books together.", "aciklama": null}]}, {"tur": "tablo", "basliklar": ["Name", "Country", "Best friend"], "satirlar": [["Mateo", {"bosluk": 1}, {"bosluk": 2}], ["Maysa", {"bosluk": 3}, {"bosluk": 4}]], "baslik": "STUDENT CARDS"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Mexico", "kabul": ["in Mexico"], "aciklama": "Mateo'nun metnindeki \"I'm from Mexico.\" cümlesi. Ülke \"I'm from ...\" kalıbından sonra gelir."}, {"soru": null, "cevap": "Jurgen", "kabul": [], "aciklama": "Mateo'nun metnindeki \"My best friend is Jurgen.\" cümlesi. En iyi arkadaş \"My best friend is ...\" kalıbından sonra gelir."}, {"soru": null, "cevap": "Azerbaijan", "kabul": ["in Azerbaijan"], "aciklama": "Maysa'nın metnindeki \"I'm from Azerbaijan.\" cümlesi. Ülke \"I'm from ...\" kalıbından sonra gelir."}, {"soru": null, "cevap": "Aylin", "kabul": [], "aciklama": "Maysa'nın metnindeki \"My best friend is Aylin.\" cümlesi. En iyi arkadaş \"My best friend is ...\" kalıbından sonra gelir."}], "adlar": ["Mateo", "Maysa", "Jurgen", "Aylin"], "puanlama": "Alt sorular (kutular) eşit puanlı. Bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz; boş ya da yanlış bilgi 0. Çözüm yolu: İki metne hızlıca göz at; her metinde yalnızca ülkeyi (\"I'm from ...\") ve en iyi arkadaşı (\"My best friend is ...\") ara, bulduğunu kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-5-s1sd2-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "metinden tablo doldurma", "yonerge": "Read the text. Write in the boxes.", "uyaran": [{"tur": "metin", "metin": "Hi! We are in the same class. There are three students in school clubs. Alp is in the technology club. The technology club is on Monday. Ece is in the music club. The music club is on Wednesday. She loves singing. Mert is in the art club. The art club is on Friday. He loves drawing pictures.", "baslik": "Our Class"}, {"tur": "tablo", "basliklar": ["Name", "School club", "Day"], "satirlar": [["Alp", {"ornek": "technology club"}, {"bosluk": 1}], ["Ece", {"bosluk": 2}, {"bosluk": 3}], ["Mert", {"bosluk": 4}, {"bosluk": 5}]], "baslik": "CLUB DAYS"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Monday", "kabul": ["on Monday"], "aciklama": "Metindeki \"The technology club is on Monday.\" cümlesi. Alp'in kulübünün günü \"on\" sözcüğünden sonra yazılır."}, {"soru": null, "cevap": "music club", "kabul": ["music", "the music club"], "aciklama": "Metindeki \"Ece is in the music club.\" cümlesi. Kulüp \"is in the ... club\" kalıbında geçer; \"singing\" kulüpte sevdiği etkinliktir."}, {"soru": null, "cevap": "Wednesday", "kabul": ["on Wednesday"], "aciklama": "Metindeki \"The music club is on Wednesday.\" cümlesi. Ece'nin kulübünün günü yazılır."}, {"soru": null, "cevap": "art club", "kabul": ["art", "the art club"], "aciklama": "Metindeki \"Mert is in the art club.\" cümlesi. Kulüp \"is in the ... club\" kalıbında geçer; \"drawing pictures\" etkinliktir."}, {"soru": null, "cevap": "Friday", "kabul": ["on Friday"], "aciklama": "Metindeki \"The art club is on Friday.\" cümlesi. Mert'in kulübünün günü yazılır."}], "adlar": ["Alp", "Ece", "Mert"], "puanlama": "Alt sorular (kutular) eşit puanlı. Bilgi doğru kutuya yazılmışsa tam puan; yazım hatası yarım puan; yanlış ya da boş 0. Çözüm yolu: Metni her kişi için ayrı oku; kişinin adını bul, hemen yanındaki cümlelerden kulübü ve günü tabloya yaz. Örnek satır nasıl yazılacağını gösterir.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["loves:SARTLI", "text:KOK"]}}, {"id": "HZ-5-s1sd2-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "orta", "soru_tipi": "kelimeyle cümle kurma", "yonerge": "Write a sentence with each word.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(library)", "cevap": "I read books in the library.", "kabul": ["The library is near the canteen.", "We read books in the library."], "aciklama": "\"library\" kütüphanedir; kitap okunan yer olarak (\"I read books in the library.\") ya da yeri tarif ederek kullanılır."}, {"soru": "(canteen)", "cevap": "We eat food in the canteen.", "kabul": ["The cook is in the canteen.", "The canteen is downstairs."], "aciklama": "\"canteen\" okul kantinidir; yemek yenen ya da yemek yapılan yer olarak kullanılır."}, {"soru": "(coach)", "cevap": "The coach is in the sports field.", "kabul": ["Our coach is Mr Graham.", "The coach is a kind person."], "aciklama": "\"coach\" antrenördür; bir kişi olarak (\"The coach is ...\") ve çoğu zaman spor alanıyla birlikte kullanılır."}, {"soru": "(friend)", "cevap": "My best friend is Elif.", "kabul": ["I have a new friend.", "Elif is my friend."], "aciklama": "\"friend\" arkadaştır; \"My best friend is ...\" kalıbıyla ya da \"I have a new friend.\" gibi kısa bir cümleyle kullanılır."}], "adlar": ["Elif", "Graham"], "puanlama": "Alt sorular eşit puanlı. Tam: verilen kelime anlamına uygun kullanılmış, anlaşılır ve doğru bir cümle. Kısmi (yarım puan): kelime doğru kullanılmış ama cümlede belirgin dil hatası var. Kelime cümlede yoksa ya da boşsa 0. Anahtardakiler örnektir. Çözüm yolu: Kelimenin anlamını düşün ve derste öğrendiğin kalıbı (ör. \"I read books in the ...\") kullanarak kısa bir cümle yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sentence:KOK", "word:KOK"]}, "ornek": "(music) → I love music."}, {"id": "HZ-5-s1sd2-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "ipucu kelimelerden soru yazma", "yonerge": "Write the questions. Use the words.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(you / like / drawing pictures)", "cevap": "Do you like drawing pictures?", "kabul": [], "aciklama": "\"Do you like\" + -ing'li etkinlik kalıbı. Kitaptaki \"Do you like drawing pictures?\" sorusuyla aynı yapı."}, {"soru": "(where / the science lab)", "cevap": "Where is the science lab?", "kabul": [], "aciklama": "Soru sözcüğü (Where) başa gelir, sonra is ve yer adı: \"Where is + yer?\"."}, {"soru": "(who / your best friend)", "cevap": "Who is your best friend?", "kabul": [], "aciklama": "Soru sözcüğü (Who) başa gelir, sonra is ve \"your best friend\": \"Who is + kişi?\"."}, {"soru": "(you / a new student)", "cevap": "Are you a new student?", "kabul": [], "aciklama": "\"Are you\" ile başlayan soru: \"Are you + a new student?\". Özne you olduğu için is değil are kullanılır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: doğru soru cümlesi (soru işareti eksikliği puan kırdırmaz). Kısmi (yarım puan): soru kalıbı doğru ama bir kelime eksik / fazla ya da belirgin yazım hatası var. Cümle soru değilse ya da boşsa 0. Çözüm yolu: Parantezdeki ilk kelimeye bak: where / who ile başlıyorsa onu başa koy ve is ekle; \"you\" ile başlıyorsa Do you like ya da Are you ile başla.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "(what / your favourite subject) → What is your favourite subject?"}, {"id": "HZ-5-s1sd2-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "örnek metinle benzer metin yazma", "yonerge": "Read the example. Look at the card. Write about the chess club.", "uyaran": [{"tur": "metin", "metin": "This is the art club. It is on Tuesday. It is in the classroom. The teacher is Mr Graham.", "baslik": "Example"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Club", "Chess club"], ["Day", "Thursday"], ["Place", "library"], ["Teacher", "Ms Canan"]], "baslik": "CLUB CARD"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(club)", "cevap": "This is the chess club.", "kabul": ["It is the chess club."], "aciklama": "Örnekteki \"This is the art club.\" cümlesi gibi: \"This is the\" + kartın Club satırı."}, {"soru": "(day)", "cevap": "It is on Thursday.", "kabul": ["The chess club is on Thursday."], "aciklama": "Örnekteki \"It is on Tuesday.\" gibi: \"It is on\" + Day satırı."}, {"soru": "(place)", "cevap": "It is in the library.", "kabul": ["The chess club is in the library."], "aciklama": "Örnekteki \"It is in the classroom.\" gibi: \"It is in the\" + Place satırı."}, {"soru": "(teacher)", "cevap": "The teacher is Ms Canan.", "kabul": ["Ms Canan is the teacher."], "aciklama": "Örnekteki \"The teacher is Mr Graham.\" gibi: \"The teacher is\" + Teacher satırı."}], "adlar": ["Graham", "Canan"], "puanlama": "Alt sorular (dört cümle) eşit puanlı. Karttaki bilgiyi doğru aktaran, anlaşılır cümle tam puan; bilgi doğru ama belirgin dil hatası (is eksik vb.) yarım puan; boş ya da yanlış bilgi 0. Anahtardakiler örnektir. Çözüm yolu: Önce örnek metne bak; her satırda ipucuna (club, day, place, teacher) uygun kart bilgisini bul ve örnekteki gibi yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["place:KOK"]}}]}, {"kod": "5-s1sd3", "sinif": 5, "ders": "secmeli", "senaryo": 1, "deneme": 3, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.5.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with people, places and rules at school; school clubs; countries; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.5.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.5.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with people, places and rules at school; school clubs; countries; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.5.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with people, places and rules at school; school clubs; countries; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-5-s1sd3-01", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R2", "zorluk": "kolay", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the texts quickly. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Valeria", "metin": "Hi! I'm Valeria. I'm from Argentina. I love the sea. I'm in the environment club.", "aciklama": null}, {"kisi": "Graham", "metin": "Hey! I'm Graham. I'm from England. I like solving problems. I'm in the maths club.", "aciklama": null}, {"kisi": "Maysa", "metin": "My name is Maysa. I'm from Azerbaijan. I love playing the guitar. I'm in the music club.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I am a member of the maths club.\"", "cevap": "Graham", "kabul": [], "aciklama": "Graham \"I'm in the maths club\" der. Matematik kulübünde olan tek kişi Graham'dır; Valeria environment, Maysa music kulübündedir."}, {"soru": "\"Argentina is my country.\"", "cevap": "Valeria", "kabul": [], "aciklama": "Valeria \"I'm from Argentina\" der. Ülke \"I'm from ...\" kalıbından sonra gelir; Graham England'dan, Maysa Azerbaijan'dandır."}, {"soru": "\"I like the guitar.\"", "cevap": "Maysa", "kabul": [], "aciklama": "Maysa \"I love playing the guitar\" der. Gitar çalmayı seven tek kişi Maysa'dır."}, {"soru": "\"England is my country.\"", "cevap": "Graham", "kabul": [], "aciklama": "Graham \"I'm from England\" der. England sözcüğü yalnızca Graham'ın metninde geçer."}], "adlar": ["Valeria", "Graham", "Maysa"], "puanlama": "Alt sorular eşit puanlı. Tam: doğru kişinin adı (isimde küçük yazım hatası kabul edilir). Yanlış / boş: 0. Çözüm yolu: Önce üç kısa metni oku ve her kişinin ülkesini, kulübünü, sevdiği şeyi not al. Sonra verilen cümlenin hangi bilgiye uyduğunu bul ve o kişinin adını yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["says:SARTLI"]}}, {"id": "HZ-5-s1sd3-02", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.R3", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the text. Write Yes or No. For No, write the correct sentence.", "uyaran": [{"tur": "metin", "metin": "Hi! My name is Emre. I'm a student at a school in Türkiye. My favourite subject is English. I'm in the drama club. My friend Lucas is from Brazil. He is in the sports club. He plays volleyball every day.", "baslik": "Emre's School"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Is Emre in the drama club?", "cevap": "Yes.", "kabul": ["Yes, he is.", "Yes, he is in the drama club."], "aciklama": "Metindeki \"I'm in the drama club.\" cümlesi. Soru metindeki bilgiyle uyuşuyor, bu yüzden cevap Yes."}, {"soru": "Is Emre's favourite subject Maths?", "cevap": "No. His favourite subject is English.", "kabul": ["No. It is English.", "No. Emre's favourite subject is English."], "aciklama": "Metindeki \"My favourite subject is English.\" cümlesi. Soru metinle uyuşmuyor, bu yüzden No yazılır ve doğru ders eklenir."}, {"soru": "Is Lucas from Spain?", "cevap": "No. He is from Brazil.", "kabul": ["No. Lucas is from Brazil."], "aciklama": "Metindeki \"My friend Lucas is from Brazil.\" cümlesi. Ülke metinle uyuşmuyor, bu yüzden No yazılır ve doğru ülke eklenir."}, {"soru": "Is Lucas in the sports club?", "cevap": "Yes.", "kabul": ["Yes, he is.", "Yes, he is in the sports club."], "aciklama": "Metindeki \"He is in the sports club.\" cümlesi. \"He\" Lucas'ı gösterir; soru metinle uyuşuyor, bu yüzden cevap Yes."}], "adlar": ["Emre", "Lucas"], "puanlama": "Alt sorular eşit puanlı. Tam: Yes / No cevabı doğru; cevap No ise metne göre doğru bilgiyi veren cümle de yazılmış. Kısmi (yarım puan): No doğru ama düzeltme eksik ya da belirgin dil hatası var. Yanlış ya da boş 0. Çözüm yolu: Önce metni oku; soruyu metindeki bilgiyle karşılaştır. Uyuyorsa Yes yaz; uymuyorsa No yaz ve metindeki doğru bilgiyi bir cümleyle ekle.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["plays:SARTLI", "sentence:KOK", "text:KOK"]}}, {"id": "HZ-5-s1sd3-03", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.V1", "zorluk": "kolay", "soru_tipi": "karışık harflerden kelime", "yonerge": "Write the words.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Mr Wilson is a ........ at our school. (a r e h c t e)", "cevap": "teacher", "kabul": [], "aciklama": "Harfler: t-e-a-c-h-e-r (7 harf). Okulda ders veren kişi teacher; \"e\" harfi iki kez kullanılır."}, {"soru": "Elif is my best ........ . (n f e i d r)", "cevap": "friend", "kabul": [], "aciklama": "Harfler: f-r-i-e-n-d (6 harf). \"best friend\" (en iyi arkadaş) kalıbı."}, {"soru": "I love playing the ........ . (n o p a i)", "cevap": "piano", "kabul": [], "aciklama": "Harfler: p-i-a-n-o (5 harf). \"playing the piano\" (piyano çalmak)."}, {"soru": "We must follow the school ........ . (l e s u r)", "cevap": "rules", "kabul": [], "aciklama": "Harfler: r-u-l-e-s (5 harf). \"Follow the rules\" (kurallara uy) kalıbı."}], "adlar": ["Wilson", "Elif"], "puanlama": "Alt sorular (kelimeler) eşit puanlı. Kelime doğru yazılmışsa tam puan; tek harf hatası yarım puan; boş ya da yanlış kelime 0. Çözüm yolu: Önce cümleyi oku ve boşluğa ne uyduğunu düşün; sonra parantezdeki karışık harfleri sırayla kullanarak kelimeyi yaz (her harfi bir kez kullan).", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "We play ........ in the club. (s h c e s) → chess"}, {"id": "HZ-5-s1sd3-04", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.G1", "zorluk": "orta", "soru_tipi": "birinci kişiyi üçüncü kişiye çevirme", "yonerge": "Read Elif's sentences. Write the sentences about Elif.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "I am in the drama club.", "cevap": "Elif is in the drama club.", "kabul": [], "baslangic": "Elif", "aciklama": "I yerine Elif yazılır; am yerine is gelir."}, {"soru": "I like playing volleyball.", "cevap": "Elif likes playing volleyball.", "kabul": [], "baslangic": "Elif", "aciklama": "3. tekil kişide like fiiline -s eklenir: likes. -ing'li etkinlik (playing volleyball) aynı kalır."}, {"soru": "I have a new friend.", "cevap": "Elif has a new friend.", "kabul": [], "baslangic": "Elif", "aciklama": "3. tekil kişide have fiili has olur."}, {"soru": "I read books in the library.", "cevap": "Elif reads books in the library.", "kabul": [], "baslangic": "Elif", "aciklama": "3. tekil kişide read fiiline -s eklenir: reads. Yer bilgisi (in the library) aynı kalır."}], "adlar": ["Elif"], "puanlama": "Alt sorular eşit puanlı. Tam: Elif ile başlayan, fiil biçimi doğru (-s / is / has) üçüncü kişi cümlesi. Kısmi (yarım puan): kişi doğru ama fiil biçimi ya da bir kelime hatalı. Birinci kişi kalmışsa ya da boşsa 0. Çözüm yolu: I yerine Elif yaz; fiil like, play, read gibi bir eylemse sonuna -s ekle (am → is, have → has).", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["loves:SARTLI", "reads:SARTLI"]}, "ornek": "I love music. → Elif loves music."}, {"id": "HZ-5-s1sd3-05", "sinif": 5, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.5.1.W3", "zorluk": "orta", "soru_tipi": "notlardan afiş", "yonerge": "Read the notes. Then write the poster for the new club in the boxes.", "uyaran": [{"tur": "metin", "metin": "Volleyball club, on Monday, in the sports field. Students play volleyball and run. The coach is Mr Alex.", "baslik": "Notes"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Title", {"ornek": "Volleyball Club"}], ["Day", {"bosluk": 1}], ["Place", {"bosluk": 2}], ["Activities", {"bosluk": 3}], ["Coach", {"bosluk": 4}]], "baslik": "POSTER"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Monday", "kabul": ["on Monday"], "aciklama": "Notlarda \"on Monday\" yazar. Day (gün) satırına günün adı yazılır."}, {"soru": null, "cevap": "in the sports field", "kabul": ["the sports field", "sports field"], "aciklama": "Notlarda \"in the sports field\" yazar. Place (yer) satırına kulübün yapıldığı yer yazılır."}, {"soru": null, "cevap": "playing volleyball and running", "kabul": ["play volleyball and run", "Students play volleyball and run.", "playing volleyball"], "aciklama": "Notlarda \"Students play volleyball and run.\" cümlesi var. Activities (etkinlikler) satırına öğrencilerin yaptığı işler yazılır."}, {"soru": null, "cevap": "Mr Alex", "kabul": ["Alex", "The coach is Mr Alex."], "aciklama": "Notlarda \"The coach is Mr Alex.\" yazar. Coach (antrenör) satırına antrenörün adı yazılır."}], "adlar": ["Alex"], "puanlama": "Kutular eşit puanlı. Notlardaki bilgi doğru kutuya yazılmışsa tam puan; yazım hatası puan kırdırmaz. Yanlış bilgi / boş: 0. Anahtardakiler örnektir. Çözüm yolu: Önce notları oku; Title satırındaki örneğe bakarak her satırın ne istediğini anla (Day = gün, Place = yer, Activities = etkinlik, Coach = antrenör) ve notlardaki ilgili bilgiyi kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "5. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["notes:SARTLI", "place:KOK", "running:SARTLI", "title:KOK"]}}]}, {"kod": "6-s1", "sinif": 6, "ders": "ingilizce", "senaryo": 1, "deneme": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-6-s1-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "duyurunun yerini bulma", "yonerge": "Read the notices. Where can you see them? Write the places.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Notice 1", "metin": "Borrow storybooks here. Return the books on Friday.", "aciklama": null}, {"kisi": "Notice 2", "metin": "Do experiments here. Listen to your teacher carefully.", "aciklama": null}, {"kisi": "Notice 3", "metin": "Sports Day is on Friday. Run in the race here.", "aciklama": null}, {"kisi": "Notice 4", "metin": "Lessons start at 8:30. Sit at your desk. Do not forget your bag.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(1)", "cevap": "library", "kabul": ["in the library", "the library"], "aciklama": "\"Borrow storybooks\" (kitap ödünç al) ve \"Return the books\" (kitapları geri ver) kütüphanede yapılır."}, {"soru": "(2)", "cevap": "lab", "kabul": ["in the lab", "science lab", "in the science lab"], "aciklama": "\"Do experiments\" (deney yap) laboratuvarda yapılır."}, {"soru": "(3)", "cevap": "sports field", "kabul": ["in the sports field", "the sports field", "playground"], "aciklama": "\"Sports Day\" ve \"Run in the race\" (yarışta koş) spor sahasını gösterir."}, {"soru": "(4)", "cevap": "classroom", "kabul": ["in the classroom", "the classroom", "class"], "aciklama": "\"Lessons start\" (dersler başlar), \"Sit at your desk\" (sırana otur) sınıfı gösterir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: duyuruya uygun doğru yer (yazım hatası kırılmaz). Kısmi: yok. Boş / yanlış yer: 0. Çözüm: Her duyuruyu oku; eşya (books, desk), eylem (do experiments, run) ve zaman ipuçlarına bak, bu şeylerin yapıldığı yeri yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["notices:SARTLI", "run:KOK"]}}, {"id": "HZ-6-s1-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "paragraf cümlelerini sıralama", "yonerge": "The sentences are not in the correct order. Write the correct order.", "uyaran": [{"tur": "metin", "metin": "A) After the lessons, Hale reads books in the library.\nB) In the morning, Hale eats breakfast with her mum.\nC) In the evening, she does her homework.\nD) Then, she goes to school by bus.\nE) At 12:00, she eats lunch in the lunch hall.", "baslik": "Hale's Day"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "D", "kabul": [], "aciklama": "B (sabah kahvaltı) örnektir; kahvaltıdan sonra \"Then, she goes to school by bus\" gelir. \"Then\" (sonra) kahvaltıdan sonraki adımı gösterir."}, {"soru": null, "cevap": "E", "kabul": [], "aciklama": "Okula varınca saat 12:00 olur ve Hale öğle yemeği yer: \"At 12:00, she eats lunch\". A yazmak (A dersten sonradır)."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "Öğle yemeğinden sonra dersler biter: \"After the lessons\" (derslerden sonra). Hale kütüphanede kitap okur."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "Gün \"In the evening\" (akşam) ile biter: Hale ödevini yapar."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Tam: doğru harf. Yanlış / boş: 0. Çözüm: Önce bütün cümleleri oku. Zaman sözcüklerine bak (In the morning, At 12:00, After the lessons, In the evening) ve günü sabahtan akşama sırala.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["eats:SARTLI", "goes:SARTLI", "hale's:SARTLI"]}}, {"id": "HZ-6-s1-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "karışık harflerden kelime", "yonerge": "Complete the sentences. Write the words in the correct order.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Defne gives a ........ at the school ceremony. (c h e e s p)", "cevap": "speech", "kabul": [], "aciklama": "Harfler: s-p-e-e-c-h (6 harf). \"gives a speech\" (konuşma yapar) kalıbı. Yazım önemlidir; \"e\" iki kez kullanılır."}, {"soru": "The ........ sings songs on the stage. (o i c h r)", "cevap": "choir", "kabul": [], "aciklama": "Harfler: c-h-o-i-r (5 harf). \"choir\" (koro) şarkı söyleyen gruptur."}, {"soru": "We line up in the school ........ every morning. (d a r g e n)", "cevap": "garden", "kabul": [], "aciklama": "Harfler: g-a-r-d-e-n (6 harf). \"school garden\" (okul bahçesi)."}, {"soru": "Our ........ explains the lesson clearly. (c h a t e r e)", "cevap": "teacher", "kabul": [], "aciklama": "Harfler: t-e-a-c-h-e-r (7 harf). Dersi açıklayan kişi öğretmendir; \"e\" iki kez kullanılır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelime doğru yazılmış. Kısmi (yarım puan): tek harf hatası. Yanlış / boş: 0. Çözüm: Cümleyi oku, boşluğa hangi kelimenin uyduğunu düşün, sonra harfleri sırala ve harf sayısını kontrol et.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sings:SARTLI"]}, "ornek": "Students read ........ in the library. (o k s b o) → books"}, {"id": "HZ-6-s1-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "sıklık zarfını yerleştirme", "yonerge": "Write the sentences again. Use the word after each sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Students are quiet in the library. (always)", "cevap": "Students are always quiet in the library.", "kabul": [], "aciklama": "\"be\" (are) fiilinden SONRA gelir: are + always."}, {"soru": "Fatih reads storybooks in the reading corner. (often)", "cevap": "Fatih often reads storybooks in the reading corner.", "kabul": ["Often Fatih reads storybooks in the reading corner."], "aciklama": "Sıklık zarfı ana fiilden ÖNCE gelir: often + reads."}, {"soru": "Our teacher gives us science projects. (sometimes)", "cevap": "Our teacher sometimes gives us science projects.", "kabul": ["Sometimes our teacher gives us science projects."], "aciklama": "Zarf ana fiilden önce gelir: teacher + sometimes + gives. Cümle başında \"Sometimes\" da kabul edilir."}, {"soru": "Kyle walks to school. (never)", "cevap": "Kyle never walks to school.", "kabul": [], "aciklama": "\"never\" ana fiilden önce gelir: never + walks."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: zarf doğru yerde, cümle doğru. Kısmi (yarım puan): zarf doğru ama küçük yazım / eksik sözcük hatası. Zarf yanlış yerde / boş: 0. Çözüm: Fiil \"am / is / are\" ise zarf ondan SONRA, diğer fiillerde (reads, gives, walks) fiilden ÖNCE gelir.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["walks:SARTLI"]}, "ornek": "We eat lunch at school. (usually) → We usually eat lunch at school."}, {"id": "HZ-6-s1-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W3", "zorluk": "orta", "soru_tipi": "notlardan benzer metin yazma", "yonerge": "Read the example. Look at the notes. Write Mehmet's text.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Defne. I always walk to school. I usually eat lunch in the garden. I often sing in the choir. I never forget my homework.", "baslik": "Example"}, {"tur": "tablo", "basliklar": ["Mehmet", "How often"], "satirlar": [["go to school by bus", "always"], ["eat lunch in the lunch hall", "usually"], ["read storybooks in the library", "often"], ["come to school late", "never"]], "baslik": "Notes"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-6-s1-05.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "Hi, I'm Mehmet. I ", "cevap": "always go to school by bus.", "kabul": [], "aciklama": "Notlardaki ilk satır: \"go to school by bus\" + always. Örnekteki gibi birinci kişi: \"I always go...\"."}, {"soru": "I ", "cevap": "usually eat lunch in the lunch hall.", "kabul": [], "aciklama": "Notlardaki ikinci satır: \"eat lunch in the lunch hall\" + usually. Zarf fiilden önce gelir."}, {"soru": "I ", "cevap": "often read storybooks in the library.", "kabul": [], "aciklama": "Notlardaki üçüncü satır: \"read storybooks in the library\" + often."}, {"soru": "I ", "cevap": "never come to school late.", "kabul": [], "aciklama": "Notlardaki son satır: \"come to school late\" + never. \"never\" ile fiil olumlu kalır (don't eklenmez)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: notlardaki bilgi doğru, sıklık sözcüğü doğru yerde, cümle anlaşılır. Kısmi (yarım puan): bilgi doğru ama zarf yanlış yerde ya da belirgin dil hatası. Bilgi yanlış / boş: 0. Çözüm: Önce Example metnine bak; her satırda zarf, \"I\" ile fiil arasındadır. Sonra notlardaki her satırı aynı biçimde yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}}]}, {"kod": "6-s1d2", "sinif": 6, "ders": "ingilizce", "senaryo": 1, "deneme": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-6-s1d2-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "kısa metinlerden tablo doldurma", "yonerge": "Read the texts quickly. Complete the table.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Aylin", "metin": "I read a poem in the assembly on Monday.", "aciklama": null}, {"kisi": "Kemal", "metin": "I carry the flag in the parade on Thursday.", "aciklama": null}, {"kisi": "Ece", "metin": "I sing in the choir at the ceremony on Wednesday.", "aciklama": null}]}, {"tur": "tablo", "basliklar": ["Student", "Task", "Day"], "satirlar": [["Aylin", {"ornek": "reading a poem"}, {"ornek": "Monday"}], ["Kemal", {"bosluk": 1}, {"bosluk": 2}], ["Ece", {"bosluk": 3}, {"bosluk": 4}]], "baslik": "Our School Programme"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "carrying the flag", "kabul": ["carry the flag", "the flag"], "aciklama": "Kemal'in metni: \"I carry the flag in the parade\". Görevi bayrak taşımaktır; tabloda Aylin örneğindeki gibi -ing biçimi de yazılabilir (carrying the flag)."}, {"soru": null, "cevap": "Thursday", "kabul": ["on Thursday"], "aciklama": "Kemal'in metninin sonu: \"in the parade on Thursday\". Gün bilgisi \"on\" sözcüğünden sonra gelir."}, {"soru": null, "cevap": "singing in the choir", "kabul": ["sing in the choir", "singing"], "aciklama": "Ece'nin metni: \"I sing in the choir at the ceremony\". Görevi koroda şarkı söylemektir."}, {"soru": null, "cevap": "Wednesday", "kabul": ["on Wednesday"], "aciklama": "Ece'nin metninin sonu: \"at the ceremony on Wednesday\". Gün bilgisi \"on\" sözcüğünden sonra gelir."}], "adlar": ["Aylin", "Kemal", "Ece"], "puanlama": "Dört kutu eşit puanlı. Tam: metindeki bilgi doğru (küçük yazım hatası kırılmaz). Yanlış / boş: 0. Çözüm: Önce her öğrencinin adını bul, sonra o kişinin metninden ne yaptığını ve hangi gün olduğunu tabloya yaz; Aylin örnek olarak verilmiştir.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}}, {"id": "HZ-6-s1d2-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Burak. I walk to school with my friend, Ziya. We usually arrive at 8:15. I always sit near the door in the classroom. At break time, I play chess in the school garden. After school, I borrow books from the library.", "baslik": "Burak's School Day"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Burak goes to school by bus.", "cevap": "Burak walks to school with Ziya.", "kabul": ["Burak walks to school.", "He walks to school with his friend."], "aciklama": "Metindeki \"I walk to school with my friend, Ziya\" cümlesi. Burak otobüsle değil, arkadaşı Ziya ile yürüyerek gider."}, {"soru": "Burak and Ziya usually arrive at 9:00.", "cevap": "Burak and Ziya usually arrive at 8:15.", "kabul": ["They usually arrive at 8:15."], "aciklama": "Metindeki \"We usually arrive at 8:15\" cümlesi. \"We\" Burak ve Ziya'dır; doğru saat 8:15'tir."}, {"soru": "Burak always sits near the window.", "cevap": "Burak always sits near the door.", "kabul": ["He always sits near the door."], "aciklama": "Metindeki \"I always sit near the door in the classroom\" cümlesi. Burak kapının yanında oturur."}, {"soru": "Burak borrows books from the lab.", "cevap": "Burak borrows books from the library.", "kabul": ["He borrows books from the library."], "aciklama": "Metindeki \"After school, I borrow books from the library\" cümlesi. Kitapları kütüphaneden ödünç alır."}], "adlar": ["Burak"], "puanlama": "Alt sorular eşit puanlı. Tam: yanlış bilgi metne göre doğru düzeltilmiş, cümle anlaşılır. Kısmi (yarım puan): bilgi doğru ama belirgin dil hatası var. Düzeltme yanlış / boş: 0. Çözüm: Önce metni oku, sonra her cümleyi metindeki bilgiyle karşılaştır; metinle uyuşmayan tek sözcüğü bul ve metindeki doğru sözcükle değiştir.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["borrows:SARTLI", "goes:SARTLI", "sits:SARTLI", "walks:SARTLI"]}, "ornek": "Burak's friend is Hale. → Burak's friend is Ziya."}, {"id": "HZ-6-s1d2-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "harf ipuçlu cümle tamamlama", "yonerge": "Complete the sentences. Write the words.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Zeynep does her homework at her d _ _ _ .", "cevap": "desk", "kabul": [], "aciklama": "Harf ipucu: d _ _ _ (4 harf). Ödev masada (desk) yapılır: \"at her desk\"."}, {"soru": "Kemal carries the f _ _ _ in the parade.", "cevap": "flag", "kabul": [], "aciklama": "Harf ipucu: f _ _ _ (4 harf). Geçit töreninde taşınan şey bayraktır: \"carry the flag\"."}, {"soru": "The h _ _ _ _ _ _ _ _ _ gives a speech at the ceremony.", "cevap": "headmaster", "kabul": [], "aciklama": "Harf ipucu: h _ _ _ _ _ _ _ _ _ (10 harf). Okulda törende konuşma yapan kişi müdürdür (headmaster)."}, {"soru": "The students dance at the c _ _ _ _ _ _ _ _ _ _ for Republic Day.", "cevap": "celebration", "kabul": [], "aciklama": "Harf ipucu: c _ _ _ _ _ _ _ _ _ _ (11 harf). Özel bir gün için yapılan şenlik \"celebration\" sözcüğüdür."}], "adlar": ["Zeynep", "Kemal"], "puanlama": "Alt sorular eşit puanlı. Tam: kelime doğru yazılmış. Kısmi (yarım puan): tek harf hatası. Yanlış / boş: 0. Çözüm: Cümlenin anlamına bak, boşluğa uyan kelimeyi düşün, ilk harfi ve harf sayısını kontrol ederek yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["carries:SARTLI"]}, "ornek": "Our t _ _ _ _ _ _ is helpful. → teacher"}, {"id": "HZ-6-s1d2-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "nesne zamirini yerleştirme", "yonerge": "Write the sentences again. Use him, her, it, us or them.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Aylin always helps (Kemal) with maths.", "cevap": "Aylin always helps him with maths.", "kabul": [], "aciklama": "Fiilden sonra gelen erkek kişi (Kemal) yerine nesne zamiri \"him\" kullanılır."}, {"soru": "Our teacher gives (the students) a project.", "cevap": "Our teacher gives them a project.", "kabul": [], "aciklama": "Çoğul isim grubu (the students) yerine nesne zamiri \"them\" kullanılır."}, {"soru": "Mum makes breakfast for (Ece and me).", "cevap": "Mum makes breakfast for us.", "kabul": [], "aciklama": "\"Ece and me\" iki kişidir ve konuşan kişi de içindedir; yerine \"us\" gelir."}, {"soru": "I put (my book) on the desk.", "cevap": "I put it on the desk.", "kabul": [], "aciklama": "Tek bir nesne (my book) yerine \"it\" kullanılır."}], "adlar": ["Aylin", "Kemal", "Ece", "Zeynep"], "puanlama": "Alt sorular eşit puanlı. Tam: doğru nesne zamiri, cümle doğru. Kısmi (yarım puan): zamir doğru ama küçük yazım / eksik sözcük hatası. Zamir yanlış / boş: 0. Çözüm: Parantezdeki sözcüklerin kim ya da ne olduğuna bak (erkek, kız, tek şey, çoğul, biz); fiilden sonra uygun zamiri (him, her, it, us, them) yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "The headmaster greets (Zeynep). → The headmaster greets her."}, {"id": "HZ-6-s1d2-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W3", "zorluk": "orta", "soru_tipi": "bilgi kartından benzer metin yazma", "yonerge": "Read the example. Look at the notes. Write Kemal's text.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Aylin. I am in the art club. I draw pictures there. The club is on Wednesday. It is in the classroom.", "baslik": "Example"}, {"tur": "tablo", "basliklar": ["Kemal", "Information"], "satirlar": [["Club", "chess club"], ["Activity", "play chess with friends"], ["Day", "Tuesday"], ["Place", "school garden"]], "baslik": "Notes"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Hi, I'm Kemal. ", "cevap": "I am in the chess club.", "kabul": [], "aciklama": "Notlardaki \"Club: chess club\" satırı. Örnekteki \"I am in the art club\" cümlesi gibi yazılır."}, {"soru": "I ", "cevap": "play chess with my friends there.", "kabul": ["play chess with my friends."], "aciklama": "Notlardaki \"Activity: play chess with friends\" satırı. Birinci kişi olduğu için fiile -s gelmez, \"friends\" önüne my gelir."}, {"soru": "The club is ", "cevap": "on Tuesday.", "kabul": [], "aciklama": "Notlardaki \"Day: Tuesday\" satırı. Örnekteki \"The club is on Wednesday\" cümlesi gibi gün önünde \"on\" kullanılır."}, {"soru": "It is ", "cevap": "in the school garden.", "kabul": ["in the garden."], "aciklama": "Notlardaki \"Place: school garden\" satırı. Yer önünde \"in\" kullanılır, örnekteki \"It is in the classroom\" gibi."}], "adlar": ["Aylin", "Kemal"], "puanlama": "Alt sorular eşit puanlı. Tam: notlardaki bilgi doğru ve cümle anlaşılır. Kısmi (yarım puan): bilgi doğru ama belirgin dil hatası. Bilgi yanlış / boş: 0. Çözüm: Önce Example metnine bak; her cümle notlardaki bir satıra karşılık gelir. Notlardaki bilgiyi örnekteki cümle biçimiyle yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}]}, {"kod": "6-s1d3", "sinif": 6, "ders": "ingilizce", "senaryo": 1, "deneme": 3, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 1}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 1}, {"kod": "ENG.6.1.W3", "tema": "School Life", "metin": "Students can organise a content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations” based on the model/example provided.", "adet": 1}], "sorular": [{"id": "HZ-6-s1d3-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "duyurudan bilgi tablosu doldurma", "yonerge": "Read the notice quickly. Complete the table.", "uyaran": [{"tur": "metin", "metin": "Talent Show\nCome to the conference hall on Tuesday at 2:00. Students sing, dance and read poems. Our teacher, Mr Akman, helps the students.", "baslik": "Notice"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Event", {"bosluk": 1}], ["Day", {"bosluk": 2}], ["Place", {"bosluk": 3}], ["Time", {"bosluk": 4}]], "baslik": "About the notice"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Talent Show", "kabul": ["talent show"], "aciklama": "Duyurunun başlığı \"Talent Show\". Başlık etkinliğin adını gösterir."}, {"soru": null, "cevap": "Tuesday", "kabul": ["on Tuesday"], "aciklama": "\"Come to the conference hall on Tuesday at 2:00\" cümlesi. \"on\" sözcüğünden sonra gün gelir."}, {"soru": null, "cevap": "conference hall", "kabul": ["the conference hall"], "aciklama": "\"Come to the conference hall\" cümlesi. \"to\" sözcüğünden sonra gelen yer etkinliğin yapıldığı yerdir."}, {"soru": null, "cevap": "2:00", "kabul": ["at 2:00"], "aciklama": "\"Come to the conference hall on Tuesday at 2:00\" cümlesi. \"at\" sözcüğünden sonra saat gelir."}], "adlar": ["Akman"], "puanlama": "Dört kutu eşit puanlı. Tam: duyurudaki bilgi doğru (küçük yazım hatası kırılmaz). Yanlış / boş: 0. Çözüm: Duyuruyu hızlıca oku; başlıkta etkinliğin adını, \"on\" sonrasında günü, \"to\" sonrasında yeri, \"at\" sonrasında saati bul.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}}, {"id": "HZ-6-s1d3-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "The sentences of the dialogue are not in the correct order. Write the correct order.", "uyaran": [{"tur": "metin", "metin": "A) Sure! Which book do you want?\nB) Hi, Ece. Do you go to the library after school?\nC) A short story, please.\nD) I need a storybook. Can you help me?\nE) OK. I have a storybook in my bag.\nF) Yes, I often go there. Why?", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "E"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "F", "kabul": [], "aciklama": "B bir soru sorar: \"Do you go to the library after school?\" Ona verilen cevap \"Yes, I often go there\" (F) ve ardından \"Why?\" gelir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "F'deki \"Why?\" sorusunun cevabı nedeni söyler: \"I need a storybook. Can you help me?\" (D)."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "D'deki yardım isteğine \"Sure!\" ile cevap verilir ve \"Which book do you want?\" (A) diye sorulur."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "A'daki \"Which book\" sorusunun cevabı \"A short story, please.\" (C). Son cümle E ile diyalog biter."}], "adlar": ["Ece"], "puanlama": "Dört kutu eşit puanlı. Tam: doğru harf. Yanlış / boş: 0. Çözüm: Önce bütün cümleleri oku. Soru-cevap çiftlerini bul (Do you ...? / Yes, ... ; Which book ...? / A short story) ve ilk cümleden son cümleye kadar sırala.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["storybook:KOK"]}}, {"id": "HZ-6-s1d3-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "ipucusuz tamamlama", "yonerge": "Write one word for each sentence.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "The students run in the ........ on Sports Day.", "cevap": "race", "kabul": [], "aciklama": "Spor gününde koşulan yarışma \"race\" sözcüğüyle söylenir: \"run in the race\"."}, {"soru": "We always ........ the school rules.", "cevap": "follow", "kabul": [], "aciklama": "\"follow the school rules\" (okul kurallarına uymak) kalıbı."}, {"soru": "Ziya answers all the questions well. He will ........ the exam.", "cevap": "pass", "kabul": [], "aciklama": "Sınavda soruları iyi cevaplayan öğrenci sınavı geçer: \"pass the exam\"."}, {"soru": "Hale wants to win the game. She will ........ to do her best.", "cevap": "try", "kabul": [], "aciklama": "\"try to do her best\" (elinden geleni yapmaya çalışmak) kalıbı."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelime doğru yazılmış. Kısmi (yarım puan): tek harf hatası. Yanlış / boş: 0. Çözüm: Cümleyi baştan sona oku, boşluktan önceki ve sonraki sözcüklerle birlikte hangi kalıbın oluştuğunu düşün ve kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["run:KOK", "win:KOK"]}, "ornek": "Students write in a ........ . → book"}, {"id": "HZ-6-s1d3-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "karışık kelimelerle emir cümlesi", "yonerge": "Put the words in the correct order and write the instructions.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(the lunch hall / quietly / enter)", "cevap": "Enter the lunch hall quietly.", "kabul": [], "aciklama": "Emir cümlesi fiille başlar: Enter. Sonra yer (the lunch hall), en sonda durum zarfı (quietly) gelir."}, {"soru": "(on the desk / put / your bag)", "cevap": "Put your bag on the desk.", "kabul": [], "aciklama": "Emir cümlesi fiille başlar: Put. Önce nesne (your bag), sonra yer (on the desk) gelir."}, {"soru": "(the teacher / to / listen / carefully)", "cevap": "Listen to the teacher carefully.", "kabul": ["Listen carefully to the teacher."], "aciklama": "Fiille başlar: Listen. \"listen to\" birlikte kullanılır; carefully sona ya da \"to\" önüne gelebilir."}, {"soru": "(your friends / help / always)", "cevap": "Always help your friends.", "kabul": ["Help your friends always."], "aciklama": "Emir cümlesinde fiil (help) cümlenin başında ya da \"always\" ile başlayıp hemen ardından gelir; nesne your friends fiilden sonradır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: emir cümlesi (fiille başlayan) doğru sırada. Kısmi (yarım puan): kelimeler doğru ama sıra anlamı bozmayacak kadar hatalı ya da fiil başta değil. Boş: 0. Çözüm: Önce fiili bul ve cümleyi onunla başlat, sonra nesneyi, en sonda yer ve zaman sözcüğünü koy.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "(your name / write) → Write your name."}, {"id": "HZ-6-s1d3-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W3", "zorluk": "orta", "soru_tipi": "notlardan sıralı yazma", "yonerge": "Look at the notes. Write about Sude's day.", "uyaran": [{"tur": "tablo", "basliklar": ["Sude", "Notes"], "satirlar": [["7:00", "wake up"], ["7:30", "eat breakfast with mum"], ["after school", "play chess in the chess club"], ["in the evening", "do homework"]], "baslik": "Sude's Day"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "At 7:00, ", "cevap": "Sude wakes up.", "kabul": [], "aciklama": "Notlardaki \"7:00 – wake up\" satırı. Özne Sude (3. tekil) olduğu için fiile -s gelir: wakes up."}, {"soru": "Then, ", "cevap": "she eats breakfast with her mum.", "kabul": ["Sude eats breakfast with her mum."], "aciklama": "Notlardaki \"7:30 – eat breakfast with mum\" satırı. \"Then\" sıradaki eylemi başlatır; 3. tekil -s ve my yerine her kullanılır."}, {"soru": "After school, ", "cevap": "she plays chess in the chess club.", "kabul": ["Sude plays chess in the chess club."], "aciklama": "Notlardaki \"after school – play chess in the chess club\" satırı. Fiile -s gelir: plays."}, {"soru": "In the evening, ", "cevap": "she does her homework.", "kabul": ["Sude does her homework."], "aciklama": "Notlardaki \"in the evening – do homework\" satırı. 3. tekil: does; \"her homework\" yazılır."}], "adlar": ["Aylin"], "puanlama": "Alt sorular eşit puanlı. Tam: notlardaki bilgi doğru, fiil 3. tekil -s ile yazılmış, cümle anlaşılır. Kısmi (yarım puan): bilgi doğru ama -s ya da belirgin dil hatası. Bilgi yanlış / boş: 0. Çözüm: Notları yukarıdan aşağı oku; her satırı verilen sözcükle (At 7:00, Then, After school, In the evening) başlayıp Sude'yi özne alarak yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["eats:SARTLI", "plays:SARTLI", "sude's:SARTLI"]}, "ornek": "At 4:00, Aylin reads a book. Then, she plays chess."}]}, {"kod": "6-s5", "sinif": 6, "ders": "secmeli", "senaryo": 5, "deneme": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 2}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.W4", "tema": "School Life", "metin": "Students can individually construct/form content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations”.", "adet": 1}], "sorular": [{"id": "HZ-6-s5-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the texts quickly. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Salih", "metin": "I wake up early. I eat breakfast with my mum. I go to school by bus.", "aciklama": null}, {"kisi": "Hale", "metin": "I like music. I sing in the choir. We sing the National Anthem at the ceremony.", "aciklama": null}, {"kisi": "Sinan", "metin": "I do my homework in the evening. I read storybooks at home.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I take the bus to school.\"", "cevap": "Salih", "kabul": [], "aciklama": "Salih \"I go to school by bus\" der. Otobüsle okula giden tek kişi Salih'tir; Hale ve Sinan otobüsten söz etmez."}, {"soru": "\"I sing with my friends in the choir.\"", "cevap": "Hale", "kabul": [], "aciklama": "Hale \"I sing in the choir\" der. Koroda şarkı söyleyen tek kişi Hale'dir."}, {"soru": "\"I study at home in the evening.\"", "cevap": "Sinan", "kabul": [], "aciklama": "Sinan \"I do my homework in the evening\" der. Akşam ödev yapan kişi Sinan'dır; Salih ve Hale akşamdan söz etmez."}, {"soru": "\"My mum and I eat together in the morning.\"", "cevap": "Salih", "kabul": [], "aciklama": "Salih \"I eat breakfast with my mum\" der. Anne ile kahvaltı eden tek kişi Salih'tir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. İsimde küçük yazım hatası kabul edilir. Çözüm: önce üç kısa metni oku, sonra her cümlenin hangi kişinin metnindeki bilgiye uyduğunu bul.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}}, {"id": "HZ-6-s5-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text quickly. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hi, I am Sinan. I help in our school library. I always smile when I greet the students. On Mondays, students borrow books. They return them on Fridays. The library is quiet, so students read silently.", "baslik": "Our School Library"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": "HZ-6-s5-02.jpg", "yerlesim": "yan"}, "alt_sorular": [{"soru": "Sinan greets the students with a ......... .", "cevap": "smile", "kabul": [], "aciklama": "Metindeki \"I always smile when I greet the students\" cümlesi. Sinan öğrencileri gülümseyerek karşılar."}, {"soru": "Students take books home on ......... .", "cevap": "Mondays", "kabul": ["Monday"], "aciklama": "Metindeki \"On Mondays, students borrow books\" cümlesi. \"take books home\" ile \"borrow books\" aynı işi anlatır."}, {"soru": "Students bring the books to the library on ......... .", "cevap": "Fridays", "kabul": ["Friday"], "aciklama": "Metindeki \"They return them on Fridays\" cümlesi. Kitapları getirmek ile geri vermek (return) aynı şeydir. Mondays yazmak."}, {"soru": "Students read ......... in the library.", "cevap": "silently", "kabul": [], "aciklama": "Metindeki \"students read silently\" cümlesi."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Cevap metinde geçen kelimedir; yazım önemli, tek harf hatası yarım puan. Çözüm: cümlenin anlamını düşün, sonra metinde aynı bilgiyi anlatan cümleyi bulup kaldığı boşluğa uyan kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fridays:SARTLI", "mondays:SARTLI"]}}, {"id": "HZ-6-s5-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the text. Answer the questions.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Erol. I walk to school with my sister, Hale. We always arrive early. I am in the school choir. We sing on Fridays. After school, I usually study in the library.", "baslik": "Erol's Day"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Does Erol walk to school with his brother?", "cevap": "No, he does not. He walks to school with his sister.", "kabul": ["No. He walks with his sister."], "aciklama": "Metindeki \"I walk to school with my sister, Hale\" cümlesi. Erol kız kardeşiyle yürür, bu yüzden cevap \"No\" olur ve \"sister\" ile düzeltilir."}, {"soru": "Is Erol in the school choir?", "cevap": "Yes, he is.", "kabul": ["Yes.", "Yes, he is in the school choir."], "aciklama": "Metindeki \"I am in the school choir\" cümlesi. Bilgi doğru olduğu için cevap \"Yes\" olur, düzeltme gerekmez."}, {"soru": "Does the choir sing on Mondays?", "cevap": "No, it does not. It sings on Fridays.", "kabul": ["No. It sings on Fridays."], "aciklama": "Metindeki \"We sing on Fridays\" cümlesi. Gün yanlış olduğu için \"No\" yazılıp doğru gün (Fridays) eklenir."}, {"soru": "Does Erol study in the library before school?", "cevap": "No, he does not. He studies in the library after school.", "kabul": ["No. He studies after school."], "aciklama": "Metindeki \"After school, I usually study in the library\" cümlesi. Zaman yanlıştır (before), doğrusu after school."}, {"soru": "Does Erol arrive early?", "cevap": "Yes, he does.", "kabul": ["Yes.", "Yes, he arrives early."], "aciklama": "Metindeki \"We always arrive early\" cümlesi. \"We\" Erol ve Hale'dir; Erol erken gelir, cevap \"Yes\"."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Yes/No cevabı doğru ve cevap metne uygunsa tam puan; \"No\" cevabında düzeltme eksikse yarım puan. Yazım ve dilbilgisi hatası puan kırdırmaz. Çözüm: önce metinde sorunun bilgisini bul; bilgi aynıysa \"Yes\", farklıysa \"No\" yazıp doğru bilgiyi ekle.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["arrives:SARTLI", "erol's:SARTLI", "fridays:SARTLI", "mondays:SARTLI", "sing:KOK", "sings:SARTLI", "walks:SARTLI"]}, "ornek": "Does Erol go to school by bus? → No, he does not. He walks to school."}, {"id": "HZ-6-s5-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "ipucusuz tamamlama", "yonerge": "Write one word for each sentence.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Students borrow books from the ........ .", "cevap": "library", "kabul": ["school library"], "aciklama": "Kitap ödünç alınan yer kütüphanedir: \"borrow books from the library\"."}, {"soru": "We sing the National ........ at the ceremony.", "cevap": "Anthem", "kabul": ["anthem"], "aciklama": "\"National Anthem\" (İstiklal Marşı gibi ulusal marş) tören kalıbıdır: \"sing the National Anthem\"."}, {"soru": "Hale gives a ........ at the school ceremony.", "cevap": "speech", "kabul": [], "aciklama": "\"give a speech\" (konuşma yapmak) kalıbı; törende konuşma yapılır."}, {"soru": "Please be ........ in the library.", "cevap": "quiet", "kabul": [], "aciklama": "Kütüphane kuralı: \"be quiet\" (sessiz ol)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime sorusu: yazım önemli, tek harf hatası yarım puan. Çözüm: ipucu cümlesini oku, kelimeyi bul ve kutulara harf harf yaz; ortak harfler diğer kelimeyi doğrulamanıza yardım eder.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sing:KOK"]}, "ornek": "We eat ........ at 12:00. → lunch"}, {"id": "HZ-6-s5-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "orta", "soru_tipi": "kelimeyle cümle kurma", "yonerge": "Write a sentence with each word.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": "sira"}, "alt_sorular": [{"soru": "(canteen)", "cevap": "I eat lunch in the canteen.", "kabul": ["We have lunch in the school canteen."], "aciklama": "\"canteen\" okuldaki yemek yeri anlamında kullanılmalı. Örnek: \"I eat lunch in the canteen.\"", "foto": "HZ-6-s5-05_1.jpg"}, {"soru": "(assembly)", "cevap": "There is an assembly on Friday.", "kabul": ["The students are in the assembly."], "aciklama": "\"assembly\" öğretmen ve öğrencilerin toplandığı toplantıdır. Örnek: \"There is an assembly on Friday.\"", "foto": "HZ-6-s5-05_2.jpg"}, {"soru": "(borrow)", "cevap": "I borrow books from the library.", "kabul": ["Students borrow storybooks."], "aciklama": "\"borrow\" ödünç almak demektir; fiil olarak kullanılmalı. Örnek: \"I borrow books from the library.\" I / students ise -s yok).", "foto": "HZ-6-s5-05_3.jpg"}, {"soru": "(poem)", "cevap": "I read a poem at the ceremony.", "kabul": ["Hale reads a poem in the class."], "aciklama": "\"poem\" şiir demektir. Örnek: \"I read a poem at the ceremony.\"", "foto": "HZ-6-s5-05_4.jpg"}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime anlamına uygun kullanılmışsa tam puan; küçük yazım hatası kırılmaz, kelime yanlış kullanılmışsa puan yok. Çözüm: kelimenin anlamını düşün ve onunla okulla ilgili kısa, doğru bir cümle yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "(teacher) → The teacher helps the students."}, {"id": "HZ-6-s5-06", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "hata düzeltme", "yonerge": "There is one mistake in each sentence. Write the correct sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Salih always wake up early.", "cevap": "Salih always wakes up early.", "kabul": [], "aciklama": "Özne Salih (3. tekil) olduğu için geniş zamanda fiile -s gelir: wakes."}, {"soru": "My dad sometimes helps I with my homework.", "cevap": "My dad sometimes helps me with my homework.", "kabul": [], "aciklama": "Fiilden sonra nesne zamiri kullanılır: I yerine me."}, {"soru": "There is many students in the lunch hall.", "cevap": "There are many students in the lunch hall.", "kabul": [], "aciklama": "\"many students\" çoğuldur, bu yüzden \"There are\" kullanılır."}, {"soru": "Hale and Sinan sometimes is late for the ceremony.", "cevap": "Hale and Sinan sometimes are late for the ceremony.", "kabul": [], "aciklama": "İki kişi (Hale and Sinan) çoğuldur, bu yüzden is yerine are gelir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Dilbilgisi sorusu: hedef yapı doğru olmalı; küçük yazım hatası puan kırdırmaz. Çözüm: cümleyi dikkatle oku, yapıyı (fiil biçimi, zamir, there is / are) kontrol et ve yanlış olan tek kısmı düzelt.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "Mum make breakfast. → Mum makes breakfast."}, {"id": "HZ-6-s5-07", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "birinci kişiyi üçüncü kişiye çevirme", "yonerge": "Read Hale's sentences. Write the sentences about Hale.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "I usually walk to school with my brother.", "cevap": "Hale usually walks to school with her brother.", "kabul": [], "baslangic": "Hale", "aciklama": "I yerine Hale yazılır, fiile -s gelir (walks), my yerine her olur."}, {"soru": "I often read books in the library.", "cevap": "Hale often reads books in the library.", "kabul": [], "baslangic": "Hale", "aciklama": "3. tekil kişide read fiiline -s eklenir: reads. Sıklık zarfı (often) fiilden önce kalır."}, {"soru": "I sometimes help my friends with my homework.", "cevap": "Hale sometimes helps her friends with her homework.", "kabul": [], "baslangic": "Hale", "aciklama": "helps (-s) yazılır ve her my her olur: her friends, her homework."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Fiil biçimi (-s) ve sahiplik sözcüğü (her) doğruysa tam puan; küçük yazım hatası puan kırdırmaz. Çözüm: \"I\" yerine kişinin adını yaz, fiile 3. tekil -s ekle, my yerine her kullan.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["goes:SARTLI", "hale's:SARTLI", "walks:SARTLI"]}, "ornek": "I go to school by bus. → Hale goes to school by bus."}, {"id": "HZ-6-s5-08", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W4", "zorluk": "orta", "soru_tipi": "eksik diyalog", "yonerge": "Hale is a new student. Write Sinan's answers. Use your own ideas.", "uyaran": [{"tur": "diyalog", "konusmalar": [{"kisi": "Hale", "soz": "Hi! Where is the canteen?"}, {"kisi": "Sinan", "soz": "", "bosluk": 1}, {"kisi": "Hale", "soz": "What time is lunch?"}, {"kisi": "Sinan", "soz": "", "bosluk": 2}, {"kisi": "Hale", "soz": "How often do you go to the library?"}, {"kisi": "Sinan", "soz": "", "bosluk": 3}, {"kisi": "Hale", "soz": "What do you do after school?"}, {"kisi": "Sinan", "soz": "", "bosluk": 4}]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": "HZ-6-s5-08.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": null, "cevap": "It is near the garden.", "kabul": ["It is in the school."], "aciklama": "Where sorusu yer ister. Okulda gerçekten olabilecek, anlaşılır bir yer (garden, library, lunch hall) yazılır."}, {"soru": null, "cevap": "It is at 12:00.", "kabul": ["Lunch is at 12:00."], "aciklama": "What time sorusu saat ister; \"It is at ...\" kalıbı kullanılır."}, {"soru": null, "cevap": "I often go to the library.", "kabul": ["I go to the library on Fridays."], "aciklama": "How often sorusu sıklık ister; always / often / sometimes / never ile cevap verilir."}, {"soru": null, "cevap": "I do my homework.", "kabul": ["I study in the library.", "I play chess with my friends."], "aciklama": "What do you do sorusu bir eylem ister. Okul sonrası yapılan, anlaşılır bir eylem yazılır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: soruya uygun, anlaşılır her cevap tam puan alır. Çözüm: önce Hale'in sorusunu oku, sonra Sinan'ın ağzından kısa ve doğru bir cümle yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fridays:SARTLI", "sinan's:SARTLI"]}, "ornek": "Where is the library? → It is near the lab."}]}, {"kod": "6-s5d2", "sinif": 6, "ders": "secmeli", "senaryo": 5, "deneme": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 2}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.W4", "tema": "School Life", "metin": "Students can individually construct/form content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations”.", "adet": 1}], "sorular": [{"id": "HZ-6-s5d2-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "bilgi kartı doldurma", "yonerge": "Read the texts quickly. Complete the table.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Sude", "metin": "Hi, I am Sude. I go to school with my sister. I eat lunch in the canteen.", "aciklama": null}, {"kisi": "Ziya", "metin": "Hi, I am Ziya. I go to school with my dad. I eat lunch in the garden.", "aciklama": null}, {"kisi": "Melih", "metin": "Hi, I am Melih. I go to school with my brother. I eat lunch in the lunch hall.", "aciklama": null}]}, {"tur": "tablo", "basliklar": ["Name", "Goes to school with", "Eats lunch in"], "satirlar": [["Sude", {"ornek": "sister"}, {"ornek": "canteen"}], ["Ziya", {"bosluk": 1}, {"bosluk": 2}], ["Melih", {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "dad", "kabul": ["his dad", "father"], "aciklama": "Ziya'nın metnindeki \"I go to school with my dad\" cümlesi. Okula babasıyla gider."}, {"soru": null, "cevap": "garden", "kabul": ["the garden", "school garden"], "aciklama": "Ziya'nın metnindeki \"I eat lunch in the garden\" cümlesi. Öğle yemeğini bahçede yer."}, {"soru": null, "cevap": "brother", "kabul": ["his brother"], "aciklama": "Melih'in metnindeki \"I go to school with my brother\" cümlesi. Okula erkek kardeşiyle gider."}, {"soru": null, "cevap": "lunch hall", "kabul": ["the lunch hall", "hall"], "aciklama": "Melih'in metnindeki \"I eat lunch in the lunch hall\" cümlesi. Öğle yemeğini yemekhanede yer."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: metindeki bilgiye uygun doğru kelime / öbek; küçük yazım hatası kırılmaz. Yanlış / boş: 0. Çözüm: önce örnek satırı metinle karşılaştır, sonra her kişinin metnini hızlıca oku ve tablodaki başlığa uyan bilgiyi bul.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["eats:SARTLI", "goes:SARTLI"]}}, {"id": "HZ-6-s5d2-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the texts quickly. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Sedef", "metin": "I like sports. I run in the race on Friday. I never forget my bag.", "aciklama": null}, {"kisi": "Hakan", "metin": "I like reading. I read a poem at the ceremony. I do my homework after the lessons.", "aciklama": null}, {"kisi": "Engin", "metin": "I like science. I do experiments in the lab. I always listen to my teacher carefully.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I join the race.\"", "cevap": "Sedef", "kabul": [], "aciklama": "Sedef \"I run in the race on Friday\" der. Yarışta koşan tek kişi Sedef'tir."}, {"soru": "\"I follow my teacher's instructions.\"", "cevap": "Engin", "kabul": [], "aciklama": "Engin \"I always listen to my teacher carefully\" der. Öğretmeni dikkatle dinleyen tek kişi Engin'dir."}, {"soru": "\"I finish my homework after school.\"", "cevap": "Hakan", "kabul": [], "aciklama": "Hakan \"I do my homework after the lessons\" der. Ödevini derslerden sonra yapan tek kişi Hakan'dır."}, {"soru": "\"I bring my bag every day.\"", "cevap": "Sedef", "kabul": [], "aciklama": "Sedef \"I never forget my bag\" der. Çantasını unutmayan, yani hep getiren kişi Sedef'tir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. İsimde küçük yazım hatası kabul edilir. Çözüm: önce üç kısa metni oku, sonra her cümlenin hangi kişinin metnindeki bilgiye uyduğunu bul.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["finish:KOK", "run:KOK"]}}, {"id": "HZ-6-s5d2-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Sude. I wake up early. I eat breakfast with my dad. I take the bus to school with my brother, Melih. School starts at 8:30. I usually eat lunch in the canteen with my best friend. After the lessons, I play chess. I always do my homework in the evening.", "baslik": "Sude's School Day"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Sude eats breakfast with her mum.", "cevap": "Sude eats breakfast with her dad.", "kabul": ["Sude eats breakfast with her father."], "aciklama": "Metindeki \"I eat breakfast with my dad\" cümlesi. Sude kahvaltıyı babasıyla yapar; \"mum\" yerine \"dad\" yazılır."}, {"soru": "Sude walks to school with her brother.", "cevap": "Sude takes the bus to school with her brother.", "kabul": ["Sude goes to school by bus with her brother."], "aciklama": "Metindeki \"I take the bus to school with my brother, Melih\" cümlesi. Sude okula otobüsle gider; \"walks\" yerine \"takes the bus\" yazılır."}, {"soru": "School starts at 9:30.", "cevap": "School starts at 8:30.", "kabul": [], "aciklama": "Metindeki \"School starts at 8:30\" cümlesi. Okulun başlama saati 8:30'dur."}, {"soru": "Sude plays chess in the evening.", "cevap": "Sude plays chess after the lessons.", "kabul": ["Sude plays chess after school."], "aciklama": "Metindeki \"After the lessons, I play chess\" cümlesi. Satranç derslerden sonra oynanır; akşam (evening) ödev yapılır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: doğru bilgi içeren cümle; küçük yazım hatası puan kırdırmaz. Kısmi (yarım puan): yalnız doğru kelimeyi yazmak. Yanlış / boş: 0. Çözüm: cümleyi metindeki ilgili cümleyle karşılaştır, uymayan kelimeyi bul ve metindeki doğru bilgiyle değiştir.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["eats:SARTLI", "goes:SARTLI", "plays:SARTLI", "sude's:SARTLI", "takes:SARTLI", "walks:SARTLI"]}, "ornek": "Sude wakes up late. → Sude wakes up early."}, {"id": "HZ-6-s5d2-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "harf ipuçlu tamamlama", "yonerge": "Write the words.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "We play games in the p _ _ _ _ _ _ _ _ _ .", "cevap": "playground", "kabul": ["school playground"], "aciklama": "Harf ipucu: p + 9 harf = 10 harf. Oyun oynanan okul alanı \"playground\" (oyun alanı)."}, {"soru": "Mehmet is the l _ _ _ _ _ of the group.", "cevap": "leader", "kabul": [], "aciklama": "Harf ipucu: l + 5 harf = 6 harf. Grubu yöneten kişi \"leader\" (lider)."}, {"soru": "We do experiments in the s _ _ _ _ _ _ lesson.", "cevap": "science", "kabul": [], "aciklama": "Harf ipucu: s + 6 harf = 7 harf. Deney yapılan ders \"science\" (fen bilimleri)."}, {"soru": "Elif is e _ _ _ _ _ _ for Sports Day.", "cevap": "excited", "kabul": [], "aciklama": "Harf ipucu: e + 6 harf = 7 harf. Spor gününü heyecanla bekleyen kişi \"excited\" (heyecanlı)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime sorusu: yazım önemli, tek harf hatası yarım puan. Çözüm: cümlenin anlamını düşün, verilen harflerle başla ve boşluk sayısı kadar harf yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "We eat l _ _ _ _ at 12:00. → lunch"}, {"id": "HZ-6-s5d2-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "orta", "soru_tipi": "kelimeyle cümle kurma", "yonerge": "Write a sentence with each word.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(greet)", "cevap": "The headmaster greets the students.", "kabul": ["I greet my teacher in the morning."], "aciklama": "\"greet\" selamlamak demektir. Örnek: \"I greet my teacher in the morning.\" Özne 3. tekil kişiyse fiile -s gelir (greets)."}, {"soru": "(parade)", "cevap": "There is a parade on Republic Day.", "kabul": ["Mehmet carries the flag in the parade."], "aciklama": "\"parade\" geçit töreni demektir. Örnek: \"There is a parade on Republic Day.\""}, {"soru": "(volunteer)", "cevap": "I volunteer for the school ceremony.", "kabul": ["Sude and Elif volunteer for the race."], "aciklama": "\"volunteer\" gönüllü olmak demektir, burada fiil olarak kullanılır. Örnek: \"I volunteer for the school ceremony.\""}, {"soru": "(flag)", "cevap": "The flag is on the stage.", "kabul": ["We carry the flag in the parade."], "aciklama": "\"flag\" bayrak demektir. Örnek: \"We carry the flag in the parade.\""}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime anlamına uygun kullanılmışsa tam puan; küçük yazım hatası kırılmaz, kelime yanlış kullanılmışsa puan yok. Çözüm: kelimenin anlamını düşün ve onunla okulla ilgili kısa, doğru bir cümle yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["carries:SARTLI"]}, "ornek": "(library) → I read books in the library."}, {"id": "HZ-6-s5d2-06", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "nesne zamiri tamamlama", "yonerge": "Write one word for each sentence.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Ziya is my friend. I help ........ with his homework.", "cevap": "him", "kabul": [], "aciklama": "Ziya bir erkektir ve fiil \"help\"ten sonra nesne zamiri gelir: Ziya yerine \"him\"."}, {"soru": "Sude is my best friend. I often study with ........ .", "cevap": "her", "kabul": [], "aciklama": "Sude bir kızdır ve \"with\" sözcüğünden sonra nesne zamiri gelir: Sude yerine \"her\"."}, {"soru": "My books are on the desk. I put ........ in my bag.", "cevap": "them", "kabul": [], "aciklama": "\"My books\" çoğuldur ve fiil \"put\"tan sonra nesne zamiri gelir: books yerine \"them\"."}, {"soru": "My friends and I are in the choir. Our teacher helps ........ with the songs.", "cevap": "us", "kabul": [], "aciklama": "\"My friends and I\" yani biz; fiil \"helps\"ten sonra nesne zamiri gelir: \"us\"."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: doğru zamir (him, her, them, us); küçük yazım hatası puan kırdırmaz. Yanlış / boş: 0. Çözüm: önce cümlede kimden / neden söz edildiğine bak, sonra fiilden sonra gelen nesne zamirini seç.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "Mr Yavuz is our teacher. We listen to ........ . → him"}, {"id": "HZ-6-s5d2-07", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "karışık kelimelerden cümle kurma", "yonerge": "Put the words in the correct order. Write the sentences.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "early / Ziya / wakes up / always", "cevap": "Ziya always wakes up early.", "kabul": [], "aciklama": "Özne (Ziya) başta, sıklık zarfı (always) ana fiilden önce gelir: Ziya always wakes up early."}, {"soru": "my friends / lunch / with / I / eat", "cevap": "I eat lunch with my friends.", "kabul": [], "aciklama": "Sıra: özne (I) + fiil (eat) + nesne (lunch) + with my friends."}, {"soru": "never / are / late / we / for school", "cevap": "We are never late for school.", "kabul": [], "aciklama": "\"be\" fiilinde (are) sıklık zarfı fiilden sonra gelir: We are never late for school."}, {"soru": "songs / on Friday / sings / the choir", "cevap": "The choir sings songs on Friday.", "kabul": [], "aciklama": "Özne (The choir) + fiil (sings) + nesne (songs) + zaman (on Friday)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: kelimeler doğru sırada, cümle doğru; küçük yazım hatası puan kırdırmaz. Kelimeler doğru ama sıra yanlışsa 0. Çözüm: önce özneyi bul, sonra fiili ve zarfı yerleştir; cümleyi sesli okuyup anlamlı mı kontrol et.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sings:SARTLI"]}}, {"id": "HZ-6-s5d2-08", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W4", "zorluk": "orta", "soru_tipi": "cümle genişletme", "yonerge": "Write the sentences again. Add a place or a time.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Sude reads storybooks. (where)", "cevap": "Sude reads storybooks in the library.", "kabul": ["Sude reads storybooks in the reading corner."], "aciklama": "Parantezde \"where\" yazıyor: cümleye bir yer eklenir (in the library, in the garden, at home)."}, {"soru": "The students eat lunch. (when)", "cevap": "The students eat lunch at 12:00.", "kabul": ["The students eat lunch after the lessons."], "aciklama": "Parantezde \"when\" yazıyor: cümleye bir zaman eklenir (at 12:00, after the lessons)."}, {"soru": "Ziya does his homework. (when)", "cevap": "Ziya does his homework in the evening.", "kabul": ["Ziya does his homework after school."], "aciklama": "Parantezde \"when\" yazıyor: zaman eklenir (in the evening, after school)."}, {"soru": "Our teacher helps us. (where)", "cevap": "Our teacher helps us in the classroom.", "kabul": ["Our teacher helps us in the lab."], "aciklama": "Parantezde \"where\" yazıyor: yer eklenir (in the classroom, in the lab)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: cümleye uygun, anlaşılır bir yer ya da zaman eklenmişse tam puan. Çözüm: parantezdeki soruya (where / when) bak; yer için in the ..., zaman için at ... ya da in the ... gibi kısa bir öbek ekle.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "We play chess. (where) → We play chess in the garden."}]}, {"kod": "6-s5d3", "sinif": 6, "ders": "secmeli", "senaryo": 5, "deneme": 3, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "ENG.6.1.R2", "tema": "School Life", "metin": "Students can bring information about the current content on “school life with roles, and responsibilities at school; school routines; national days and celebrations” through skimming (looking quickly at) the audio-visual elements and reading the content very quickly.", "adet": 2}, {"kod": "ENG.6.1.R3", "tema": "School Life", "metin": "Students can make meaning of / derive meaning from the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” by reading it carefully.", "adet": 1}, {"kod": "ENG.6.1.V1", "tema": "School Life", "metin": "Students can select and use the target vocabulary of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.G1", "tema": "School Life", "metin": "Students can select and use the target grammatical elements of the current content about “school life with roles, and responsibilities at school; school routines; national days and celebrations” accurately, authentically, spontaneously, and naturally and use it appropriately and effectively when communicating with others.", "adet": 2}, {"kod": "ENG.6.1.W4", "tema": "School Life", "metin": "Students can individually construct/form content for the assigned writing task on the current content “school life with roles, and responsibilities at school; school routines; national days and celebrations”.", "adet": 1}], "sorular": [{"id": "HZ-6-s5d3-01", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "duyurunun yerini bulma", "yonerge": "Read the notices. Where can you see them? Write the places.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Notice 1", "metin": "Eat your lunch here. Clean the table before you leave.", "aciklama": null}, {"kisi": "Notice 2", "metin": "Draw pictures here. Paint with your friends. Bring your drawings on Friday.", "aciklama": null}, {"kisi": "Notice 3", "metin": "Play games here with your friends. Come to your class when you hear the bell.", "aciklama": null}, {"kisi": "Notice 4", "metin": "There is an assembly at 9:00. Sit down and listen to the headmaster.", "aciklama": null}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(1)", "cevap": "canteen", "kabul": ["lunch hall", "in the canteen", "in the lunch hall"], "aciklama": "\"Eat your lunch\" (öğle yemeğini ye) ve \"Clean the table\" (masayı temizle) yemek yenen yeri gösterir: canteen ya da lunch hall."}, {"soru": "(2)", "cevap": "art club", "kabul": ["in the art club", "the art club"], "aciklama": "\"Draw pictures\" (resim çiz) ve \"Paint\" (boya yap) resim çalışmasının yapıldığı yeri, yani art club'ı gösterir."}, {"soru": "(3)", "cevap": "playground", "kabul": ["in the playground", "the playground", "school playground"], "aciklama": "\"Play games here\" (burada oyun oyna) ve \"when you hear the bell\" (zili duyunca) teneffüste oyun oynanan yeri, yani playground'u gösterir."}, {"soru": "(4)", "cevap": "conference hall", "kabul": ["assembly hall", "in the conference hall", "hall"], "aciklama": "\"assembly\" (toplantı) ve \"listen to the headmaster\" (müdürü dinle) bütün öğrencilerin toplandığı büyük salonu gösterir: conference hall ya da assembly hall."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: duyuruya uygun doğru yer (yazım hatası kırılmaz). Kısmi: yok. Boş / yanlış yer: 0. Çözüm: her duyuruyu oku; eşya (table, pictures), eylem (eat, paint, play) ve zaman ipuçlarına bak, bu şeylerin yapıldığı yeri yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["notices:SARTLI", "paint:KOK"]}}, {"id": "HZ-6-s5d3-02", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R2", "zorluk": "kolay", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text quickly. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Melih. I am the leader of our school art club. We meet in the classroom on Wednesdays. The club starts after the lessons. Our teacher, Mr Yavuz, explains the pictures clearly. At the end, the students share their drawings.", "baslik": "Our Art Club"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "The ......... of the art club is Melih.", "cevap": "leader", "kabul": [], "aciklama": "Metindeki \"I am the leader of our school art club\" cümlesi. Kulübü yöneten kişi Melih, yani \"leader\"."}, {"soru": "The students come to the club on ......... .", "cevap": "Wednesdays", "kabul": ["Wednesday"], "aciklama": "Metindeki \"We meet in the classroom on Wednesdays\" cümlesi. \"come to the club\" ile \"meet\" aynı işi anlatır."}, {"soru": "The club is in a ......... .", "cevap": "classroom", "kabul": ["class"], "aciklama": "Metindeki \"We meet in the classroom\" cümlesi. Kulübün toplandığı yer \"classroom\"."}, {"soru": "The students show their ......... to the class at the end.", "cevap": "drawings", "kabul": ["drawing"], "aciklama": "Metindeki \"the students share their drawings\" cümlesi. \"show\" ile \"share\" benzer anlamdadır; kelime \"drawings\"."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Cevap metinde geçen kelimedir; yazım önemli, tek harf hatası yarım puan. Çözüm: cümlenin anlamını düşün, sonra metinde aynı bilgiyi anlatan cümleyi bulup kaldığı boşluğa uyan kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["drawing:KOK", "meet:KOK", "wednesdays:SARTLI"]}}, {"id": "HZ-6-s5d3-03", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.R3", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "The sentences are not in the correct order. Write the correct order.", "uyaran": [{"tur": "metin", "metin": "A) Yes, it is. I see my friends on the bus.\nB) Hi, Ziya! How do you come to school?\nC) I usually take the bus.\nD) Wow, that is great!\nE) I always walk with my dad. And you?\nF) Is it fun?", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "D"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "B bir soru sorar (How do you come to school?); ona cevap veren ve \"And you?\" diye soran satır E'dir."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "E'deki \"And you?\" sorusuna cevap C'dir: \"I usually take the bus.\""}, {"soru": null, "cevap": "F", "kabul": [], "aciklama": "C'de otobüsten söz edilir; \"Is it fun?\" sorusundaki \"it\" otobüstür, bu yüzden F gelir."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "F'deki \"Is it fun?\" sorusuna cevap A'dır: \"Yes, it is.\" Sonra D ile diyalog biter."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Tam: doğru harf. Yanlış / boş: 0. Çözüm: önce bütün satırları oku. Soruyu ve ona verilen cevabı eşleştir (Is it fun? → Yes, it is.), ilk ve son satırı örnekten al, kalan satırları sırala.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-6-s5d3-04", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "karışık harflerden kelime", "yonerge": "Complete the sentences. Write the words in the correct order.", "uyaran": [], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "We eat lunch in the ........ . (n t e e a c n)", "cevap": "canteen", "kabul": [], "aciklama": "Harfler: c-a-n-t-e-e-n (7 harf). \"canteen\" okulda yemek yenen yerdir; \"n\" ve \"e\" ikişer kez kullanılır."}, {"soru": "I sit at my ........ in the classroom. (k s e d)", "cevap": "desk", "kabul": [], "aciklama": "Harfler: d-e-s-k (4 harf). Sınıfta oturulan sıra \"desk\" (sıra / masa)."}, {"soru": "We hear the ........ every morning. (l e b l)", "cevap": "bell", "kabul": [], "aciklama": "Harfler: b-e-l-l (4 harf). Okulda ders başını bildiren ses \"bell\" (zil); \"l\" iki kez kullanılır."}, {"soru": "Elif is my best ........ . (d r f i e n)", "cevap": "friend", "kabul": [], "aciklama": "Harfler: f-r-i-e-n-d (6 harf). \"best friend\" (en iyi arkadaş) kalıbı."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime sorusu: yazım önemli, tek harf hatası yarım puan. Çözüm: cümleyi oku, boşluğa hangi kelimenin uyduğunu düşün, sonra harfleri sırala ve harf sayısını kontrol et.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "Hale and Sude are in the same ........ . (a s c l s) → class"}, {"id": "HZ-6-s5d3-05", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.V1", "zorluk": "kolay", "soru_tipi": "metindeki kelimeleri gruba yazma", "yonerge": "Read the text. Write the words in the boxes.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Hakan. In the morning, my friend and I line up in the garden. Then we go to the classroom with our teacher. After school, I join the chess club on Mondays and the art club on Fridays.", "baslik": "Hakan's Day"}, {"tur": "tablo", "basliklar": ["Group", "Word", "Word"], "satirlar": [["Places", {"bosluk": 1}, {"bosluk": 2}], ["People", {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "garden", "kabul": ["classroom"], "aciklama": "Metinde iki yer vardır: \"in the garden\" ve \"to the classroom\". Bu iki kelimeden biri yazılır."}, {"soru": null, "cevap": "classroom", "kabul": ["garden"], "aciklama": "İkinci yer kutusuna, birinci kutuda yazılmayan yer yazılır: garden ya da classroom."}, {"soru": null, "cevap": "friend", "kabul": ["teacher"], "aciklama": "Metinde iki kişi vardır: \"my friend\" ve \"our teacher\". Bu iki kelimeden biri yazılır."}, {"soru": null, "cevap": "teacher", "kabul": ["friend"], "aciklama": "İkinci kişi kutusuna, birinci kutuda yazılmayan kişi yazılır: teacher ya da friend."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: metinde geçen ve gruba uyan kelime; iki kutuda aynı kelime olmaz, sıra serbesttir. Küçük yazım hatası yarım puan. Çözüm: metni oku; yer, kişi gibi grubun adına uyan kelimeleri bul ve kutulara yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fridays:SARTLI", "hakan's:SARTLI", "mondays:SARTLI"]}}, {"id": "HZ-6-s5d3-06", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "sıklık zarfını yerleştirme", "yonerge": "Write the sentences again. Use the word after each sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Sude is on time for school. (always)", "cevap": "Sude is always on time for school.", "kabul": [], "aciklama": "\"be\" fiilinin (is) SONRASINA gelir: is + always. Zarf cümle sonuna gitmez."}, {"soru": "Ziya helps his friends. (often)", "cevap": "Ziya often helps his friends.", "kabul": ["Often Ziya helps his friends."], "aciklama": "Sıklık zarfı ana fiilden ÖNCE gelir: often + helps."}, {"soru": "The choir sings songs on the stage. (sometimes)", "cevap": "The choir sometimes sings songs on the stage.", "kabul": ["Sometimes the choir sings songs on the stage."], "aciklama": "Zarf ana fiilden önce gelir: choir + sometimes + sings. Cümle başında \"Sometimes\" da kabul edilir."}, {"soru": "We are late for the ceremony. (never)", "cevap": "We are never late for the ceremony.", "kabul": [], "aciklama": "\"be\" fiilinde (are) zarf fiilden SONRA gelir: are + never."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Dilbilgisi sorusu: hedef yapı doğru olmalı; küçük yazım hatası puan kırdırmaz. Çözüm: \"am / is / are\" fiilinden SONRA, diğer fiillerden ÖNCE gelen sıklık zarfını yerine koyarak cümleyi yeniden yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["sings:SARTLI"]}, "ornek": "Elif is quiet in the library. (always) → Elif is always quiet in the library."}, {"id": "HZ-6-s5d3-07", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.G1", "zorluk": "orta", "soru_tipi": "çizelgeden cümle yazma", "yonerge": "Look at the table. Write sentences about Sedef.", "uyaran": [{"tur": "tablo", "basliklar": ["Sedef", "How often"], "satirlar": [["go to the library", "always"], ["walk to school", "often"], ["read storybooks", "sometimes"], ["play chess", "never"]], "baslik": "Sedef"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Sedef / walk to school", "cevap": "Sedef often walks to school.", "kabul": [], "aciklama": "Tabloda \"walk to school\" satırı: often. Zarf fiilden önce gelir ve fiile -s eklenir: often walks."}, {"soru": "Sedef / read storybooks", "cevap": "Sedef sometimes reads storybooks.", "kabul": [], "aciklama": "Tabloda \"read storybooks\" satırı: sometimes. Sedef 3. tekil kişi olduğu için fiile -s gelir: reads."}, {"soru": "Sedef / play chess", "cevap": "Sedef never plays chess.", "kabul": [], "aciklama": "Tabloda \"play chess\" satırı: never. \"never\" ile fiil olumlu kalır ve -s alır: never plays."}, {"soru": "Sedef / go to the library", "cevap": "Sedef always goes to the library.", "kabul": [], "aciklama": "Tabloda \"go to the library\" satırı: always. \"go\" fiilinin 3. tekil biçimi \"goes\" olur."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Tam: tablodaki bilgiye uygun, sıklık sözcüğü doğru yerde ve fiili doğru biçimde (-s) yazılmış cümle. Kısmi (yarım puan): bilgi doğru ama zarf yanlış yerde ya da -s eksik. Bilgi yanlış / boş: 0. Çözüm: önce örnekteki kalıba bak; her satırda zarf ana fiilden önce gelir ve Sedef için fiile -s eklenir.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["comes:SARTLI", "goes:SARTLI", "plays:SARTLI", "walks:SARTLI"]}, "ornek": "Sedef / come to school early (usually) → Sedef usually comes to school early."}, {"id": "HZ-6-s5d3-08", "sinif": 6, "tema": 1, "tema_adi": "School Life", "kazanim": "ENG.6.1.W4", "zorluk": "orta", "soru_tipi": "cümle başlangıçlarını tamamlama", "yonerge": "Complete the sentences about you. Use your own ideas.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "In the morning, I ", "cevap": "wake up early.", "kabul": ["eat breakfast with my mum.", "go to school by bus."], "aciklama": "Sabah yaptığın bir işi yaz: I + fiil (wake up, eat breakfast, go to school...). Anahtardakiler örnektir."}, {"soru": "My favourite place at school is ", "cevap": "the library.", "kabul": ["the garden.", "the playground."], "aciklama": "Okuldaki sevdiğin bir yeri yaz (the library, the garden, the canteen...). Anahtardakiler örnektir."}, {"soru": "I sometimes ", "cevap": "read storybooks.", "kabul": ["play chess with my friends.", "help my teacher."], "aciklama": "\"sometimes\" ile bazen yaptığın bir işi yaz: fiil yalın biçimde kalır (I sometimes read...). Anahtardakiler örnektir."}, {"soru": "At the ceremony, I feel ", "cevap": "happy.", "kabul": ["excited.", "so excited."], "aciklama": "\"feel\" fiilinden sonra duygu bildiren bir sözcük yaz (happy, excited, ...). Anahtardakiler örnektir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: soruya uygun, anlaşılır her cevap tam puan alır. Çözüm: cümle başını oku, anlamlı ve kısa bir bitiş yaz.", "kelime_kontrol": {"izinli_havuz": "6. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "My teacher is ... → My teacher is Mr Yavuz."}]}, {"kod": "7-s1", "sinif": 7, "ders": "secmeli", "senaryo": 1, "deneme": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 1}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 1}, {"kod": "E7.2.W1", "tema": "Sports", "metin": "Students will be able to write pieces about routines/daily activities by using frequency adverbs.", "adet": 1}], "sorular": [{"id": "HZ-7-s1-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Kevin and Joe are best friends. They are very different. Kevin is tall and slim. He has short, straight, black hair and brown eyes. He is hardworking, so his marks are higher than Joe's marks. Joe is shorter than Kevin, but he is funnier. Joe is outgoing, and he has a lot of friends because he is friendly. Kevin is not very outgoing. He likes reading books at home.", "baslik": "Two Best Friends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Kevin is shorter than Joe.", "cevap": "Kevin is taller than Joe.", "kabul": ["Joe is shorter than Kevin.", "Kevin is taller."], "aciklama": "Metinde \"Joe is shorter than Kevin\" yazıyor. Yani Kevin daha uzun: \"taller than\"."}, {"soru": "Joe is hardworking, so his marks are higher than Kevin's marks.", "cevap": "Kevin is hardworking, so his marks are higher than Joe's marks.", "kabul": ["Kevin's marks are higher than Joe's marks.", "Joe's marks are worse than Kevin's marks."], "aciklama": "Metindeki \"He is hardworking, so his marks are higher than Joe's marks\" cümlesinde \"He\" Kevin'dir. Yanlış kişi Joe yazılmış."}, {"soru": "Kevin is more outgoing than Joe.", "cevap": "Joe is more outgoing than Kevin.", "kabul": ["Kevin is not very outgoing."], "aciklama": "Metinde \"Joe is outgoing\" ve \"Kevin is not very outgoing\" yazıyor. Karşılaştırma: \"Joe is more outgoing than Kevin\"."}, {"soru": "Kevin has long, curly hair.", "cevap": "Kevin has short, straight hair.", "kabul": ["Kevin has short, straight, black hair.", "He has short, straight hair."], "aciklama": "Metinde \"He has short, straight, black hair\" yazıyor. Saç tarifi (short, straight) metinden alınır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Cümle metne uygun düzeltilmişse tam puan; yazım ve küçük dilbilgisi hatası puan kırdırmaz; cümle yanlış kalmışsa ya da yanlış kişi/bilgi yazılmışsa puan yok. Çözüm: önce metni oku, sonra her cümleyi metindeki bilgiyle karşılaştır ve yanlış olan kısmı metne göre değiştir.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["joe's:SARTLI", "kevin's:SARTLI"]}}, {"id": "HZ-7-s1-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "tabloya göre karşılaştırma cümleleri", "yonerge": "Look at the chart. Compare Nazan and Mehmet. Write sentences.", "uyaran": [{"tur": "tablo", "basliklar": ["", "Nazan", "Mehmet"], "satirlar": [["age", "14", "15"], ["height", "160 cm", "172 cm"], ["weight", "55 kg", "52 kg"], ["marks", "95", "80"], ["friends", "5", "12"], ["character", "hardworking", "outgoing"]], "baslik": "Nazan and Mehmet"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-7-s1-02.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "(height)", "cevap": "Mehmet is taller than Nazan.", "kabul": ["Nazan is shorter than Mehmet."], "aciklama": "Mehmet 172 cm, Nazan 160 cm. Kısa sıfat + -er + than: \"taller than\" / \"shorter than\"."}, {"soru": "(weight)", "cevap": "Nazan is heavier than Mehmet.", "kabul": ["Mehmet is slimmer than Nazan.", "Mehmet is thinner than Nazan."], "aciklama": "Nazan 55 kg, Mehmet 52 kg. Nazan daha ağır: \"heavier than\". Mehmet için \"slimmer / thinner than\" da olur."}, {"soru": "(marks)", "cevap": "Nazan's marks are higher than Mehmet's marks.", "kabul": ["Nazan's marks are higher than Mehmet's.", "Mehmet's marks are worse than Nazan's marks."], "aciklama": "Nazan 95, Mehmet 80 almış. Notlar için \"higher than\" kullanılır."}, {"soru": "(friends / because)", "cevap": "Mehmet has more friends than Nazan because he is outgoing.", "kabul": ["Mehmet has more friends because he is outgoing.", "Mehmet has 12 friends, but Nazan has 5 friends, because he is more outgoing."], "aciklama": "Mehmet 12, Nazan 5 arkadaşa sahip. Nedeni \"because\" ile tablodaki karakter satırından yaz: Mehmet outgoing."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Bilgi tabloya uygun ve karşılaştırma yapısı (-er ... than / more ... than) doğruysa tam puan; bilgi doğru ama yapı ya da ad hatalıysa yarım puan; bilgi yanlışsa puan yok. Çözüm: önce tablodaki iki değere bak, hangisinin daha büyük/fazla olduğunu bul, sonra örnekteki gibi cümle kur.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["character:KOK", "mehmet's:SARTLI", "nazan's:SARTLI"]}, "ornek": "(age) Mehmet is older than Nazan."}, {"id": "HZ-7-s1-03", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the text. Who says these sentences? Write the names.", "uyaran": [{"tur": "metin", "metin": "Helen, Robert, Ali and Sally are friends. Helen is a swimmer. She trains at the swimming pool three times a week, and she always eats a big breakfast. Robert prefers team sports. He plays basketball for the school team, and he works out at the gym twice a week. Ali doesn't like exercises. He seldom does sports, but he watches matches on TV every weekend. Sally wakes up early every morning and goes jogging in the park. She never eats junk food.", "baslik": "Four Friends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I play with my school team.\"", "cevap": "Robert", "kabul": [], "aciklama": "\"He plays basketball for the school team\" cümlesi Robert hakkında. Okul takımında oynayan tek kişi o."}, {"soru": "\"I run in the park every morning.\"", "cevap": "Sally", "kabul": [], "aciklama": "\"Sally wakes up early every morning and goes jogging in the park.\" Parkta koşan tek kişi Sally."}, {"soru": "\"I go swimming three times a week.\"", "cevap": "Helen", "kabul": [], "aciklama": "Metinde yalnız Helen yüzücü ve havuzda haftada üç kez antrenman yapıyor (\"trains at the swimming pool three times a week\")."}, {"soru": "\"I do not often exercise.\"", "cevap": "Ali", "kabul": [], "aciklama": "Metinde Ali için \"He seldom does sports\" yazıyor; \"seldom\" ile \"not often\" aynı anlama gelir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce metni oku, sonra cümledeki bilgiyi metinde ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["matches:SARTLI", "says:SARTLI", "watches:SARTLI", "weekend:KOK", "works:SARTLI"]}}, {"id": "HZ-7-s1-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.W1", "zorluk": "orta", "soru_tipi": "çizelge → sıklık zarfı cümleleri", "yonerge": "Look at Rachel's chart. Write sentences about Rachel. Use frequency adverbs.", "uyaran": [{"tur": "tablo", "basliklar": ["Activity", "How often?"], "satirlar": [["wake up early", "always"], ["eat fruit", "usually"], ["play basketball", "twice a week"], ["watch a match", "sometimes"], ["eat junk food", "never"]], "baslik": "Rachel's Routine"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-7-s1-04.jpg", "yerlesim": "ust"}, "alt_sorular": [{"soru": "(eat fruit)", "cevap": "Rachel usually eats fruit.", "kabul": [], "aciklama": "Tabloda \"usually\" yazıyor. Sıklık zarfı özneden sonra, fiilden önce gelir; Rachel tekil olduğu için \"eats\"."}, {"soru": "(play basketball)", "cevap": "Rachel plays basketball twice a week.", "kabul": ["Rachel plays basketball two times a week."], "aciklama": "\"Twice a week\" cümlenin sonuna yazılır."}, {"soru": "(watch a match)", "cevap": "Rachel sometimes watches a match.", "kabul": [], "aciklama": "\"Sometimes\" özneden sonra gelir; \"watch\" fiili 3. tekilde \"watches\" olur."}, {"soru": "(eat junk food)", "cevap": "Rachel never eats junk food.", "kabul": [], "aciklama": "\"Never\" kendi başına olumsuz anlam taşır. Fiil: \"eats\"."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Bilgi tabloya uygun, sıklık zarfı (ya da once / twice / times a week) doğru yerde ve fiil doğru biçimdeyse (3. tekil -s) tam puan; bilgi doğru ama dil hatalıysa yarım puan; bilgi yanlışsa puan yok. Çözüm: önce tablodaki sıklığa bak, sonra örnekteki gibi ad + sıklık zarfı + fiil sırasıyla yaz.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["rachel's:SARTLI", "watches:SARTLI"]}, "ornek": "(wake up early) Rachel always wakes up early."}]}, {"kod": "7-s1d2", "sinif": 7, "ders": "secmeli", "senaryo": 1, "deneme": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 1}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 1}, {"kod": "E7.2.W1", "tema": "Sports", "metin": "Students will be able to write pieces about routines/daily activities by using frequency adverbs.", "adet": 1}], "sorular": [{"id": "HZ-7-s1d2-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Read the sentences from a dialogue. Complete the chart with A, B, C, D, E or F to make the correct dialogue.", "uyaran": [{"tur": "metin", "metin": "A) He is fifteen years old. He is taller than me.\nB) He is easy-going and friendly. He is funnier than me!\nC) Yes, I do. His name is Osman.\nD) What is he like?\nE) Do you have a brother, Mandy?\nF) How old is he?", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "E"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "B"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "C", "kabul": [], "aciklama": "Birinci satır \"Do you have a brother?\" sorusudur; cevap \"Yes, I do.\" ile başlar ve erkek kardeşin adını verir."}, {"soru": null, "cevap": "F", "kabul": [], "aciklama": "Kardeşin adı söylendikten sonra yaşı sorulur: \"How old is he?\""}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "\"How old is he?\" sorusunun cevabı yaşı söyleyen \"He is fifteen years old.\" cümlesidir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "Son cevap kişiliği anlatır (\"easy-going and friendly\"), bu yüzden hemen önceki soru kişiliği soran \"What is he like?\" olmalıdır."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan, yanlış ya da boş harf puan almaz. Çözüm yolu: önce ilk ve son satırı oku; her soruyu, hemen ardından gelen cevapla eşleştir; sonra sırayı baştan sona oku.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-7-s1d2-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "notlardan afiş", "yonerge": "Read the notes. Then complete the poster.", "uyaran": [{"tur": "metin", "metin": "Guess Who? Monday, in Room 2. Students describe a person. Friends guess the name.", "baslik": "Notes"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["Activity", {"bosluk": 1}], ["Time", {"bosluk": 2}], ["Place", {"bosluk": 3}], ["Students", {"bosluk": 4}]], "baslik": "POSTER"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Guess Who?", "kabul": ["Guess Who"], "aciklama": "Notların ilk kelimeleri etkinliğin adıdır: \"Guess Who?\". Activity kutusuna etkinliğin adı yazılır."}, {"soru": null, "cevap": "on Monday", "kabul": ["Monday"], "aciklama": "Notlarda zaman olarak \"Monday\" yazıyor. Time kutusuna gün yazılır."}, {"soru": null, "cevap": "Room 2", "kabul": ["2", "in Room 2"], "aciklama": "Notlarda yer olarak \"in Room 2\" yazıyor. Place kutusuna yer yazılır."}, {"soru": null, "cevap": "describe a person", "kabul": ["Students describe a person."], "aciklama": "Notlardaki \"Students describe a person.\" cümlesi öğrencilerin ne yaptığını söyler. Students kutusuna bu eylem yazılır."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Nottaki bilgi doğru kutuya aktarılmışsa tam puan; yazım hatası puan kırdırmaz; bilgi yanlış ya da boşsa puan yok. Çözüm yolu: önce notları oku; sonra her kutunun başlığına (Activity, Time, Place, Students) bak ve notta o soruyu cevaplayan kısmı kutuya yaz.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["notes:SARTLI"]}}, {"id": "HZ-7-s1d2-03", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the text. Answer the questions.", "uyaran": [{"tur": "metin", "metin": "Ali is a young football player. He plays for his school team on Saturdays. He trains twice a week with his coach, Mr Wilson. Ali eats a lot of vegetables and fruit, and he drinks water every day. He seldom eats junk food. Last year, his team won a big match.", "baslik": "Ali's Team"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Does Ali train with his coach?", "cevap": "Yes, he does.", "kabul": ["Yes.", "Yes, he trains with his coach."], "aciklama": "Metindeki \"He trains twice a week with his coach, Mr Wilson\" cümlesi soruyla uyuşur; cevap Yes."}, {"soru": "Does Ali drink water every day?", "cevap": "Yes, he does.", "kabul": ["Yes.", "Yes, he drinks water every day."], "aciklama": "Metindeki \"he drinks water every day\" cümlesi soruyla uyuşur; cevap Yes."}, {"soru": "Does Ali play for his school team on Sundays?", "cevap": "No, he does not. He plays on Saturdays.", "kabul": ["No. He plays on Saturdays.", "No, he doesn't. He plays on Saturdays."], "aciklama": "Metinde \"He plays for his school team on Saturdays\" yazıyor; Pazar değil, Cumartesi. \"Does\" ile sorulan soruya \"No, he does not.\" denir."}, {"soru": "Does Ali eat junk food every day?", "cevap": "No, he does not. He seldom eats junk food.", "kabul": ["No. He seldom eats junk food.", "No, he doesn't. He seldom eats junk food."], "aciklama": "Metinde \"He seldom eats junk food\" yazıyor; seldom = nadiren. Her gün yemediği için cevap No."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Yes/No doğru ve (No ise) düzeltme metne uygunsa tam puan; yalnız doğru Yes ya da No yazılmışsa yarım puan. Yazım ve dilbilgisi hatası puan kırdırmaz. Çözüm yolu: önce soruyu oku; cevabı metinde ara; bilgi doğruysa Yes, değilse No yaz ve No ise metindeki doğru bilgiyi ikinci cümlede ver.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["ali's:SARTLI", "saturdays:SARTLI"]}, "ornek": "Does Ali play tennis? → No, he does not. He plays football."}, {"id": "HZ-7-s1d2-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.W1", "zorluk": "orta", "soru_tipi": "cümle başlangıçlarını tamamlama", "yonerge": "Complete the sentences about you and your friends.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "I always ", "cevap": "eat fruit in the morning.", "kabul": ["drink water.", "wake up early."], "aciklama": "Sıklık zarfı always özneden sonra gelir; ardından yalın fiil yazılır (I always eat ...)."}, {"soru": "My best friend seldom ", "cevap": "eats junk food.", "kabul": ["watches TV.", "plays football."], "aciklama": "Özne 3. tekil (my best friend) olduğu için fiil -s alır: seldom eats / plays / watches."}, {"soru": "On weekends, I usually ", "cevap": "play football with my friends.", "kabul": ["go to the park.", "ride my bike."], "aciklama": "usually özneden sonra gelir; ardından yalın fiil ve bir etkinlik yazılır."}, {"soru": "I do exercise ", "cevap": "three times a week.", "kabul": ["twice a week.", "every morning."], "aciklama": "Sıklık \"once / twice / three times a week\" ya da \"every morning\" gibi bir ifadeyle söylenir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: cümle başlangıcına dilbilgisi olarak uyan ve anlamlı her cevap tam puan alır (sıklık zarfı doğru yerde, fiil doğru biçimde olmalı); anlamsız ya da başlangıca uymayan cevap puan almaz. Çözüm yolu: önce örneği oku; sonra cümlenin başını ve sonunu birleştirerek anlamlı olup olmadığına bak.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["watches:SARTLI"]}, "ornek": "I sometimes play tennis."}]}, {"kod": "7-s1d3", "sinif": 7, "ders": "secmeli", "senaryo": 1, "deneme": 3, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 1}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 1}, {"kod": "E7.2.W1", "tema": "Sports", "metin": "Students will be able to write pieces about routines/daily activities by using frequency adverbs.", "adet": 1}], "sorular": [{"id": "HZ-7-s1d3-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hello, I'm Albert. Mark is my best friend. He is a handsome boy with short, wavy, dark hair and brown eyes. He is well-built because he plays football a lot. Mark is patient and helpful. I am outgoing, so I have a lot of friends, but Mark has only two friends. He is hardworking, so his marks are higher than my marks.", "baslik": "Albert's Best Friend"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Mark gets better marks than Albert. He is ......... .", "cevap": "hardworking", "kabul": [], "aciklama": "Metinde \"marks\" sözcüğünü ara: \"He is hardworking, so his marks are higher than my marks.\" Mark'ın notlarının yüksek olma nedeni hardworking."}, {"soru": "Mark's hair is not straight. It is ......... .", "cevap": "wavy", "kabul": [], "aciklama": "Mark'ın saçı için metinde \"short, wavy, dark hair\" yazıyor. straight (düz) olmayan saç wavy (dalgalı)."}, {"soru": "Albert has a lot of friends because he is ......... .", "cevap": "outgoing", "kabul": [], "aciklama": "Metinde \"I am outgoing, so I have a lot of friends\" yazıyor. Albert'ın çok arkadaşı olmasının nedeni outgoing (dışa dönük) olması."}, {"soru": "Mark plays football a lot, so he is ......... .", "cevap": "well-built", "kabul": [], "aciklama": "Metinde \"He is well-built because he plays football a lot\" yazıyor. well-built = iri yapılı, güçlü yapılı."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; küçük yazım hatası (tek harf) kabul edilir, yanlış kelime puan almaz. Çözüm yolu: önce cümlenin anahtar sözcüğünü (kişi adı, marks, hair...) metinde ara; bulduğun cümlede boşluğa uyan kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["albert's:SARTLI", "mark's:SARTLI"]}}, {"id": "HZ-7-s1d3-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "kelimeyle cümle kurma", "yonerge": "Write a sentence with each word.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "(curly)", "cevap": "My sister has curly hair.", "kabul": ["He has short, curly hair."], "aciklama": "curly = kıvırcık; saç tarif eden bir cümlede kullanılır (curly hair)."}, {"soru": "(heavier)", "cevap": "My father is heavier than me.", "kabul": ["Nina is heavier than Mandy."], "aciklama": "heavier, heavy sıfatının karşılaştırma biçimidir; iki kişiyi karşılaştırır ve cümlede than gerekir."}, {"soru": "(polite)", "cevap": "My best friend is polite.", "kabul": ["She is a polite girl."], "aciklama": "polite = kibar; bir kişinin kişiliğini anlatan bir cümlede kullanılır."}, {"soru": "(punctual)", "cevap": "I am punctual.", "kabul": ["My brother is not punctual."], "aciklama": "punctual = zamanında gelen; bir kişinin kişiliğini anlatan bir cümlede kullanılır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kelime anlamına uygun kullanılmış, anlaşılır bir cümle tam puan; yazım hatası kırılmaz; kelime yanlış kullanılmışsa ya da cümle anlamsızsa puan yok. Anahtardakiler örnektir. Çözüm yolu: kelimenin anlamını düşün, sonra bir kişi hakkında kısa bir cümle kur (My father is heavier than me.).", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-7-s1d3-03", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "paragraf cümlelerini sıralama", "yonerge": "Read the sentences. Make the correct paragraph. Write A, B, D or E in the chart.", "uyaran": [{"tur": "metin", "metin": "A) After the match, she drinks water and eats some fruit.\nB) In the evening, she reads a book at home.\nC) First, Mandy goes to the tennis court.\nD) After that, she runs in the park for one hour.\nE) Then, she plays a match with her friend.", "baslik": "Mandy's Day"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5"], "satirlar": [[{"ornek": "C"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "\"Then\" ilk olaydan sonrasını anlatır: Mandy kortta gittikten sonra arkadaşıyla maç yapar."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "\"After the match\" maçtan sonra demektir; bu yüzden maç cümlesinden hemen sonra gelir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "\"After that\" bir önceki olaydan (su içme, meyve yeme) sonra olanı anlatır: parkta bir saat koşar."}, {"soru": null, "cevap": "B", "kabul": [], "aciklama": "\"In the evening\" günün sonudur; en son olay evde kitap okumaktır."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan. Çözüm yolu: First, Then, After the match, After that, In the evening gibi sıra sözcüklerini ara; olayları mantıklı akışa göre diz ve ilk kutudaki örnekten başla.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["book:KOK", "mandy's:SARTLI", "reads:SARTLI"]}}, {"id": "HZ-7-s1d3-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.W1", "zorluk": "orta", "soru_tipi": "notlardan sıralı yazma", "yonerge": "Look at James's notes. Write sentences about James.", "uyaran": [{"tur": "tablo", "basliklar": ["Time", "Activity"], "satirlar": [["7:00", "wake up"], ["8:00", "eat breakfast"], ["9:00", "go to the gym"], ["12:00", "eat lunch with his parents"], ["3:00", "watch a match on TV"]], "baslik": "James's Sunday"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Then, ", "cevap": "Then, James eats breakfast at 8:00.", "kabul": ["Then, he eats breakfast at 8:00."], "aciklama": "Tabloda 8:00 satırı \"eat breakfast\". 3. tekil kişi olduğu için fiil -s alır: eats."}, {"soru": "After that, ", "cevap": "After that, James goes to the gym at 9:00.", "kabul": ["After that, he goes to the gym at 9:00."], "aciklama": "Tabloda 9:00 satırı \"go to the gym\". 3. tekil kişi olduğu için go fiili goes olur."}, {"soru": "At 12:00, ", "cevap": "At 12:00, James eats lunch with his parents.", "kabul": ["At 12:00, he eats lunch with his parents."], "aciklama": "Tabloda 12:00 satırı \"eat lunch with his parents\". Fiil 3. tekilde eats olur."}, {"soru": "In the afternoon, ", "cevap": "In the afternoon, James watches a match on TV at 3:00.", "kabul": ["In the afternoon, he watches a match on TV."], "aciklama": "Tabloda 3:00 satırı \"watch a match on TV\". Fiil 3. tekilde watches olur."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Saat ve etkinlik tabloya uygun, cümle doğru kurulmuşsa (3. tekil -s) tam puan; bilgi doğru ama fiil biçimi ya da yazım hatalıysa yarım puan; bilgi yanlışsa puan yok. Çözüm yolu: önce tabloda saate bak, sonra örnekteki gibi sıra sözcüğü + James + eylem + saat sırasıyla yaz.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["afternoon:KOK", "james's:SARTLI", "notes:SARTLI", "watches:SARTLI"]}, "ornek": "First, James wakes up at 7:00."}]}, {"kod": "7-s2", "sinif": 7, "ders": "ingilizce", "senaryo": 2, "deneme": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 2}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 2}], "sorular": [{"id": "HZ-7-s2-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Read the sentences from a dialogue. Complete the chart with A, B, C, D, E or F to make the correct dialogue.", "uyaran": [{"tur": "metin", "metin": "A) What is he like?\nB) Who is that boy, Sophie?\nC) He is tall and slim. He has short, straight hair.\nD) What does he look like?\nE) He is Jim. He is my best friend.\nF) He is patient and helpful. He is funnier than me!", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "B"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "F"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "Birinci satır \"Who is that boy?\" sorusudur; cevabı onu tanıtan \"He is Jim. He is my best friend.\" cümlesidir. Soru ile cevap yan yana gelir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "Kişi tanıtıldıktan sonra görünüşü sorulur: \"What does he look like?\" (look like = neye benziyor / nasıl görünüyor)."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "\"What does he look like?\" sorusunun cevabı boy, vücut ve saç anlatan \"He is tall and slim. He has short, straight hair.\" cümlesidir."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "Son cevap kişiliği anlatır (\"patient and helpful\"), bu yüzden hemen önceki soru kişiliği soran \"What is he like?\" olmalıdır."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan, yanlış ya da boş harf puan almaz. Çözüm yolu: önce ilk ve son satırı oku; her soruyu, hemen ardından gelen cevapla eşleştir; sonra sırayı baştan sona oku.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-7-s2-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Rachel and Helen are sisters. Rachel is older than Helen, but they are very different. Rachel is tall and slim. She has long, straight, blonde hair and blue eyes. She is polite and hardworking. Helen is shorter than Rachel. She has curly, brown hair and green eyes. Helen is more outgoing than her sister, and she is very funny. She has a lot of friends.", "baslik": "Two Sisters"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Helen's eyes are not blue. They are ......... .", "cevap": "green", "kabul": [], "aciklama": "Metinde Helen için \"curly, brown hair and green eyes\" yazıyor; Rachel'ın gözleri mavi, Helen'ın gözleri yeşil."}, {"soru": "Rachel is not plump. She is ......... .", "cevap": "slim", "kabul": [], "aciklama": "Rachel için \"tall and slim\" yazıyor. plump = tombul; slim (ince) bunun zıttıdır."}, {"soru": "Rachel works hard. She is ......... .", "cevap": "hardworking", "kabul": [], "aciklama": "Metinde Rachel için \"She is polite and hardworking.\" cümlesi var. works hard = hardworking."}, {"soru": "Rachel's hair is not curly. It is ......... .", "cevap": "straight", "kabul": [], "aciklama": "Rachel'ın saçı için \"long, straight, blonde hair\" yazıyor; curly (kıvırcık) olan Helen'ın saçıdır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; küçük yazım hatası (tek harf) kabul edilir, yanlış kelime puan almaz. Çözüm yolu: önce metni oku; her cümlenin ipucunu (saç, göz, yapı, kişilik) metinde ara ve cümlenin anlamına uyan kelimeyi bul.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["helen's:SARTLI", "rachel's:SARTLI", "sisters:SARTLI", "works:SARTLI"]}}, {"id": "HZ-7-s2-03", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "cümle başlangıçlarını tamamlama", "yonerge": "Complete the sentences about you and your family.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "I am younger than ", "cevap": "my brother.", "kabul": ["my sister.", "my father."], "aciklama": "Karşılaştırmada younger than + kişi kullanılır. \"I am younger than my brother.\" gibi mantıklı herhangi bir kişi yazılabilir."}, {"soru": "My best friend is more ", "cevap": "outgoing than me.", "kabul": ["hardworking than me.", "intelligent than me."], "aciklama": "more + uzun sıfat + than yapısı gerekir (more outgoing than)."}, {"soru": "My mother is shorter than ", "cevap": "my father.", "kabul": ["me.", "my sister."], "aciklama": "Kısa sıfat + er + than: shorter than. Sonra bir kişi yazılır (my father, me...)."}, {"soru": "My best friend has curly hair, but ", "cevap": "I have straight hair.", "kabul": ["my brother has straight hair.", "I have short hair."], "aciklama": "but ile iki kişiyi (ya da kendini) karşılaştıran bir cümle yazılır: curly hair <-> straight hair gibi bir zıtlık verilir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: cümle başlangıcına dilbilgisi olarak uyan ve anlamlı her cevap tam puan alır (karşılaştırmada -er / more ... than doğru kullanılmalı); anlamsız ya da başlangıca uymayan cevap puan almaz. Çözüm yolu: önce örneği oku; sonra cümlenin başını ve sonunu yüksek sesle birleştirerek anlamlı olup olmadığına bak.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "My friend is funnier than my brother."}, {"id": "HZ-7-s2-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the text. Answer the questions.", "uyaran": [{"tur": "metin", "metin": "Zeynep is a talented tennis player. She trains at the tennis court three times a week. She plays with her coach, Mr Robins, on Sundays. Zeynep eats fruit, vegetables and meat, and she never eats junk food. She doesn't like running, but she likes swimming. Last year, she won a gold medal in a national championship.", "baslik": "Zeynep's Sport"}], "cevap_bicimi": "satir", "gorsel": {"dosya": "HZ-7-s2-04.jpg", "yerlesim": "yan"}, "alt_sorular": [{"soru": "Does Zeynep train three times a week?", "cevap": "Yes, she does.", "kabul": ["Yes.", "Yes, she trains three times a week."], "aciklama": "Metindeki \"She trains at the tennis court three times a week.\" cümlesi soruyla uyuşur; cevap Yes. \"Does\" ile sorulan soruya \"Yes, she does.\" denir."}, {"soru": "Does Zeynep like swimming?", "cevap": "Yes, she does.", "kabul": ["Yes.", "Yes, she likes swimming."], "aciklama": "Metinde \"She doesn't like running, but she likes swimming.\" cümlesi var; koşmayı sevmez ama yüzmeyi sever. Cevap Yes."}, {"soru": "Is Zeynep a swimmer?", "cevap": "No, she is not. She is a tennis player.", "kabul": ["No. She is a tennis player.", "No, she isn't. She is a tennis player."], "aciklama": "Metin \"Zeynep is a talented tennis player.\" diyor; Zeynep tenis oyuncusudur. Yes/No sorusu \"Is\" ile başlar, kısa cevap \"No, she is not.\" olur."}, {"soru": "Does Zeynep eat junk food?", "cevap": "No, she does not. She never eats junk food.", "kabul": ["No. She never eats junk food.", "No, she doesn't."], "aciklama": "Metinde \"she never eats junk food\" yazıyor; never = hiçbir zaman, yani cevap No."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Yes/No doğru ve (No ise) düzeltme metne uygunsa tam puan; yalnız doğru Yes ya da No yazılmışsa yarım puan. Yazım ve dilbilgisi hatası puan kırdırmaz. Çözüm yolu: önce soruyu oku; cevabı metinde ara; bilgi doğruysa Yes, değilse No yaz ve No ise metindeki doğru bilgiyi ikinci cümlede ver.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["zeynep's:SARTLI"]}, "ornek": "Does Zeynep play with her friends on Sundays? → No, she does not. She plays with her coach."}, {"id": "HZ-7-s2-05", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "paragraf cümlelerini sıralama", "yonerge": "Read the sentences. Make the correct paragraph. Write A, B, D or E in the chart.", "uyaran": [{"tur": "metin", "metin": "A) In the evening, he rests at home and watches TV.\nB) After that, they train for two hours.\nC) First, Sam wakes up early and eats a big breakfast.\nD) After training, Sam takes a shower and eats lunch.\nE) Then, he goes to the football field with his team.", "baslik": "Sam's Football Day"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5"], "satirlar": [[{"ornek": "C"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "İlk cümleden sonra \"Then\" gelir: Sam kahvaltı yaptıktan sonra takımıyla sahaya gider. \"Then\" bir olaydan sonraki olayı anlatır."}, {"soru": null, "cevap": "B", "kabul": [], "aciklama": "\"After that\" bir önceki olaydan (sahaya gitme) sonra olanı anlatır: they train for two hours (antrenman yaparlar)."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "\"After training\" antrenmandan sonra demektir; bu yüzden antrenman cümlesinden hemen sonra gelir."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "\"In the evening\" günün sonudur; en son olay evde dinlenmek ve TV izlemektir."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan. Çözüm yolu: First, Then, After that, After training, In the evening gibi sıra sözcüklerini ara; olayları günün akışına göre diz ve ilk kutudaki örnekten başla.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["rests:SARTLI", "sam's:SARTLI", "takes:SARTLI", "watches:SARTLI"]}}]}, {"kod": "7-s2d2", "sinif": 7, "ders": "ingilizce", "senaryo": 2, "deneme": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 2}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 2}], "sorular": [{"id": "HZ-7-s2d2-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "zamirin gösterdiği", "yonerge": "Read the text. Who or what are these words in the text? Write.", "uyaran": [{"tur": "metin", "metin": "Hello, I'm Sheila. Emma and Henry are my friends. **They** are sister and brother. **She** is short and slim with straight, blonde hair. Henry is older than her. **He** is tall and well-built, and he has a lot of friends because he is outgoing. Their father is a scientist. I like **him** because he is patient and helpful.", "baslik": "Sheila's Friends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "She", "cevap": "Emma", "kabul": [], "aciklama": "Sheila kendisini \"I\" ile anlatıyor. Emma ve Henry tanıtıldıktan sonra kısa, ince, düz sarı saçlı olan kız Emma'dır; \"She\" kız için kullanılır."}, {"soru": "He", "cevap": "Henry", "kabul": [], "aciklama": "\"Henry is older than her. He is tall and well-built\" cümlelerinde \"He\" hemen önceki cümledeki erkek olan Henry'yi gösterir."}, {"soru": "him", "cevap": "Emma and Henry's father", "kabul": ["their father", "the father", "father"], "aciklama": "Önceki cümlede \"Their father is a scientist\" yazıyor. Sheila'nın sevdiği, sabırlı ve yardımsever kişi Emma ile Henry'nin babasıdır."}, {"soru": "They", "cevap": "Emma and Henry", "kabul": ["Henry and Emma"], "aciklama": "Önceki cümlede \"Emma and Henry are my friends\" yazıyor. \"They are sister and brother\" cümlesinde \"They\" iki kişiyi, Emma ve Henry'yi gösterir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru kişi ya da şey tam puan; \"Emma and Henry\" gibi iki kişi gereken yerde yalnız biri yazılmışsa puan yok. İsimde küçük yazım hatası kabul edilir. Çözüm: önce kalın sözcüğün bulunduğu cümleyi oku, sonra bir önceki cümlede bu sözcüğün yerine geçebilecek kişiyi ya da şeyi ara (He/She = kişi, They = iki kişi, it = bir şey).", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["henry's:SARTLI", "sheila's:SARTLI"]}}, {"id": "HZ-7-s2d2-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Selma and Anne are classmates. Selma is fifteen years old. Anne is younger than Selma, but she is funnier. Selma is more hardworking than Anne, so her marks are better. Anne has curly, black hair and brown eyes. She is thoughtful. She always gives gifts to her friends.", "baslik": "Selma and Anne"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Anne is older than Selma.", "cevap": "Anne is younger than Selma.", "kabul": ["Selma is older than Anne.", "Anne is younger."], "aciklama": "Metindeki \"Anne is younger than Selma\" cümlesi. Selma 15 yaşında ve Anne'den büyüktür: older / younger zıt anlamlıdır."}, {"soru": "Anne is more hardworking than Selma.", "cevap": "Selma is more hardworking than Anne.", "kabul": ["Selma is more hardworking."], "aciklama": "Metinde \"Selma is more hardworking than Anne\" yazıyor. Karşılaştırmada more + uzun sıfat + than kullanılır."}, {"soru": "Selma is funnier than Anne.", "cevap": "Anne is funnier than Selma.", "kabul": ["Anne is funnier."], "aciklama": "Metindeki \"Anne is younger than Selma, but she is funnier\" cümlesinde \"she\" Anne'dir. Daha komik olan Anne'dir."}, {"soru": "Anne has straight, blonde hair.", "cevap": "Anne has curly, black hair.", "kabul": ["She has curly, black hair.", "Anne has curly hair."], "aciklama": "Metinde \"Anne has curly, black hair and brown eyes\" yazıyor. Saç tarifi (curly = kıvırcık, black = siyah) metinden alınır."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Cümle metne uygun düzeltilmişse tam puan; yazım ve küçük dilbilgisi hatası puan kırdırmaz; cümle yanlış kalmışsa ya da yanlış kişi/bilgi yazılmışsa puan yok. Çözüm: önce metni oku, sonra her cümleyi metindeki bilgiyle karşılaştır ve yanlış olan kısmı metne göre değiştir.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["classmates:SARTLI", "gives:SARTLI"]}}, {"id": "HZ-7-s2d2-03", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "hata düzeltme", "yonerge": "One word in each sentence is not correct. Write the correct sentence.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "My sister is more shorter than me.", "cevap": "My sister is shorter than me.", "kabul": [], "aciklama": "Kısa sıfatlarda -er kullanılır (shorter than). \"more\" ile -er birlikte yazılmaz; \"more\" kelimesi silinir."}, {"soru": "Peter have a moustache.", "cevap": "Peter has a moustache.", "kabul": [], "aciklama": "Özne Peter tek kişi (he) olduğu için have değil has kullanılır."}, {"soru": "Frank and Alex is best friends.", "cevap": "Frank and Alex are best friends.", "kabul": [], "aciklama": "Özne \"Frank and Alex\" iki kişidir (they); bu yüzden is değil are kullanılır."}, {"soru": "What do your best friend look like?", "cevap": "What does your best friend look like?", "kabul": [], "aciklama": "\"your best friend\" tek kişidir (he/she); soru yardımcı fiili does olmalıdır."}, {"soru": "Is Mandy slimmer then Nina?", "cevap": "Is Mandy slimmer than Nina?", "kabul": [], "aciklama": "Karşılaştırmada iki kişiyi bağlayan kelime than yazılır; then başka bir kelimedir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Cümle tamamen doğru yazılmışsa tam puan; hatalı kelime düzeltilmiş ama başka bir yazım hatası yapılmışsa yarım puan; hata düzeltilmemişse puan yok. Çözüm: cümleyi kelime kelime oku; fiilin özneye uyup uymadığına ve karşılaştırma yapısına (-er than / more ... than) bak, yanlış kelimeyi değiştir.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "Nina are tall. → Nina is tall."}, {"id": "HZ-7-s2d2-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the text. Who says these sentences? Write the names.", "uyaran": [{"tur": "metin", "metin": "Doris, Larry, Terry and Roger are friends. Doris is a cyclist. She rides her bike in the park every morning. Larry plays tennis on Sundays, and he always wins his matches. Terry goes hiking with his parents at weekends. He never eats junk food, but he eats a lot of fruit. Roger loves weightlifting. He is very strong.", "baslik": "Four Friends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I play on Sundays.\"", "cevap": "Larry", "kabul": [], "aciklama": "\"Larry plays tennis on Sundays\" cümlesi. Pazar günleri oynayan tek kişi Larry'dir."}, {"soru": "\"I like weightlifting.\"", "cevap": "Roger", "kabul": [], "aciklama": "Metinde \"Roger loves weightlifting\" yazıyor. love = like (çok sevmek); ağırlık kaldırmayı seven tek kişi Roger."}, {"soru": "\"I ride my bike every morning.\"", "cevap": "Doris", "kabul": [], "aciklama": "Metinde bisiklete binen tek kişi Doris: \"Doris is a cyclist. She rides her bike in the park every morning.\""}, {"soru": "\"I do not eat junk food.\"", "cevap": "Terry", "kabul": [], "aciklama": "\"He never eats junk food\" cümlesindeki \"He\" Terry'dir. never = hiçbir zaman, \"I do not eat\" ile aynı anlama gelir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce metni oku, sonra cümledeki bilgiyi metinde ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["loves:SARTLI", "matches:SARTLI", "rides:SARTLI", "says:SARTLI", "wins:SARTLI"]}}, {"id": "HZ-7-s2d2-05", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Read the sentences from a dialogue. Complete the chart with A, B, C, D, E or F to make the correct dialogue.", "uyaran": [{"tur": "metin", "metin": "A) Is tennis your favourite sport?\nB) Yes, I do. I play tennis.\nC) I play three times a week.\nD) Hello, Raymond. Do you play a sport?\nE) How often do you play tennis?\nF) Yes, it is. I train hard every day.", "baslik": "The Interview"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "D"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "F"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "B", "kabul": [], "aciklama": "İlk soru \"Do you play a sport?\" sorusudur. Cevap \"Yes, I do.\" ile başlar ve hangi sporu oynadığını söyler: \"I play tennis.\""}, {"soru": null, "cevap": "E", "kabul": [], "aciklama": "Tenis söylendikten sonra sıklık sorulur: \"How often do you play tennis?\" (how often = ne sıklıkla)."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "\"How often\" sorusunun cevabı sıklık bildiren \"three times a week\" ifadesidir."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "Son cevap \"Yes, it is.\" olduğu için hemen önceki cümle \"Is ... ?\" ile başlayan soru olmalıdır: \"Is tennis your favourite sport?\""}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan, yanlış ya da boş harf puan almaz. Çözüm yolu: önce ilk ve son satırı oku; her soruyu, hemen ardından gelen cevapla eşleştir; sonra sırayı baştan sona oku.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}]}, {"kod": "7-s2d3", "sinif": 7, "ders": "ingilizce", "senaryo": 2, "deneme": 3, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E7.1.R1", "tema": "Appearance and Personality", "metin": "Students will be able to understand a simple text about appearances, personalities, and comparisons including explanations and reasons.", "adet": 2}, {"kod": "E7.1.W1", "tema": "Appearance and Personality", "metin": "Students will be able to write simple pieces to compare people.", "adet": 1}, {"kod": "E7.2.R1", "tema": "Sports", "metin": "Students will be able to understand short and simple texts on sports.", "adet": 2}], "sorular": [{"id": "HZ-7-s2d3-01", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the text. Who says these sentences? Write the names.", "uyaran": [{"tur": "metin", "metin": "Jane, Wilson, Rosie and Burcu are classmates. Jane is very punctual. She is never late. Wilson is relaxed and easy-going. He has no problems with his friends. Rosie is generous. She buys gifts for her friends. Burcu works hard, so her marks are always higher than Wilson's marks.", "baslik": "Classmates"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I never have problems with my friends.\"", "cevap": "Wilson", "kabul": [], "aciklama": "\"He has no problems with his friends\" cümlesindeki \"He\" Wilson'dır. no problems = hiç sorun yok."}, {"soru": "\"My marks are better than Wilson's marks.\"", "cevap": "Burcu", "kabul": [], "aciklama": "Metinde \"her marks are always higher than Wilson's marks\" yazıyor; \"her\" Burcu'dur. higher = better (daha yüksek / daha iyi)."}, {"soru": "\"I am never late.\"", "cevap": "Jane", "kabul": [], "aciklama": "Metinde \"Jane is very punctual. She is never late for anything\" yazıyor. Geç kalmayan tek kişi Jane."}, {"soru": "\"I give gifts to my friends.\"", "cevap": "Rosie", "kabul": [], "aciklama": "\"Rosie is generous. She buys gifts for her friends.\" Arkadaşlarına hediye alan tek kişi Rosie."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce metni oku, sonra cümledeki bilgiyi metinde ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["classmates:SARTLI", "says:SARTLI", "wilson's:SARTLI", "works:SARTLI"]}}, {"id": "HZ-7-s2d3-02", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.R1", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the text. Answer the questions.", "uyaran": [{"tur": "metin", "metin": "Peter is my classmate. He is short and plump, and he has curly, dark hair and green eyes. He is not very outgoing, but he is friendly and helpful. He is a good friend. He always shares his books with me, and he never tells lies. His sister Beth is older than him. She is taller, and she is more hardworking.", "baslik": "My Classmate Peter"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Is Peter tall?", "cevap": "No, he is not. He is short.", "kabul": ["No. He is short.", "No, he isn't. He is short."], "aciklama": "Metinde \"He is short and plump\" yazıyor. Peter uzun değil, kısa boyludur; Yes/No sorusu \"Is\" ile sorulduğu için kısa cevap \"No, he is not.\" olur."}, {"soru": "Does Peter tell lies?", "cevap": "No, he does not. He never tells lies.", "kabul": ["No. He never tells lies.", "No, he doesn't."], "aciklama": "\"He never tells lies\" cümlesi var; never = hiçbir zaman. \"Does\" ile sorulan soruya \"No, he does not.\" denir."}, {"soru": "Is Beth taller than Peter?", "cevap": "Yes, she is.", "kabul": ["Yes.", "Yes, she is taller than Peter."], "aciklama": "Metinde Beth için \"She is taller\" yazıyor ve cümleler Peter ile karşılaştırma yapıyor (\"older than him\"). Cevap Yes."}, {"soru": "Is Peter friendly?", "cevap": "Yes, he is.", "kabul": ["Yes.", "Yes, he is friendly."], "aciklama": "Metindeki \"he is friendly and helpful\" cümlesi soruyla uyuşur; cevap Yes."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Yes/No doğru ve (No ise) düzeltme metne uygunsa tam puan; yalnız doğru Yes ya da No yazılmışsa yarım puan. Yazım ve dilbilgisi hatası puan kırdırmaz. Çözüm yolu: önce soruyu oku; cevabı metinde ara; bilgi doğruysa Yes, değilse No yaz ve No ise metindeki doğru bilgiyi ikinci cümlede ver.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["shares:SARTLI"]}, "ornek": "Does Peter have blue eyes? → No, he does not. He has green eyes."}, {"id": "HZ-7-s2d3-03", "sinif": 7, "tema": 1, "tema_adi": "Appearance and Personality", "kazanim": "E7.1.W1", "zorluk": "orta", "soru_tipi": "eksik diyalog", "yonerge": "Read Jane's questions. Write your answers. Use your ideas.", "uyaran": [{"tur": "diyalog", "konusmalar": [{"kisi": "Jane", "soz": "Who is your best friend?"}, {"kisi": "You", "soz": "", "bosluk": 1}, {"kisi": "Jane", "soz": "What does your best friend look like?"}, {"kisi": "You", "soz": "", "bosluk": 2}, {"kisi": "Jane", "soz": "What is your best friend like?"}, {"kisi": "You", "soz": "", "bosluk": 3}, {"kisi": "Jane", "soz": "Is your best friend funnier than you?"}, {"kisi": "You", "soz": "", "bosluk": 4}]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "My best friend is Merve.", "kabul": ["My best friend is Jack.", "Burcu is my best friend."], "aciklama": "\"Who\" sorusuna bir isimle cevap verilir: \"My best friend is ...\" Kendi arkadaşının adını yaz."}, {"soru": null, "cevap": "He is tall and slim. He has short, straight hair.", "kabul": ["She has long, wavy hair and brown eyes."], "aciklama": "\"What does ... look like?\" görünüşü sorar: boy, vücut, saç ve göz tarifi yaz (tall, slim, curly hair, brown eyes...)."}, {"soru": null, "cevap": "He is friendly and helpful.", "kabul": ["She is outgoing and funny.", "He is hardworking."], "aciklama": "\"What is ... like?\" kişiliği sorar: sıfat yaz (friendly, patient, generous, funny...)."}, {"soru": null, "cevap": "Yes, he is. He is funnier than me.", "kabul": ["No, she is not. I am funnier than her.", "Yes, she is."], "aciklama": "\"Is ... funnier than you?\" Yes/No sorusudur: Yes ya da No yaz, istersen karşılaştırma cümlesiyle devam et (funnier than)."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Anahtardaki cevaplar yalnızca örnek: soruya uygun, dilbilgisi olarak doğru ve anlamlı her cevap tam puan alır; soruyla ilgisiz ya da anlamsız cevap puan almaz. Çözüm yolu: önce soruyu oku; sonra soruya uyan bir cümle ya da kısa cevap yaz (look like = görünüş, be like = kişilik).", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["answers:SARTLI"]}}, {"id": "HZ-7-s2d3-04", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hello, I'm Rick. I love sports and I am fit. I go jogging in the park every morning. After that, I eat fruit and vegetables for breakfast. I never eat junk food because it is not healthy. In the afternoon, I play tennis with my coach, Mr Higgings. On weekends, I go hiking with my parents.", "baslik": "Rick's Sports"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Mr Higgings is Rick's ......... .", "cevap": "coach", "kabul": [], "aciklama": "Metinde \"my coach, Mr Higgings\" yazıyor. Mr Higgings'i metinde ara; adından sonra gelen kelime coach (antrenör)."}, {"soru": "Rick does not eat ......... food.", "cevap": "junk", "kabul": [], "aciklama": "Metindeki \"I never eat junk food because it is not healthy\" cümlesi. Rick'in yemediği yiyecek junk food (abur cubur)."}, {"soru": "Rick's morning exercise is ......... in the park.", "cevap": "jogging", "kabul": [], "aciklama": "\"I go jogging in the park every morning\" cümlesinde sabah sporu jogging (hafif tempolu koşu)."}, {"soru": "Rick and his coach play ......... in the afternoon.", "cevap": "tennis", "kabul": [], "aciklama": "\"In the afternoon, I play tennis with my coach\" cümlesinde öğleden sonra oynanan spor tennis."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; küçük yazım hatası (tek harf) kabul edilir, yanlış kelime puan almaz. Çözüm yolu: önce cümlenin anahtar sözcüğünü (kişi adı, yer, saat) metinde ara; bulduğun cümlede boşluğa uyan kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["afternoon:KOK", "rick's:SARTLI"]}}, {"id": "HZ-7-s2d3-05", "sinif": 7, "tema": 2, "tema_adi": "Sports", "kazanim": "E7.2.R1", "zorluk": "orta", "soru_tipi": "zamirin gösterdiği", "yonerge": "Read the text. Who or what are these words in the text? Write.", "uyaran": [{"tur": "metin", "metin": "Naim and Sheila are brother and sister. They love swimming. **He** goes to the pool on Mondays, and **she** goes on Fridays. The pool is near their house, and **it** is very big. Mr Robins is their coach. Naim and Sheila listen to **him** a lot.", "baslik": "Naim and Sheila"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "she", "cevap": "Sheila", "kabul": [], "aciklama": "\"He goes on Mondays, and she goes on Fridays\" cümlesinde \"he\" Naim olduğuna göre \"she\" kız olan Sheila'dır."}, {"soru": "him", "cevap": "Mr Robins", "kabul": ["the coach", "their coach", "Robins"], "aciklama": "\"Mr Robins is their coach. Naim and Sheila listen to him\" cümlesinde \"him\" erkek olan koçu, yani Mr Robins'i gösterir."}, {"soru": "He", "cevap": "Naim", "kabul": [], "aciklama": "\"Naim and Sheila ...\" cümlesinden sonra \"He goes to the pool on Mondays\" geliyor; erkek olan Naim'dir."}, {"soru": "it", "cevap": "the pool", "kabul": ["pool"], "aciklama": "\"The pool is near their house, and it is very big\" cümlesinde \"it\" önceki isim olan havuzu (pool) gösterir."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Doğru kişi ya da şey tam puan; iki kişi gereken yerde yalnız biri yazılmışsa puan yok. İsimde küçük yazım hatası kabul edilir. Çözüm: önce kalın sözcüğün bulunduğu cümleyi oku, sonra bir önceki cümlede bu sözcüğün yerine geçebilecek kişiyi ya da şeyi ara (he/she = kişi, it = bir şey).", "kelime_kontrol": {"izinli_havuz": "7. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["fridays:SARTLI", "mondays:SARTLI"]}}]}, {"kod": "8-s4", "sinif": 8, "ders": "ingilizce", "senaryo": 4, "deneme": 1, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E8.1.R1", "tema": "Friendship", "metin": "Students will be able to understand short and simple texts about friendship.", "adet": 1}, {"kod": "E8.1.R2", "tema": "Friendship", "metin": "Students will be able to understand short and simple invitation letters, cards and e-mails.", "adet": 2}, {"kod": "E8.2.R1", "tema": "Teen Life", "metin": "Students will be able to understand short and simple texts about regular activities of teenagers.", "adet": 2}, {"kod": "E8.2.W1", "tema": "Teen Life", "metin": "Students will be able to write a short and simple paragraph about regular activities of teenagers.", "adet": 1}], "sorular": [{"id": "HZ-8-s4-01", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R1", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Hi, I'm Mert. Rick is my best friend. We are neighbours and we go to the same school. Rick is honest and punctual. He is always on time, but I am always in a hurry. On Sundays, we play tennis together. Then, we eat pizza at my house. I trust Rick because he never tells lies.", "baslik": "My Best Friend"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Mert and Rick go to different schools.", "cevap": "Mert and Rick go to the same school.", "kabul": ["They go to the same school."], "aciklama": "Metinde \"we go to the same school\" yazıyor. Yanlış cümlede \"different\" kullanılmış; doğrusu \"the same\"."}, {"soru": "Rick is always in a hurry.", "cevap": "Mert is always in a hurry.", "kabul": ["Rick is always on time."], "aciklama": "Metinde \"He is always on time, but I am always in a hurry\" yazıyor. Acelesi olan kişi metni anlatan Mert; \"He\" Rick'tir."}, {"soru": "Mert and Rick play tennis on Saturdays.", "cevap": "Mert and Rick play tennis on Sundays.", "kabul": ["They play tennis on Sundays."], "aciklama": "Metindeki \"On Sundays, we play tennis together\" cümlesi. Doğru gün Sundays."}, {"soru": "They eat pizza at Rick's house.", "cevap": "They eat pizza at Mert's house.", "kabul": ["They eat pizza at Mert's.", "Mert and Rick eat pizza at Mert's house."], "aciklama": "Metinde \"we eat pizza at my house\" yazıyor; \"my\" metni anlatan Mert demektir. Rick'e ait sanmak."}], "adlar": ["Mert", "Rick", "Rick's", "Mert's"], "puanlama": "Alt sorular eşit puanlı. Cümle metne uygun düzeltilmişse tam puan; yazım ve küçük dilbilgisi hatası puan kırdırmaz; cümle yanlış kalmışsa ya da yanlış kişi/bilgi yazılmışsa puan yok. Çözüm: önce metni oku, sonra her cümleyi metindeki bilgiyle karşılaştır ve yanlış olan kısmı metne göre değiştir.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["saturdays:SARTLI", "schools:SARTLI", "sundays:SARTLI"]}}, {"id": "HZ-8-s4-02", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "davetiye bilgi tablosu", "yonerge": "Read the e-mail. Then complete the invitation.", "uyaran": [{"tur": "metin", "metin": "Hi Jim,\nHow are you? I'm giving a picnic on Sunday for my friends. We will meet at 2 o'clock in front of the museum. We will eat pizza and drink orange juice. Would you like to come? Please, let me know soon.\nOya", "baslik": "E-mail"}, {"tur": "tablo", "basliklar": ["", ""], "satirlar": [["From", {"bosluk": 1}], ["Day", {"bosluk": 2}], ["Time", {"bosluk": 3}], ["Meet", {"bosluk": 4}], ["Drink", {"bosluk": 5}]], "baslik": "PICNIC"}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Oya", "kabul": [], "aciklama": "E-postanın son satırında gönderenin adı yazıyor: \"Oya\"."}, {"soru": null, "cevap": "Sunday", "kabul": ["on Sunday"], "aciklama": "\"I'm giving a picnic on Sunday\" cümlesi. Gün bilgisi \"on\" sözcüğünden sonra gelir."}, {"soru": null, "cevap": "2 o'clock", "kabul": ["at 2 o'clock"], "aciklama": "\"We will meet at 2 o'clock\" cümlesi. Saat bilgisi \"at\" sözcüğünden sonra gelir."}, {"soru": null, "cevap": "in front of the museum", "kabul": ["the museum", "at the museum"], "aciklama": "\"We will meet ... in front of the museum\" cümlesi. Buluşma yeri \"in front of the museum\"."}, {"soru": null, "cevap": "orange juice", "kabul": ["juice"], "aciklama": "\"We will eat pizza and drink orange juice.\" Yiyecek pizza, içecek orange juice; \"Drink\" satırına içecek yazılır."}], "adlar": ["Oya", "Jim"], "puanlama": "Kutular eşit puanlı. Bilgi e-postadan doğru aktarılmışsa tam puan; yazım hatası puan kırdırmaz; bilgi yanlışsa ya da boşsa puan yok. Çözüm: önce e-postayı oku, sonra her kutunun başlığına uyan bilgiyi (kim, hangi gün, saat, buluşma yeri, içecek) metinde ara.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["e-mail:KOK"]}}, {"id": "HZ-8-s4-03", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the invitation letter. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hi Tina,\nOur sports club has a tennis match at the stadium next Saturday. Would you like to come and support us? My cousin Robin will come too. Then, we will have a party at the club with cake and juice. Please, reply before Friday.\nTony", "baslik": "Letter"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Tony's club has a ......... match.", "cevap": "tennis", "kabul": [], "aciklama": "Mektubun ilk cümlesinde \"a tennis match\" yazıyor. Maçın türü tenis."}, {"soru": "Tina can watch the game at the ......... .", "cevap": "stadium", "kabul": [], "aciklama": "\"... match at the stadium\" ifadesi. \"game\" ve \"match\" aynı anlamda kullanılmış."}, {"soru": "Robin is Tony's ......... .", "cevap": "cousin", "kabul": [], "aciklama": "\"My cousin Robin will come too\" cümlesi. Mektubu yazan Tony olduğu için \"my cousin\" = Tony'nin kuzeni."}, {"soru": "Tina should answer before ......... .", "cevap": "Friday", "kabul": [], "aciklama": "\"Please, reply before Friday.\" Burada \"reply\" ve \"answer\" aynı anlamda; cevap verilecek gün Friday."}], "adlar": ["Tina", "Tony", "Tony's", "Robin"], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; kelimede küçük yazım hatası kabul edilir; yanlış kelime ya da boş cevap puan kazandırmaz. Çözüm: önce cümleyi oku, sonra cümledeki bilgiyi mektupta ara ve boşluğa oradaki kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}}, {"id": "HZ-8-s4-04", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Put the sentences in the correct order and make a dialogue. Write the letters in the boxes.", "uyaran": [{"tur": "metin", "metin": "A) Yes, I am. I love playing basketball.\nB) Sure, I'd love to.\nC) How often do you play it?\nD) Would you like to join us on Saturday?\nE) Are you keen on sports, Ali?\nF) I usually play it with my friends three days a week.", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "E"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "B"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "A", "kabul": [], "aciklama": "İlk cümle \"Are you keen on sports, Ali?\" sorusu; cevabı \"Yes, I am.\" ile başlayan A cümlesi."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "A cümlesinde basketbol geçiyor. \"it\" basketbolu gösterir; \"How often do you play it?\" soruyu sürdürür."}, {"soru": null, "cevap": "F", "kabul": [], "aciklama": "\"How often\" sorusunun cevabı sıklık bildirir: \"three days a week\". \"it\" yine basketbolu gösterir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "F cümlesinde \"my friends\" geçiyor; \"join us\" bu arkadaşlara katılma daveti. Son cümle B (\"Sure, I'd love to.\") bu davete cevap."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan. Çözüm: önce ilk ve son cümleye bak; sonra soru–cevap çiftlerini bul (\"Are you keen on...?\" → \"Yes, I am.\"; \"it\" ve \"us\" gibi sözcükler önceki cümleyi gösterir).", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["letters:SARTLI"]}}, {"id": "HZ-8-s4-05", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the text. Who says these sentences? Write the names.", "uyaran": [{"tur": "metin", "metin": "Some teenagers talk about their weekends. James is keen on cycling. He goes cycling with his sister on Sundays. Doris is fond of reading. She reads detective books in the evenings. Sam loves chess. He plays it online every Saturday. Kelly enjoys watching films. She often goes to the cinema with her cousin.", "baslik": "Weekends"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I enjoy reading detective stories.\"", "cevap": "Doris", "kabul": [], "aciklama": "\"She reads detective books in the evenings\" cümlesi Doris hakkında. \"stories\" ve \"books\" burada benzer anlamda."}, {"soru": "\"I often visit the cinema with my cousin.\"", "cevap": "Kelly", "kabul": [], "aciklama": "\"She often goes to the cinema with her cousin\" cümlesi Kelly hakkında. Kuzeniyle sinemaya giden tek kişi o."}, {"soru": "\"I like cycling with my sister at the weekend.\"", "cevap": "James", "kabul": [], "aciklama": "\"He goes cycling with his sister on Sundays.\" Kız kardeşiyle bisiklete binen tek kişi James; \"weekend\" Sunday'i kapsar."}, {"soru": "\"I love playing chess on the internet.\"", "cevap": "Sam", "kabul": [], "aciklama": "\"He plays it online every Saturday\" cümlesinde \"it\" satrançtır. \"online\" ile \"on the internet\" aynı anlama gelir."}], "adlar": ["James", "Doris", "Sam", "Kelly"], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce metni oku, sonra cümledeki bilgiyi metinde ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["enjoys:SARTLI", "plays:SARTLI", "reads:SARTLI", "sundays:SARTLI"]}}, {"id": "HZ-8-s4-06", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.W1", "zorluk": "orta", "soru_tipi": "notlardan sıralı yazma", "yonerge": "Read the notes. Doris does these things every Saturday. Write about her. Complete the sentences.", "uyaran": [{"tur": "tablo", "basliklar": ["Time", "Doris"], "satirlar": [["9:00", "play basketball with friends"], ["11:00", "go shopping"], ["3:00", "read detective books"], ["7:00", "watch a film with her sister"]], "baslik": "Doris's Saturdays"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": "sira"}, "alt_sorular": [{"soru": "In the morning, ", "cevap": "In the morning, Doris plays basketball with her friends at 9:00.", "kabul": ["In the morning, she plays basketball with her friends at 9:00.", "In the morning, Doris plays basketball at 9:00."], "aciklama": "Notlardaki ilk satır: 9:00 – play basketball with friends. Saat bilgisi \"at 9:00\" ile eklenir, fiil 3. tekil kişide \"plays\" olur.", "foto": "HZ-8-s4-06_1.jpg"}, {"soru": "Then, ", "cevap": "Then, Doris goes shopping at 11:00.", "kabul": ["Then, she goes shopping at 11:00."], "aciklama": "İkinci satır: 11:00 – go shopping. \"go\" fiili Doris ile \"goes\" olur.", "foto": "HZ-8-s4-06_2.jpg"}, {"soru": "After that, ", "cevap": "After that, Doris reads detective books at 3:00.", "kabul": ["After that, she reads detective books at 3:00."], "aciklama": "Üçüncü satır: 3:00 – read detective books. \"read\" fiili 3. tekil kişide \"reads\" olur.", "foto": "HZ-8-s4-06_3.jpg"}, {"soru": "In the evening, ", "cevap": "In the evening, Doris watches a film with her sister at 7:00.", "kabul": ["In the evening, she watches a film with her sister at 7:00.", "In the evening, Doris watches a film with her sister."], "aciklama": "Son satır: 7:00 – watch a film with her sister. Notlarda \"her sister\" yazıyor; \"watch\" fiili \"watches\" olur.", "foto": "HZ-8-s4-06_4.jpg"}], "adlar": ["Doris", "Kelly"], "puanlama": "Satırlar eşit puanlı. Satır başı verilen sözcükle, notlardaki bilgiyi doğru yazan ve fiili doğru biçimde (3. tekil -s) kullanan cümle tam puan; bilgi doğru ama dil hatalıysa yarım puan; bilgi yanlışsa ya da boşsa puan yok. Çözüm: önce notları oku, sonra her satır başını örnekteki gibi tamamla: saat bilgisini \"at ...\" ile, etkinliği Doris ile 3. tekil kişi biçiminde yaz.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["plays:SARTLI", "reads:SARTLI", "saturdays:SARTLI", "watches:SARTLI"]}, "ornek": "Notes: Kelly, 8:00, go cycling → At 8:00, Kelly goes cycling."}]}, {"kod": "8-s4d2", "sinif": 8, "ders": "ingilizce", "senaryo": 4, "deneme": 2, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E8.1.R1", "tema": "Friendship", "metin": "Students will be able to understand short and simple texts about friendship.", "adet": 1}, {"kod": "E8.1.R2", "tema": "Friendship", "metin": "Students will be able to understand short and simple invitation letters, cards and e-mails.", "adet": 2}, {"kod": "E8.2.R1", "tema": "Teen Life", "metin": "Students will be able to understand short and simple texts about regular activities of teenagers.", "adet": 2}, {"kod": "E8.2.W1", "tema": "Teen Life", "metin": "Students will be able to write a short and simple paragraph about regular activities of teenagers.", "adet": 1}], "sorular": [{"id": "HZ-8-s4d2-01", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R1", "zorluk": "orta", "soru_tipi": "zamirin gösterdiği", "yonerge": "Read the text. Who or what are these words in the text? Write.", "uyaran": [{"tur": "metin", "metin": "Laura's best friend is Mike. **He** is honest and reliable. When Laura needs help, Mike listens to **her** and gives advice. Mike loves swimming. **It** is fun, and Laura likes it too. On Saturdays, **they** go swimming together.", "baslik": "Laura and Mike"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "He", "cevap": "Mike", "kabul": [], "aciklama": "\"Laura's best friend is Mike. He is honest and reliable.\" He, bir önceki cümledeki erkek kişiyi (Mike) gösterir."}, {"soru": "her", "cevap": "Laura", "kabul": [], "aciklama": "\"Mike listens to her\" cümlesinde dinlenen kişi, \"When Laura needs help\" ifadesindeki Laura'dır."}, {"soru": "It", "cevap": "swimming", "kabul": [], "aciklama": "\"Mike loves swimming. It is fun\" cümlelerinde It, bir önceki cümledeki \"swimming\" (yüzme) demektir."}, {"soru": "they", "cevap": "Laura and Mike", "kabul": ["Mike and Laura"], "aciklama": "\"On Saturdays, they go swimming together\" cümlesinde they, metinde anlatılan iki kişidir: Laura ve Mike."}], "adlar": [], "puanlama": "Alt sorular eşit puanlı. Kalın yazılı sözcüğün gösterdiği kişi ya da şey doğru yazılmışsa tam puan; yazım hatası puan kırdırmaz; yanlış kişi/şey ya da boş cevap puan kazandırmaz. Çözüm: önce kalın sözcüğün geçtiği cümleyi oku, sonra bir önceki cümlelere bak ve o sözcüğün yerine geçebilecek kişi ya da şeyi bul.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["laura's:SARTLI", "loves:SARTLI", "saturdays:SARTLI"]}}, {"id": "HZ-8-s4d2-02", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the invitations. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Jane", "metin": "Hi! Our class will visit the museum on Friday. Would you like to join us?", "aciklama": ""}, {"kisi": "Bob", "metin": "Hello! I am planning a birthday party at my house on Sunday. There will be cake and juice. Would you like to come?", "aciklama": ""}, {"kisi": "Kate", "metin": "Hi! My sister and I will go camping at the weekend. Would you like to come with us?", "aciklama": ""}, {"kisi": "Danny", "metin": "Hello! There is a film at the cinema tonight. Would you like to watch it with me?", "aciklama": ""}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I want to eat cake with my friends at home.\"", "cevap": "Bob", "kabul": [], "aciklama": "Bob'un mesajında \"birthday party at my house\" ve \"cake and juice\" yazıyor; evde pasta yenecek tek davet bu."}, {"soru": "\"I will go to the museum with my class.\"", "cevap": "Jane", "kabul": [], "aciklama": "Jane \"Our class will visit the museum\" diyor; \"visit\" ile \"go to\" burada aynı anlamda. Müzeye sınıfıyla gidecek tek kişi o."}, {"soru": "\"I would like to see a film tonight.\"", "cevap": "Danny", "kabul": [], "aciklama": "Danny \"There is a film at the cinema tonight\" yazıyor. Bu gece sinemaya gitmek isteyen tek kişi o."}, {"soru": "\"I will go camping with my sister.\"", "cevap": "Kate", "kabul": [], "aciklama": "Kate \"My sister and I will go camping\" yazıyor. Kız kardeşiyle kampa gidecek tek kişi o."}], "adlar": ["Jane", "Bob", "Kate", "Danny"], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce dört kısa mesajı oku, sonra cümledeki bilgiyi mesajlarda ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["names:SARTLI"]}}, {"id": "HZ-8-s4d2-03", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the e-mail. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hi Ali,\nOn Friday evening, we will have a Ramadan feast at my house. My grandparents will come, and we will eat a lot of food. Then, we will play games. Would you like to come? Please, reply soon.\nBeth", "baslik": "E-mail"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Beth is inviting Ali to a ......... .", "cevap": "feast", "kabul": ["Ramadan feast"], "aciklama": "\"we will have a Ramadan feast at my house\" cümlesi. Davet edilen etkinlik \"feast\" (ziyafet)."}, {"soru": "Beth's ......... will come to the feast.", "cevap": "grandparents", "kabul": [], "aciklama": "\"My grandparents will come\" cümlesi. Beth'in büyükanne ve büyükbabası gelecek; \"My\" mektubu yazan Beth demektir."}, {"soru": "The guests will ......... games.", "cevap": "play", "kabul": [], "aciklama": "\"Then, we will play games\" cümlesi. Oyunlarla birlikte kullanılan fiil \"play\"."}, {"soru": "The feast is on ......... evening.", "cevap": "Friday", "kabul": [], "aciklama": "\"On Friday evening, we will have a Ramadan feast\" cümlesi. Gün bilgisi \"Friday\"."}], "adlar": ["Ali", "Beth", "Beth's"], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; kelimede küçük yazım hatası kabul edilir; yanlış kelime ya da boş cevap puan kazandırmaz. Çözüm: önce cümleyi oku, sonra cümledeki bilgiyi metinde ara ve boşluğa metindeki kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["e-mail:KOK"]}}, {"id": "HZ-8-s4d2-04", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "yanlış bilgiyi düzeltme", "yonerge": "Read the text. The sentences are not true. Write the correct sentences.", "uyaran": [{"tur": "metin", "metin": "Hi! I'm Buket. I am fond of music. I play the guitar every evening. On Mondays, I go to the gym with my sister. I rarely watch TV, but I often read detective books. On weekends, I seldom go shopping. I usually stay at home and listen to rock music.", "baslik": "About Me"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Buket goes to the gym on Wednesdays.", "cevap": "Buket goes to the gym on Mondays.", "kabul": ["She goes to the gym on Mondays."], "aciklama": "Metindeki \"On Mondays, I go to the gym\" cümlesi. Gün bilgisi Mondays; 3. tekil kişide \"goes\" olur."}, {"soru": "Buket goes shopping every weekend.", "cevap": "Buket seldom goes shopping on weekends.", "kabul": ["She seldom goes shopping.", "Buket seldom goes shopping."], "aciklama": "Metindeki \"On weekends, I seldom go shopping\" cümlesi. \"seldom\" (nadiren) alışverişe çıkmayı anlatır."}, {"soru": "Buket plays the violin every evening.", "cevap": "Buket plays the guitar every evening.", "kabul": ["She plays the guitar every evening."], "aciklama": "Metindeki \"I play the guitar every evening\" cümlesi. Çalınan enstrüman violin değil guitar."}, {"soru": "Buket often watches TV.", "cevap": "Buket rarely watches TV.", "kabul": ["She rarely watches TV."], "aciklama": "Metindeki \"I rarely watch TV\" cümlesi. Sıklık zarfı \"rarely\" (nadiren); \"often\" metindeki kitap okumayı anlatır."}], "adlar": ["Buket"], "puanlama": "Alt sorular eşit puanlı. Cümle metne uygun düzeltilmişse tam puan; yazım ve küçük dilbilgisi hatası puan kırdırmaz; cümle yanlış kalmışsa ya da yanlış bilgi yazılmışsa puan yok. Çözüm: önce metni oku, sonra her cümleyi metindeki bilgiyle karşılaştır ve yanlış olan kısmı metne göre değiştir.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["plays:SARTLI", "stay:KOK", "watches:SARTLI"]}}, {"id": "HZ-8-s4d2-05", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "metinden tek kelimeyle tamamlama", "yonerge": "Read the text. Complete the sentences with one word from the text.", "uyaran": [{"tur": "metin", "metin": "Hi! I'm George. I am a teenager and I am a drummer in a school band. We play folk music at school on Fridays. In my free time, I often listen to jazz, but I can't stand heavy metal. I think it is unbearable. I also enjoy hanging out with my friends.", "baslik": "George's Blog"}], "cevap_bicimi": "bosluklu", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "George plays in a ......... at school.", "cevap": "band", "kabul": ["school band"], "aciklama": "\"I am a drummer in a school band\" cümlesi. Okuldaki müzik grubu \"band\"."}, {"soru": "The band plays ......... music on Fridays.", "cevap": "folk", "kabul": [], "aciklama": "\"We play folk music at school on Fridays\" cümlesi. Müzik türü \"folk\"."}, {"soru": "George often listens to ......... .", "cevap": "jazz", "kabul": [], "aciklama": "\"I often listen to jazz\" cümlesi. Sık dinlediği müzik \"jazz\"."}, {"soru": "George thinks heavy metal is ......... .", "cevap": "unbearable", "kabul": [], "aciklama": "\"I think it is unbearable\" cümlesinde \"it\", heavy metal'i gösterir. Sıfat \"unbearable\"."}], "adlar": ["George"], "puanlama": "Alt sorular eşit puanlı. Doğru kelime tam puan; kelimede küçük yazım hatası kabul edilir; yanlış kelime ya da boş cevap puan kazandırmaz. Çözüm: önce cümleyi oku, sonra cümledeki bilgiyi metinde ara ve boşluğa metindeki kelimeyi yaz.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["plays:SARTLI", "teenager:KOK"]}}, {"id": "HZ-8-s4d2-06", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.W1", "zorluk": "orta", "soru_tipi": "eksik diyalog", "yonerge": "Sam wants to know about your free time. Read his questions and write your answers. Use your own ideas.", "uyaran": [{"tur": "diyalog", "konusmalar": [{"kisi": "Sam", "soz": "Do you like dancing?"}, {"kisi": "You", "soz": "Yes, I do. I love dancing."}, {"kisi": "Sam", "soz": "Are you keen on sports?"}, {"kisi": "You", "soz": "", "bosluk": 1}, {"kisi": "Sam", "soz": "What do you usually do in the evenings?"}, {"kisi": "You", "soz": "", "bosluk": 2}, {"kisi": "Sam", "soz": "Which type of music do you prefer?"}, {"kisi": "You", "soz": "", "bosluk": 3}, {"kisi": "Sam", "soz": "How often do you watch TV?"}, {"kisi": "You", "soz": "", "bosluk": 4}]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "Yes, I am. I am keen on basketball.", "kabul": ["No, I'm not. I prefer reading books."], "aciklama": "\"Are you keen on ...?\" sorusuna \"Yes, I am.\" ya da \"No, I'm not.\" ile cevap verilir; ardından kendi tercihini ekle."}, {"soru": null, "cevap": "I usually do my homework.", "kabul": ["I usually watch TV with my family."], "aciklama": "\"What do you usually do ...?\" sorusuna \"I usually + fiil\" ile cevap verilir. \"usually\" sıklık zarfı fiilden önce gelir."}, {"soru": null, "cevap": "I prefer pop music.", "kabul": ["I prefer rock music."], "aciklama": "\"Which type of music do you prefer?\" sorusuna \"I prefer + müzik türü\" ile cevap verilir (pop, rock, jazz, folk...)."}, {"soru": null, "cevap": "I rarely watch TV.", "kabul": ["I watch TV every day."], "aciklama": "\"How often ...?\" sorusu sıklık sorar. \"rarely, sometimes, often, every day\" gibi bir sıklık ifadesi kullanılır."}], "adlar": ["Sam"], "puanlama": "Satırlar eşit puanlı. Öğrenci kendi bilgisini yazar: soruya uygun, anlaşılır cevap tam puan; dil hatası belirgin ya da tek kelimelik cevap yarım puan; soruyla ilgisiz ya da boş cevap puan kazandırmaz. Anahtardaki cümleler yalnızca örnektir. Çözüm: önce Sam'in sorusunu oku, sonra soru kalıbına uygun, kendi bilgini içeren kısa bir cümle yaz.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["wants:SARTLI"]}, "ornek": "Sam: Do you like dancing? → You: Yes, I do. I love dancing."}]}, {"kod": "8-s4d3", "sinif": 8, "ders": "ingilizce", "senaryo": 4, "deneme": 3, "donem": "1. Dönem 1. Ortak Yazılı", "kazanimlar": [{"kod": "E8.1.R1", "tema": "Friendship", "metin": "Students will be able to understand short and simple texts about friendship.", "adet": 1}, {"kod": "E8.1.R2", "tema": "Friendship", "metin": "Students will be able to understand short and simple invitation letters, cards and e-mails.", "adet": 2}, {"kod": "E8.2.R1", "tema": "Teen Life", "metin": "Students will be able to understand short and simple texts about regular activities of teenagers.", "adet": 2}, {"kod": "E8.2.W1", "tema": "Teen Life", "metin": "Students will be able to write a short and simple paragraph about regular activities of teenagers.", "adet": 1}], "sorular": [{"id": "HZ-8-s4d3-01", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R1", "zorluk": "orta", "soru_tipi": "karışık diyalog", "yonerge": "Put the sentences in the correct order and make a dialogue. Write the letters in the boxes.", "uyaran": [{"tur": "metin", "metin": "A) What is she like?\nB) Yes, we do. We spend a lot of time together.\nC) Do you have a best friend, Tina?\nD) She is outgoing. She is also very funny.\nE) Yes, I do. Her name is Laura.\nF) Do you get on well with her?", "baslik": "The Dialogue"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5", "6"], "satirlar": [[{"ornek": "C"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}, {"ornek": "B"}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "E", "kabul": [], "aciklama": "İlk soru \"Do you have a best friend?\" olduğu için cevabı \"Yes, I do. Her name is Laura.\" gelir; Laura adı sonraki cümlelerdeki \"she\" ve \"her\" için gereklidir."}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "E cümlesinde Laura tanıtıldı; şimdi \"What is she like?\" diye Laura'nın nasıl biri olduğu sorulur. \"she\", Laura'yı gösterir."}, {"soru": null, "cevap": "D", "kabul": [], "aciklama": "\"What is she like?\" sorusunun cevabı kişiliği anlatır: \"She is outgoing. She is also very funny.\""}, {"soru": null, "cevap": "F", "kabul": [], "aciklama": "Laura anlatıldıktan sonra \"Do you get on well with her?\" sorusu gelir; son cümle B (\"Yes, we do.\") bu sorunun cevabıdır."}], "adlar": [], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan; yanlış ya da boş kutu puan kazandırmaz. Çözüm: önce ilk ve son cümleye bak; sonra soru–cevap çiftlerini bul (\"Do you have a best friend?\" → \"Yes, I do.\"; \"she\" ve \"her\" önceki cümledeki kişiyi gösterir).", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["letters:SARTLI", "spend:KOK"]}}, {"id": "HZ-8-s4d3-02", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "Yes/No sorusu ve düzeltme", "yonerge": "Read the e-mail and answer the questions.", "uyaran": [{"tur": "metin", "metin": "Hi Helen,\nThanks for the invitation to your birthday party on Saturday. I'm sorry, but I can't come because I will visit my grandparents. How about Sunday? Would you like to go to the cinema with me?\nPablo", "baslik": "E-mail"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "Is Helen's party a birthday party?", "cevap": "Yes, it is.", "kabul": ["Yes."], "aciklama": "Metinde \"your birthday party on Saturday\" yazıyor; Helen'in partisi doğum günü partisi. \"Is\" ile başlayan soruya \"Yes, it is.\" diye cevap verilir."}, {"soru": "Can Pablo come to the party?", "cevap": "No, he can not. He will visit his grandparents.", "kabul": ["No, he can't. He will visit his grandparents.", "No, he can not.", "No, he can't."], "aciklama": "\"I'm sorry, but I can't come because I will visit my grandparents\" cümlesi. Pablo partiye gelemez; nedeni büyükanne ve büyükbabasını ziyaret edecek olması."}, {"soru": "Does Pablo want to go to the museum with Helen?", "cevap": "No, he does not. He wants to go to the cinema.", "kabul": ["No, he doesn't. He wants to go to the cinema.", "No, he does not."], "aciklama": "\"Would you like to go to the cinema with me?\" cümlesi. Pablo müzeye değil sinemaya gitmek istiyor."}, {"soru": "Is Pablo sorry?", "cevap": "Yes, he is.", "kabul": ["Yes."], "aciklama": "Metindeki \"I'm sorry\" ifadesi. Pablo üzgün olduğunu söylüyor; \"Is\" ile başlayan soruya \"Yes, he is.\" denir."}], "adlar": ["Pablo", "Helen", "Helen's"], "puanlama": "Alt sorular eşit puanlı. Yes/No cevabı doğruysa ve cevap \"No\" ise doğru bilgi de yazılmışsa tam puan; kısa ya da tam cümle kabul edilir; yazım hatası puan kırdırmaz; yalnız Yes/No doğru ama \"No\" cevabında düzeltme eksikse yarım puan; yanlış cevap ya da boş puan yok. Çözüm: önce e-postayı oku, sonra soruyla ilgili cümleyi metinde bul; bilgi uyuyorsa \"Yes\", uymuyorsa \"No\" yaz ve metindeki doğru bilgiyi ekle.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["e-mail:KOK", "wants:SARTLI"]}, "ornek": "Is the party on Sunday? → No, it is not. It is on Saturday."}, {"id": "HZ-8-s4d3-03", "sinif": 8, "tema": 1, "tema_adi": "Friendship", "kazanim": "E8.1.R2", "zorluk": "orta", "soru_tipi": "zamirin gösterdiği", "yonerge": "Read the invitation. Who or what are these words in the text? Write.", "uyaran": [{"tur": "metin", "metin": "Hi Robert,\nWe will have a concert at my house on Friday evening. My brother Joe plays the guitar, and my best friend Kate will come too. **He** is very good, and **she** is very funny. My aunt makes muffins for the guests. **They** are yummy. Would you like to come? **It** will be fun!\nDan", "baslik": "Invitation"}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "He", "cevap": "Joe", "kabul": ["Dan's brother"], "aciklama": "\"My brother Joe plays the guitar\" cümlesinden sonra gelen \"He is very good\" cümlesinde He, erkek kişi olan Joe'dur."}, {"soru": "she", "cevap": "Kate", "kabul": ["Dan's best friend"], "aciklama": "\"my best friend Kate will come too\" cümlesi. \"she is very funny\" ifadesindeki she, kadın kişi olan Kate'dir."}, {"soru": "They", "cevap": "muffins", "kabul": ["the muffins"], "aciklama": "\"My aunt makes muffins for the guests. They are yummy.\" They, bir önceki cümledeki \"muffins\" kelimesini gösterir."}, {"soru": "It", "cevap": "the concert", "kabul": ["concert", "a concert"], "aciklama": "\"Would you like to come?\" sorusundan önce davet edilen etkinlik \"a concert\"; \"It will be fun\" ifadesindeki It konserdir."}], "adlar": ["Robert", "Joe", "Kate", "Dan"], "puanlama": "Alt sorular eşit puanlı. Kalın yazılı sözcüğün gösterdiği kişi ya da şey doğru yazılmışsa tam puan; yazım hatası puan kırdırmaz; yanlış kişi/şey ya da boş cevap puan kazandırmaz. Çözüm: önce kalın sözcüğün geçtiği cümleyi oku, sonra bir önceki cümlelere bak ve o sözcüğün yerine geçebilecek kişi ya da şeyi bul.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T1 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["makes:SARTLI", "plays:SARTLI"]}}, {"id": "HZ-8-s4d3-04", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "paragraf cümlelerini sıralama", "yonerge": "The sentences are not in the correct order. Write the correct order.", "uyaran": [{"tur": "metin", "metin": "A) In the evening, he watches a film.\nB) Then, he goes cycling with his friends.\nC) At night, he reads a detective book.\nD) On Sundays, Archie gets up early and has breakfast.\nE) In the afternoon, he plays chess with his brother.", "baslik": "Archie's Sunday"}, {"tur": "tablo", "basliklar": ["1", "2", "3", "4", "5"], "satirlar": [[{"ornek": "D"}, {"bosluk": 1}, {"bosluk": 2}, {"bosluk": 3}, {"bosluk": 4}]]}], "cevap_bicimi": "tablo", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": null, "cevap": "B", "kabul": [], "aciklama": "D (kahvaltı) örnektir; kahvaltıdan sonra \"Then, he goes cycling with his friends\" gelir. \"Then\" (sonra) ilk olaydan sonraki adımı gösterir."}, {"soru": null, "cevap": "E", "kabul": [], "aciklama": "Bisikletten sonra öğleden sonra gelir: \"In the afternoon, he plays chess with his brother.\""}, {"soru": null, "cevap": "A", "kabul": [], "aciklama": "Öğleden sonranın ardından \"In the evening\" (akşam) gelir: Archie film izler."}, {"soru": null, "cevap": "C", "kabul": [], "aciklama": "Gün \"At night\" (gece) ile biter: Archie en son detektif kitabı okur."}], "adlar": ["Archie"], "puanlama": "Dört kutu eşit puanlı. Doğru harf tam puan; yanlış ya da boş kutu puan kazandırmaz. Çözüm: önce bütün cümleleri oku; zaman sözcüklerine bak (On Sundays, Then, In the afternoon, In the evening, At night) ve günü sabahtan geceye doğru sırala.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["plays:SARTLI", "reads:SARTLI", "sundays:SARTLI", "watches:SARTLI"]}}, {"id": "HZ-8-s4d3-05", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.R1", "zorluk": "orta", "soru_tipi": "bu cümleyi kim söylüyor", "yonerge": "Read the texts. Who says these sentences? Write the names.", "uyaran": [{"tur": "metinler", "ogeler": [{"kisi": "Maria", "metin": "I am fond of surfing. I go surfing every weekend, and I love it.", "aciklama": ""}, {"kisi": "Peter", "metin": "I am keen on running. I run 10 km every day.", "aciklama": ""}, {"kisi": "Martha", "metin": "I enjoy playing the violin. I play it with an orchestra on Sundays.", "aciklama": ""}, {"kisi": "Melih", "metin": "I like scuba diving. I go diving with my cousin two days a week.", "aciklama": ""}]}], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "\"I go running every day.\"", "cevap": "Peter", "kabul": [], "aciklama": "Peter \"I run 10 km every day\" yazıyor; her gün koşan tek kişi o. \"go running\" ve \"run\" burada aynı anlamda."}, {"soru": "\"On Saturdays and Sundays, I surf.\"", "cevap": "Maria", "kabul": [], "aciklama": "Maria \"I go surfing every weekend\" yazıyor; hafta sonu (weekend) Cumartesi ve Pazar demektir."}, {"soru": "\"I like diving with my cousin.\"", "cevap": "Melih", "kabul": [], "aciklama": "Melih \"I go diving with my cousin\" yazıyor; kuzeniyle dalışa giden tek kişi o."}, {"soru": "\"On Sundays, I make music in an orchestra.\"", "cevap": "Martha", "kabul": [], "aciklama": "Martha \"I play it with an orchestra on Sundays\" yazıyor; \"it\" kemandır (violin). Pazar günleri orkestrada çalan tek kişi o."}], "adlar": ["Maria", "Peter", "Martha", "Melih"], "puanlama": "Alt sorular eşit puanlı. Doğru isim tam puan; isimde küçük yazım hatası kabul edilir. Çözüm: önce dört kısa metni oku, sonra cümledeki bilgiyi metinlerde ara ve o bilginin kime ait olduğunu bul.", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": ["run:KOK", "saturdays:SARTLI", "sundays:SARTLI"]}}, {"id": "HZ-8-s4d3-06", "sinif": 8, "tema": 2, "tema_adi": "Teen Life", "kazanim": "E8.2.W1", "zorluk": "kolay", "soru_tipi": "cümle başlangıçlarını tamamlama", "yonerge": "Complete the sentences about you. Use your own ideas.", "uyaran": [], "cevap_bicimi": "satir", "gorsel": {"dosya": null, "yerlesim": null}, "alt_sorular": [{"soru": "On Fridays, I usually ", "cevap": "watch TV with my family.", "kabul": ["play basketball with my friends."], "aciklama": "\"usually\" sıklık zarfından sonra fiil kökü gelir (watch, play, listen...). Cümle Fridays gününe uygun, kendi etkinliğini anlatır."}, {"soru": "I am fond of ", "cevap": "listening to pop music.", "kabul": ["playing computer games."], "aciklama": "\"be fond of\" kalıbından sonra fiil + ing gelir (listening, playing, reading...) ya da bir isim yazılır (music, sports)."}, {"soru": "I never ", "cevap": "listen to heavy metal.", "kabul": ["watch the news."], "aciklama": "\"never\" (hiçbir zaman) sıklık zarfından sonra fiil kökü gelir; cümle olumlu yazılır: \"I never watch the news.\""}, {"soru": "My friends and I enjoy ", "cevap": "hanging out at the weekend.", "kabul": ["playing chess together."], "aciklama": "\"enjoy\" fiilinden sonra fiil + ing gelir (hanging out, playing, watching...)."}], "adlar": [], "puanlama": "Satırlar eşit puanlı. Öğrenci kendi bilgisini yazar: başlangıca uygun, anlaşılır ve dilbilgisi doğru cümle tam puan; dil hatası belirgin ya da tek kelimelik cevap yarım puan; başlangıca uymayan ya da boş cevap puan kazandırmaz. Anahtardaki cümleler yalnızca örnektir. Çözüm: önce cümle başlangıcını oku, sonra başlangıca uyan kendi bilgini ekle (fiil + ing ya da fiil kökü).", "kelime_kontrol": {"izinli_havuz": "8. sınıf T1-T2 tema sayfaları", "sonuc": "temiz", "kok_sartli": []}, "ornek": "I rarely go to the theatre."}]}];
